/* =========================================================
   第7章 終章 偽神墜堕編 (EP114〜127)
   ---------------------------------------------------------
   開始ラベル: stardust_return
   分岐: B09 (tia_bomb / エリクサーの選択 → ending:bad_paradox)
         B10 (el_confession / 神の処遇   → ending:if_revenge)
   章末: ch08:moonlit_warehouse
   ========================================================= */
VN.registerScenario("ch07", [

  // ===== Scene 1: stardust_return (EP114 星屑の行方) =====
  { label: "stardust_return" },
  { chapter: { no: "終章", title: "偽神墜堕編" } },
  { bg: "alan_forest_night" },
  { bgm: "mystery" },
  { fade: "in" },
  { text: "｜鬱蒼《うっそう》と茂る森の中。夜の森は、不穏な不気味さを醸し出す。" },
  { text: "同時に、どこか懐かしさを感じるそんな風景の中に、俺とクロセルは降り立った。" },
  { chara: [ { slot: "left", id: "yamato_robe", expr: "masked" }, { slot: "right", id: "crocell", expr: "normal" } ] },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "今更こんな所に何の用があるのだ?" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "俺達のやろうとしてる事は世界への反逆だ。そんな事に手を貸してくれる人間が居ると思うか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "居ないだろうな。帝国の強者は軒並みご主人が殺してしまったし" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "あぁ、だから俺達に出来る準備ってのは、人を集める事じゃない。神の喉元に届かせる為の武器を集める事だ" },
  { text: "そう言って、俺は森の中を歩き出す。" },
  { text: "因みに、俺とクロセルは全身を黒いローブで覆っている。白い仮面まで付けた完全防備だ。" },
  { text: "そうしている理由は当然、俺が王国、帝国、教国において全面指名手配中だから。俺の素顔は既に割れている。だからこうして身を忍ばせる必要があるわけだ。" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "まぁ、見付かった所で捕まえられるとは思えないが、ラオンの仕事を増やすのも悪いしな" },
  { text: "薄々お気付きの方も多いと思うが、ここは王国だ。王国領の辺境部に位置する村。その名も……" },
  { bg: "tarf_town_night" },
  { bgm: "daily2" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "帰ってきたな、タルフの村に" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ、こうして二人で来ると感慨深いな" },
  { text: "俺達は森を抜け、町の中に足を踏み入れる。そう、俺達の旅が始まった場所。タルフの村だ。相変わらずというか、街並みに変化はない。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それで、今更ここに何の用があるのだ?" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "要件は二つある。ま、まずは簡単な方からだな" },
  { text: "俺は慣れた足取りで、町の中を歩く。森の中から、あの場所に向かう道は何度も歩いた。手に入れた薬草を持って。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、まさか……" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "まさかも何も、見ての通りだ、あいつに借りを返してもらおうと思ってな" },
  { text: "俺はある所で足を止める。夜の闇でも分かる、古びた異質な家屋。星屑屋、と呼ばれている薬屋だ。俺はここの主人に用がある。" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "……鍵が掛かってるな" },
  { text: "当然というかなんというか。扉は固く｜施錠《せじょう》されていた。" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "クロセル、開けろ" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "普通に不法侵入だが良いのか……?" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "お前がそういう事気にするようになったのか、成長したな" },
  { text: "前だったら逆だった。クロセルが強引に鍵を開けようとして、俺が止める。今はクロセルも丸くなったし、俺は記憶を取り戻して少々過激な思想に染まった。なんだかおかしくて、俺はくすくすと笑いを浮かべる。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それで、どうするのだご主人" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "素直にノックしよう" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "その手があったか!" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "やっぱお前変わってねーわ" },
  { text: "目から鱗だとばかりに瞳を輝かせるクロセルに愛の拳を放って、弾かれる。そして、俺は少し強めにドアをノックした。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、本当にここに居るのか……?ステラは確か……" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "俺の記憶が正しければ、クロセル奪還の際にここを離れ、後は魔王に仕えていた、んで魔王の間の前で再開して……" },
  { fade: "out" },
  { comment: "―― 回想: 魔王城・玉座の間前 (EP114)" },
  { bg: "maou_castle", instant: true },
  { bgm: "mystery" },
  { fade: "in" },
  { hide: "all" },
  { pov: { name: "ヤマト", color: "#BDC3C7" } },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "right", id: "stella", expr: "normal" } ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "久しぶりだな、ステラ" },
  { name: "ステラ", who: "stella", expr: "normal" , text: "えぇ、お久しぶりです。ヤマトさん、クロ様" },
  { text: "俺とクロセルが最後の準備。ラプラスなりすまし作戦をしている途中の事。玉座の間の前の部屋に、彼は現れた。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まだ皇帝の奴に仕えてたのか" },
  { name: "ステラ", who: "stella", expr: "normal", text: "えぇまぁ、ボクも命は惜しいですから" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "安心しろ、皇帝……魔王は俺が封印してやる" },
  { name: "ステラ", who: "stella", expr: "normal", text: "そうですよね、ヤマトさんが此処に来たって事は、そうなると思ってました" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺達を止めるか?" },
  { name: "ステラ", who: "stella", expr: "normal", text: "いいえ?逆ですよ、ボクはヤマトさんに協力する為に此処に居たんです、来るべき時に備えて、ね" },
  { text: "ステラは笑ってそう告げると、俺に向かって一本の瓶を差し出す。中には透き通るような爽やかな青い液体が詰められている――｜封能薬《ふうのうやく》だ。" },
  { name: "ステラ", who: "stella", expr: "normal", text: "｜封能薬《ふうのうやく》です、素材をアレンジしたのでちょっと色は違いますけど、効能はおおよそ一緒です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "良いのか?皇帝はお前の恩人なんだろ" },
  { name: "ステラ", who: "stella", expr: "sad", text: "確かに……エルク様は悪い人じゃなかった、ボクを拾ってくれたあの頃のエルク様は。でも今は変わってしまった、だからボクは、間違った道に進むエルク様を止めなければならない。それが僕に出来る、唯一の恩返しだから" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "……なるほどな、承った。任せとけ、俺達が魔王を止めてやるよ" },
  { name: "ステラ", who: "stella", expr: "normal", text: "ありがとう、それでは幸運を祈ってます。また会いましょう、願わくば今度こそは友人として" },
  { text: "そう言って深くお辞儀をすると、ステラは小走りで魔王城の奥へと走って行った。" },
  { fade: "out" },
  { comment: "―― 回想終わり" },
  { pov: null },
  { bg: "stardust_shop_night", instant: true },
  { bgm: "daily2" },
  { fade: "in" },
  { hide: "all" },
  { chara: [ { slot: "left", id: "yamato_robe", expr: "masked" }, { slot: "right", id: "crocell", expr: "normal" } ] },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "また会おう、って言葉が確かならば、居るはずだ" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "だとしても……わざわざタルフの村に戻ってくるか?" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "……そこは賭けだな、｜尤《もっと》も、大して期待はしてないから良いんだが" },
  { text: "こんな風に｜駄弁《だべ》っていても、中々星屑屋の店主は出てこない。この様子だとやはり居ないのか……そう思って俺は扉に背を向ける。" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "……行くか" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "待てご主人、探査魔術を使った所、内部に生命反応がある" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "よし、扉を破壊しろクロセル" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "命令するでない、鍵だけ破壊するがよいか?" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "それでもいい" },
  { se: "magic" },
  { text: "クロセルが短く詠唱すると、ぽん、という気味の良い音と共に、鍵穴から煙が出てくる。破壊行為にしてはかなり静かだ。これなら近所迷惑にはならないだろう。" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "お、開いたな" },
  { text: "ドアノブに手を掛けて、軽く引くと、扉はごく普通に開く。これで立派な不法侵入なのだが、俺は臆する事なく中に足を踏み入れた。" },
  { text: "店内は相変わらず片付いてない。大量の植木鉢やら壺やら本棚やらで迷路のようになっている。一応店なんだよなここ?" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "っと……やっぱりか" },
  { text: "奥に進むと、丸机に突っ伏して寝ている少年の姿を確認する。既視感とはこのことか。そう言えば最初に星屑屋に来た時も、不法侵入してこいつが寝てたっけ。" },
  { text: "という訳で、今回はこいつに用事がある。気持ちよく寝てる所悪いが、起きて貰おう。" },
  { text: "肩を優しく揺さぶると、直ぐに目を覚ます。そして、｜虚《うつ》ろな視線が宙を泳ぎ、俺とクロセルを見て停止する。" },
  { chara: { slot: "center", id: "stella", expr: "sleepy" } },
  { name: "ステラ", who: "stella", expr: "sleepy", text: "ボクは誰?貴方はステ……" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "それもう良いから" },
  { name: "ステラ", who: "stella", expr: "surprised", text: "……ほんとに誰ですか!?強盗!?ボクの店に金目の物なんて無いですよ!?" },
  { text: "ステラは飛び起きると、両手で待ってのポーズをしながら、あたふたと目を回す。何故だ?と少し考えて理解する。そう言えば俺達変装してたな。" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "あぁ、悪い。これで分かるか?" },
  { text: "フードを脱ぎ、不気味な白い仮面を外す。クロセルも俺に続いて同じように変装を解いた。" },
  { chara: { slot: "left", id: "yamato", expr: "normal" } },
  { name: "ステラ", who: "stella", expr: "normal", text: "ヤマトさん……とクロさん?はふぅ……びっくりしました" },
  { text: "俺とクロセルの存在を認識すると、安堵したように溜息を吐いて、嬉しそうな笑みを浮かべる。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まさか本当にここに居たとはな、指名手配……ではなかったな、お前は死んだ事になってる" },
  { name: "ステラ", who: "stella", expr: "normal", text: "はい、こうして戻って来れたのもアカツキさんのお陰です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それで、本題なんだが" },
  { name: "ステラ", who: "stella", expr: "normal", text: "ボクの所に来たという事は、そういう事ですよね。任せて下さい。力になりますよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、助かる。因みに目的は神を殺す事だ、協力してくれるな?" },
  { name: "ステラ", who: "stella", expr: "normal", text: "えぇ、もちろんです。ん……え?誰を殺すって言いました?セミ?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "神だよ、教国に居る" },
  { name: "ステラ", who: "stella", expr: "surprised", text: "本気ですか?どう考えても魔王よりやばい相手ですけど……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ、やるしかないんだよ。神の為にな" },
  { name: "ステラ", who: "stella", expr: "sleepy", text: "神の為に神を殺す?あはは……ボクちょっと頭がこんがらがってきました" },
  { text: "ステラは頭を押さえて小さく笑う。まぁ、混乱するのも無理はない。" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "ご主人の説明が悪いな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "うるさい、話すと長くなるんだよ、取り敢えず｜封能薬《ふうのうやく》と身体強化薬、あとゲーテに殺されかけた時に使ってた傷を治す薬も、用意できるか?" },
  { name: "ステラ", who: "stella", expr: "serious", text: "｜封能薬《ふうのうやく》は神の｜権能《けんのう》には効果がありませんが……良いんですか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "｜権能《けんのう》について知ってるのか?" },
  { name: "ステラ", who: "stella", expr: "normal", text: "えぇまぁ、エルク様から色々と聞いてはいるので……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "勇者や教皇も相手にする事になるからな、持っていて損は無い" },
  { name: "ステラ", who: "stella", expr: "serious", text: "分かりました、あと｜超再生薬《エリクサー》に関してなんですが……あれは魔法薬の才能が無いと使えないんですよね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "それなら問題ない、俺が使える" },
  { text: "一回だけなら、と心の中で付け加えておく。ステラの方は、当然驚いたような反応を返してくる。" },
  { name: "ステラ", who: "stella", expr: "surprised", text: "えっ!?そうだったんですか!?あの……才能指数で効果が変わるんですけど……ボクは『魔法薬8』なので致命傷一歩手前くらいなら治せます" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なら俺なら致命傷でも治せそうだな、幾つ用意出来る?" },
  { name: "ステラ", who: "stella", expr: "normal", text: "｜封能薬《ふうのうやく》3本、身体強化薬4本、超再生薬1本ですかね……どれも貴重な素材と作製に時間が掛かる代物なので量産は出来なくて……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "十分だ、助かる" },
  { name: "ステラ", who: "stella", expr: "normal", text: "では用意するので待ってて下さい" },
  { text: "ステラは立ち上がると、店の奥へと消えていく。狭い部屋に取り残された俺とクロセル。取り敢えず一つだけ椅子があるので俺は座らせて貰った。" },
  { hide: "center" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ステラの奴、いつもここで座って寝てるがベッドとかないのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "身体を痛めそうだが、大方、ベッドを置けるスペースが無いのだろう" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "少しは片付けろよ……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "我の研究室もこんな感じだったぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば、ステラの才能ってどうなんだ?調合と魔法薬は分かるんだが才能指数は知らないんだよな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "『錬金術3』『調合9』『魔法薬8』だな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あいつも大概の規格外じゃねぇか……妖精か転生者かと疑うレベルだ……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人の才能に比べると霞んで見えるがな……" },
  { text: "そんな風に話しながら十数分程度待っていると、奥からステラが戻ってくる。手には箱を持っており、中には色の違う三種類の薬瓶が入っている。" },
  { chara: { slot: "center", id: "stella", expr: "normal" } },
  { name: "ステラ", who: "stella", expr: "normal", text: "お待たせしました" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "早かったな、それが例の?" },
  { name: "ステラ", who: "stella", expr: "normal", text: "はい、青色が｜封能薬《ふうのうやく》、黄色が身体強化薬、赤色が超再生薬です" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "分かりやすいな" },
  { name: "ステラ", who: "stella", expr: "normal", text: "着色してますからね、本来は深緑とか茶色なんですけど" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まずそうだな" },
  { name: "ステラ", who: "stella", expr: "normal", text: "良薬とは苦い物ですから" },
  { text: "俺は箱を受け取ると、片手でステラの頭を撫でる。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ありがとな、これで借りは返してもらった" },
  { name: "ステラ", who: "stella", expr: "normal", text: "あはは……利害関係が無くても、ボクはヤマトさんに協力しますよ" },
  { text: "相変わらずの｜無垢《むく》な笑顔を浮かべる。これで男じゃなければ……" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人?何か変な事を考えてないか?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "心を読むな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "顔に出てたぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "顔色を読むな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "無茶苦茶だが……それとステラは……いや、言わないでおこう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんだよ、気になるな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "大した事じゃない、それに他にも用事があるのだろう?急がなくて良いのか?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうだったな、取り敢えずステラ、改めてありがとう、薬は有効活用させて貰う" },
  { name: "ステラ", who: "stella", expr: "normal", text: "はい!ヤマトさんとクロ様もお気を付けて" },
  { text: "俺が席を立つと、ステラが深くお辞儀をして見送ってくれる。それに後ろ手で手を振りながら、狭い廊下を進み、店を出る。こうして俺とクロセルは、星屑屋を後にした。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 2: hagenti_reveal (EP115 力の根源) =====
  { label: "hagenti_reveal" },
  { bg: "alan_forest" },
  { bgm: "mystery" },
  { fade: "in" },
  { chara: [ { slot: "left", id: "yamato_robe", expr: "masked" }, { slot: "right", id: "crocell", expr: "normal" } ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、やっぱりこの格好は逆に目立つと思うのだが……" },
  { name: "ヤマト", who: "yamato_robe", expr: "masked", text: "俺達だとバレなきゃそれで良いんだよ" },
  { text: "クロセルの指摘通り、めちゃくちゃ目立って指を刺されながらも、素性がバレる事は無く、なんとか村を出る。確かに自警団に見つかって職質でもされたらヤバかった。運が良かったと思おう。" },
  { text: "そして現在位置だが、俺達が降り立った森と村を挟んで反対側に位置する広大な森林地帯。こっち側の森には魔物も出る為、タルフの村の人間はあまり近付かない場所だ。尤も、近付かない理由は魔物だけではないのだが。" },
  { chara: { slot: "left", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺の記憶が正しければこっちであってるんだが……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人の目指している場所は分かったのだが……こちらも今更何の用事があるのだ……?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "上層でエルと殺し合った直後から、アランの森の湖で溺れかける間の記憶が欠落している、その理由を探りにな" },
  { text: "そう、シェル公に記憶を復元して貰った後も、欠落した記憶がある。シェル公の記憶操作は完璧だった。記憶操作の才能を使った事のある俺だから分かる。だからおかしい。" },
  { text: "いや、分からない訳じゃない。推測は出来ている。後は仮説が正しいか証明するだけ。その為に俺はここに来たのだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あった……アランの森の、大結界だ" },
  { text: "天高く聳え立つガラスのような壁。これが、アランの森を守る結界だ。アランの森は禁足地、アランの民以外が足を踏み入れる事は禁じられている。それは当然タルフの村の人間も承知であり、故にここに近付く物好きは居ない。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "結界を破壊するのか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや、その必要は無い" },
  { text: "クロセルの言葉を背に受けながら、俺は結界へと歩み寄る。片手を伸ばし、近付き、そして……" },
  { fx: "flash" },
  { text: "――俺の手は結界を突き抜けた" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……やっぱりか" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "なっ、ご主人!?どういう事だ!?" },
  { text: "クロセルが驚きの声を漏らす。そして、俺を真似て結界に近付き、その手を伸ばすが……" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "っ!?何故だ?" },
  { text: "ばちん、と電撃が走るような音と共に、クロセルの手は結界から弾かれる。つまり、結界は正常に機能している。何故か俺はその影響を受けない。憶測は確信に変わった。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、此処で待ってろ" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "説明を要求するぞ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺も分からないんだ、全てが分かったら後で説明する" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "うぬぬ……分かったぞ……だがご主人一人で大丈夫なのか?前回と違って今回は完全に領域への侵入だ、前のように｜極刑《きょっけい》に処される可能性も……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "安心しろ、あの時と違って俺には才能の解放がある、それに俺を殺したらクロセルがお前らを皆殺しにするとでも言えば手は出せない筈だ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そうか……気を付けるのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ" },
  { text: "俺は薬の入った箱をクロセルに渡すと、そのまま結界の中へと足を踏み入れる。文字通りの意味で、足が結界を通り抜け、そのまま全身が結界を通り抜ける。やはり俺はこの結界の\"例外\"らしい。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……今日こそは説明して貰うぞ" },
  { text: "クロセルに聞こえないように、俺は小さく呟いた。広大な森だ。小さなアランの村を見付けるのはとても難しい。森を進む。道は覚えていないが、何故かこっちだという直感があった。" },
  { fade: "out" },
  { bg: "alan_village_morning", instant: true },
  { fade: "in" },
  { hide: "all" },
  { text: "ここだ、と口をついて出た言葉。それは俺の物だったか。或いは。夜が明ける。太陽の光が少しずつ視界を照らしていく。目の前に広がっていたのは、茅葺屋根の家が立ち並ぶ古風な村。アランの村だ。" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { text: "懐かしさや感慨に浸っていると、怒気の籠った声が投げかけられる。結界は長老により厳重に管理されている、侵入者が居れば、直ぐに分かる。だから俺自らが出向くまでも無く、丁重に出迎えて貰えるようだ。" },
  { name: "村人", text: "誰だ!" },
  { name: "村人", text: "って……貴様は!?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……誰だ?会った事あったか?" },
  { name: "村人", text: "俺がお前をタルフの村まで案内しただろ……って、なんでまた来たんだ、今度こそ言い訳出来ないぞ?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "長老に話がある、なに、手荒な真似はしない。対等に対話をさせて貰えればそれで良い" },
  { name: "村人", text: "……身柄を拘束するが構わないな?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "言っておくが、俺を殺したりしたら｜魔杖《まじょう》クロセルがアランの民を滅ぼすからな、扱いには気を付けろよ" },
  { name: "村人", text: "全く……君は変わらないな……" },
  { text: "俺を見付けた男は、呆れたように溜息を吐くと何処からかロープを取り出し、俺の身体を拘束する。黒髪に真っ白い肌。今なら分かる。アランの民とは魔族だ。かつて魔王に仕えていた一族の一つ。" },
  { text: "それが、何故か魔王フォーカスに滅ぼされかけ、何故か生き残った。クロセルの話から、何故そういう経緯になったのかは推測できる。" },
  { text: "と、そんな風に考えていると、いつもの集会所に辿り着く。" },
  { name: "村人", text: "ここで待っていろ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あいよ、長老には｜魔杖《まじょう》クロセルの件とでも伝えてくれ" },
  { name: "村人", text: "分かった" },
  { text: "男が去っていく。早朝という事もあって、ここに来るまでに殆ど人とは会わなかった。俺を湖から引き揚げてくれたあの兄妹。元気にしてるだろうか。というかそもそも生き延びてくれただろうか。今回の対話が穏便に済めば、また会えるかもしれない。" },
  { text: "そうしたら改めてお礼を言わないとな、なんて思いつつ待つ。暫くすると奥から老齢の爺が現われ、椅子に腰かける。そして、こいつもあからさまに大きな溜息を吐いた。" },
  { name: "長老", text: "……また貴様か。何故再び訪れた、ここには二度と近付くなと言った筈なのだが" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "久しぶりだな、長老さん" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "｜魔杖《まじょう》クロセルの封印は解かれた、もうお前達が隠れて生きる必要は無いんだ" },
  { name: "長老", text: "……何の事だ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "すっとぼけるなよ爺さん、アランの民ってのは、｜魔杖《まじょう》クロセルを守る為の一族だ、そうだろ?" },
  { name: "長老", text: "部外者の貴様に話すことなどない" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "部外者?あぁまぁ、確かに\"俺\"は部外者だ、だが当事者でもある" },
  { name: "長老", text: "どういう事だ?" },
  { text: "俺はふっと小さく笑う。そして告げた。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "もう良いだろ、出て来いよ、魔王様?" },
  { se: "magic" },
  { fx: "flash" },
  { text: "俺がそう呟いた瞬間、俺の身体から紫色の光が放たれる。場所は胸、心臓部。その光は徐々に強さを増していき、同時に俺の意識が宙に浮いたように不安定になる。俺は意図的に、意識の手綱を手放した。主導権は俺から、他の何かへと変わる。" },
  { fx: "shake" },
  { text: "光はゆっくりと消え失せ、途端、俺の纏う気配が変わる。それはまるで別人のような。事実、別人の物だ。そして、俺の身体を借りたその人物は、ゆっくりと口を開いた。" },
  { chara: { slot: "right", id: "hagenti", expr: "normal", ghost: true } },
  { name: "？？？", who: "hagenti", expr: "normal", text: "僕だ。\n――48代魔王ハーゲンティと言えば通じるかな?" },
  { name: "長老", text: "ハーゲンティ様!?ですが……貴方の｜魔魂結晶《まこんけっしょう》は勇者に破壊されたはず……どうして……" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "あぁ、訂正だ。正確にはハーゲンティの意志の才能が自我を持った物、と考えて貰えるかな" },
  { name: "長老", text: "才能が自我を持つ?" },
  { name: "ハーゲンティ", who: "hagenti", expr: "serious", text: "あぁ、才能指数10の力は、一つの人格すらも形成する、神の力なんだ、おかしな話じゃないだろう?" },
  { name: "長老", text: "では……その身体は" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "才能である僕が力を発揮するには｜依り代《よりしろ》となる肉体が必要だ、だから僕は今まで、何人もの人間の肉体を渡り歩いてきた" },
  { name: "長老", text: "その男が、ハーゲンティ様の｜依り代《よりしろ》だと?" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "そういう事だね、ヤマト君は僕と長老を会わせる為に此処に来てくれたんだよね" },
  { text: "朧げに聞こえていた声が鮮明になる。意識が浮上し、肉体の主導権を取り戻す。いや、正確には半分だけだ。今この肉体の主導権は二つの人格が同時に握っている。" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { text: "取り敢えず、話せ、という意思表示だと受け取り、俺は声を発した。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "こうでもしないと、お前は出て来てくれないと思ったからな" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "あはは……確かにそうだね、今まで隠していてごめんね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "気持ちは分かる、クロセルに知られたくなかったんだろ?" },
  { name: "ハーゲンティ", who: "hagenti", expr: "sad", text: "まぁ……それもあるよ、彼女を過酷な運命に誘ったのは他でもない僕だ、会わせる顔が無い" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほどな、それで……諸々の説明は貰えるんだよな?" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "構わないけど、少し条件がある。君の仲間達の前で僕の名前を出さない事だ、魔王ハーゲンティ、出来るね?" },
  { name: "ヤマト", who: "yamato", text: "分かった" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "よし、それじゃあ話すとしよう、長老、良いですか?" },
  { name: "長老", text: "ハーゲンティ様が宜しいのでしたら……" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "ありがとう、じゃあまずはアランの民についてだ" },
  { text: "そして、魔王ハーゲンティの意志の才能は語り始める。魔王ハーゲンティの｜悲願《ひがん》。それは世界征服でも世界平和でも無かった。それは……" },
  { fx: "shake" },
  { text: "――神を殺すこと" },
  { text: "正確には、偽物の神、エルを殺す事だった。その理由は俺と同じ。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "シンシアの啓示?ってことは……ハーゲンティ、お前……まさか" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "そのまさかだよ。僕は地球からの転生者だ。そしてこの世界を救う為、魔王を討ち、魔王になった" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "啓示を受けたのは俺とお前だけ、つまり才能指数10の持ち主がシンシアの試行錯誤の成功例って事か" },
  { name: "ハーゲンティ", who: "hagenti", expr: "serious", text: "僕が神を殺そうとしてるのは啓示だけじゃない、あの神が他でもない魔王を生み出した存在なんだ、僕は魔王という存在が憎い。正確に言えば、魔王というシステムが憎いんだ。だからそれを作った神を殺し、魔王システムをこの世界から消し去ろうとした" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "んで失敗した訳か" },
  { name: "ハーゲンティ", who: "hagenti", expr: "sad", text: "あぁ、そうだよ、僕は失敗した。僕だけの力じゃ神には届かなかった、そして同時に、僕には時間が無かった。勇者による魔王討伐の開始までに、僕が出来る事は" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "クロセルを後世に残すことだった、と" },
  { name: "ハーゲンティ", who: "hagenti", expr: "sad", text: "そうだ、僕は彼女を魔王にして力を与え、討たれた後の魔魂結晶から杖が作られる事までを想定し、その杖を奪還、保護する為の準備をした。その結果生まれたのが……\n――アランの民だ" },
  { text: "長老が口を挟む。" },
  { name: "長老", text: "我々はハーゲンティ様に言われた通り、莫大な犠牲を払い魔王フォーカスから｜魔杖《まじょう》クロセルを奪取、それを保護する為に聖域に封印していたのです" },
  { name: "ハーゲンティ", who: "hagenti", expr: "sad", text: "そう、来るべき時が来るまで、封印するつもりだった、それが彼女に途方もない苦痛を与える事になるのは承知の上で、だ。だが、計画は早まった" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "本来はクロセルが目覚めるのはもっと後の筈だった、と?" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "その通りだ、だが、僕は計画を変更した。君というイレギュラーの発生をきっかけにしてね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いつから目を付けてたんだ" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "上層で君が神と戦った時だよ、僕は神の動向を常に伺っていた。だから君と神の戦いも見ていた。君は全ての才能を才能指数10で持つ、規格外だ。君なら神を殺せる、と思った" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "封印された才能を解放する力、それ……お前のお陰なんだろ" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "そうだよ、上層で、僕は君の身体を借りて戦った。その時に解放した傷害の才能、それが君の最初のディザビリティだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……なるほどな、繋がったよ" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "才能封印を受けた君では神に勝てない。だから｜魔杖《まじょう》クロセルを解放する必要があった。僕は君の身体をアランの森まで運び、結界を超えて湖に潜った" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "んで、その途中で俺が目を覚まして、身体の主導権を奪われた訳だ" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "そういう事だね、色々と計画とは違う過程になったが、結果としては上々だ、君はよくやってくれた" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセルの魔力も、クロセルが加護の影響を受けないのも、アランの森の結界を通れたのも、アランの民がフォーカスに滅ぼされなかったのも……" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "全部、僕の仕業だよ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "意志の才能……なんでもありかよ……" },
  { text: "だが待てよ?俺の存在は計画外の存在。本来の計画では、ハーゲンティはどうやって神を殺そうとしてたんだ?" },
  { name: "ハーゲンティ", who: "hagenti", expr: "normal", text: "じゃあ本題だ、わざわざヤマト君がお膳立てしてくれたからね、このチャンスは有難く受け取らせてもらうよ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そりゃ良かったな" },
  { text: "理解から生まれた安堵を覚えると同時に、俺は大きな溜息を吐いた。そして魔王ハーゲンティ、の意志の才能は、長老へと向き直る。" },
  { chara: { slot: "right", id: "hagenti", expr: "sad", ghost: true } },
  { name: "ハーゲンティ", who: "hagenti", expr: "sad", text: "長老、アランの民を代表して僕の言葉を受け取って欲しい。700年間、今までクロセルを守ってくれてありがとう、そしてもう良い、もう良いんだ……結界を維持する必要は無い、君達の役目は終わった、この森に縛られず、自由に生きて良いんだ" },
  { name: "長老", text: "ハーゲンティ様……ありがたきお言葉……これでアランの民は報われます" },
  { text: "長老は地に付くほど深く深く頭を下げる。こいつらにとってそんなやばい存在なのか、こいつ。というか関係ない俺に向けて頭を下げられてるみたいでなんか複雑だな。" },
  { name: "ハーゲンティ", who: "hagenti", expr: "serious", text: "では僕は失礼するよ、君の目的は僕の悲願だ、必ず、神を殺してくれ" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かった、もう行くのか……本当にクロセルに会う気は無いんだな" },
  { name: "ハーゲンティ", who: "hagenti", expr: "sad", text: "少なくとも、目的が果たされるまでは……ね、それに彼女の主人はもう僕じゃない、ヤマト君、君なんだ" },
  { hide: "right" },
  { text: "そう言って、俺の身体から気配が消え失せる。本当に俺の身体に入ってるのか分からないほどに、普通だ。後遺症もなんもなし、記憶もしっかりある。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ハゲの奴はああ言ってたが、魔族であるお前らに居場所が無いのは事実だからな、無理する必要は無いぞ" },
  { name: "長老", text: "その通りだ。故に我々は此処から離れるつもりはない、これからも結界を維持し、静かに暮らしていくつもりだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それが良い、んで……ちょっとしたお願いがあるんだが良いか?" },
  { name: "長老", text: "お前にはハーゲンティ様を連れてきてくれた恩がある、言ってみろ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "この村に釣りが得意な少女は居ないか?うろ覚えだが……確か才能指数は6だったか" },
  { name: "長老", text: "シオンの事か?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "名前は知らん、取り敢えずそういう奴が居るってなら会わせてくれ" },
  { name: "長老", text: "うむ、分かった、連れてこさせよう" },
  { text: "長老が一つ頷いて、俺の後ろの方に立っていたアランの民を手招きすると、少し言葉を交わし、その男は長老にお辞儀をすると直ぐに集会場を出ていく。" },
  { text: "ハゲ……もとい魔王ハーゲンティ様を呼び捨てにした俺に、長老は一瞬眉をひそめたが、何も言わなかった。それから十数分程度待っていると、集会場に二人の人物が現れる。一人は青年、もう一人は幼い少女。あぁ、良かった。生きていたか。" },
  { chara: { slot: "center", id: "yamato", expr: "smile" } },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よう、久しぶりだな" },
  { name: "ウジェド", text: "貴様……どうやって此処に来た" },
  { name: "長老", text: "これ、ウジェド、彼は大切なお客様だ。言葉は慎むように" },
  { name: "ウジェド", text: "……そうなのですか?長老" },
  { text: "兄妹の兄の方。ウジェドと呼ばれた青年は困惑した様子で俺と長老を交互に見る。一方、妹の方は不思議そうな顔で俺を見つめていたかと思うと、思い出したかのように目を見開いて声を出した。" },
  { name: "シオン", text: "湖で溺れてたヤマトお兄ちゃん!無事だったのね!" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうだ、あの時は世話になったな" },
  { name: "ウジェド", text: "魔物に殺されたかと思っていた" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺もお前ら二人が魔物に殺されたんじゃないかと思ってた、無事で良かったよ" },
  { text: "相変わらず愛想のよくない兄と、俺に警戒心を欠片も抱かない無邪気な妹。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "お前ら二人に感謝を言いたくてな、この世界に来た時……いや正確には違うんだが、まぁ湖で溺れてた俺を助けてくれてありがとう" },
  { name: "シオン", text: "どういたしまして!" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "名前を聞いても良いか?" },
  { name: "ウジェド", text: "私はウジェド、こっちは妹のシオンだ" },
  { name: "シオン", text: "改めて宜しくね!ヤマトお兄ちゃん!" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、宜しくな" },
  { text: "太陽のような笑みを浮かべるシオンに、俺も小さく笑って返す。また来る事もあるだろう。もうアランの民は何も守らなくて良いのだから。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "また来るよ、とか言ったら怒るか?" },
  { name: "ウジェド", text: "長老の言葉が確かなら、お前は例外なんだろう、歓迎……は出来ないが、出て行けとは言わないさ" },
  { name: "シオン", text: "また来てね!ヤマトお兄ちゃん!" },
  { text: "反応は様々だが、来るなとは言われなくて安心した。全てが終わったら、また来よう。今度はクロセルや、仲間達も連れて。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "じゃあ俺はこの辺で失礼するよ、朝早くに悪かったな" },
  { name: "長老", text: "我々も、変わるべき時なのかもしれないな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうだな、そこから先はお前たちの問題だ、俺は何も言わないが、頑張れよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……おい、誰かこの縄解け" },
  { name: "シオン", text: "あはは、ヤマトお兄ちゃん、今まで忘れてたでしょ" },
  { text: "シオンに笑われた。だって誰も指摘してくれないんだもん。長老の指示で現れたアランの民に縄を解いてもらい、今度こそ集会場を後にする。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よし、戻るか、クロセルを待たせてるからな" },
  { text: "俺は一人呟いた。或いは中のハゲに聞こえるように。そして、心地よい朝の空気を浴びながら、俺は村を出て、結界のある場所へと向かった。" },
  { fade: "out" },
  { hide: "all" },

  // ===== 追補: ep116_reunion (結界の外・クロセルとの合流) =====
  { label: "ep116_reunion" },
  { bg: "alan_forest", instant: true },
  { bgm: "daily" },
  { fade: "in" },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "right", id: "crocell", expr: "angry" } ] },
  { name: "クロセル", who: "crocell", expr: "angry", text: "遅い!ご主人、いったい中で何をしていたのだ!我は心配で気が気でなかったのだぞ!" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "悪い悪い、ちょっと長話になってな" },
  { text: "結界を抜けて戻ると、クロセルが頬を膨らませて待っていた。預けておいた薬の箱を、大事そうに胸に抱えたまま。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……で、約束はどうなった。全てが分かったら説明すると言ったではないか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、約束だったな" },
  { text: "俺は森の中を歩きながら、当たり障りのない範囲で事情を話す。アランの民が｜魔杖《まじょう》クロセルを守る為の一族だった事。結界を通れたのは、俺がこの地と縁のある\"例外\"だった事。ハゲの正体だけは、約束通り伏せておいた。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "……なるほどな。我の故郷、か。複雑な気分だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "全部終わったら、また来よう。今度はゆっくりとな" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ!約束だぞ、ご主人!" },
  { text: "クロセルが嬉しそうに笑う。その笑顔を守る為に、俺は神を殺す。改めてそう心に誓いながら、俺達は王国を後にした。次に向かうは、決戦の地・聖都アルカディア。最後の準備を整える為に。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 3: gremory_pact (EP116 炎の魔女) =====
  { label: "gremory_pact" },
  { bg: "sen_mansion" },
  { bgm: "suspense" },
  { fade: "in" },
  { text: "王国から帰還し、一日の休息を挟んだ後、俺達はセン公の屋敷にて作戦会議をしていた。当然とも言えるが、セン公とエスクは居ない。屋敷は勝手に使っていいから後は好きにしろって感じらしい。" },
  { text: "机の上には瀬野の用意したフリントロック式の拳銃と閃光手榴弾、そしてステラの薬箱が並ぶ。" },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "center", id: "akatsuki", expr: "normal" }, { slot: "right", id: "zeno", expr: "normal" } ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それでは作戦を説明する、いいか、これは命令ではない、断じて命令では無いから心して聞くように" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "それ相変わらず厄介なディザビリティですよね" },
  { text: "アカツキが呆れたような声色で冷静に突っ込む中、俺は至って真面目に話を続ける。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その前に成果報告だ、アカツキ、例の物は" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "MMですか?ダメですね、一応掛け合ってはみましたが、持ち出すのはNGだそうで" },
  { name: "クロセル", text: "あれがあれば我の使える魔術の幅が大きく広がるから出来れば手に入れたかったな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、まぁ無い物は仕方ない、次だ、瀬野" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "ここだとパーツが足りなくて大した物は作れなかったけど、拳銃と手榴弾は用意出来た" },
  { text: "そう言って、瀬野は机の上に｜二挺《にちょう》の拳銃と紙に包まれた弾薬、筒にピンの付いた手榴弾を三つ置く。" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "フリントロック式の単発拳銃、有効射程は短いけど最後の｜悪足掻《わるあが》き程度には使えると思う" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "シェル公とアカツキ用だな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私は魔術でも攻撃出来るので必要かは分かりませんが……" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "だよね……手榴弾の方は閃光手榴弾……って言えば伝わるかな、音と光で視覚と聴覚にダメージを与える兵器だよ、仮想敵はニコラスさん" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、確かにあいつを突破するのは｜搦め手《からめて》を使わないときついな" },
  { text: "瀬野には殺傷性の低い武器を注文しておいた。拳銃は十分な殺傷性を秘めてるが、急所に当たらない限りは魔術で簡単に治療出来る。ぶっちゃけクロセルの魔術の方が殺傷性は高い。この拳銃よりも威力の高い水弾をマシンガンの如く連射出来るのだから。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺達の方の収穫はこれだな" },
  { text: "そう言って俺は机の上に薬の入った木箱を置く。中には三種類の薬が数本ずつ瓶詰めされて入っている。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "シェル公は近接戦闘の心得はあるか?" },
  { name: "シェル公爵", who: "shellmi", text: "知識としては持っているさ。ただ、戦闘系の才能は持ち合わせていないがな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なら身体強化薬は俺とシェル公と瀬野とアカツキで一本ずつだな、効果時間は長く無いから使いどころは見極めろよ" },
  { name: "クロセル", text: "基本的には我が身体強化魔術を使うから必要ないとは思うがな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "万が一もあるだろ、念入りに準備しとくに越した事は無い" },
  { text: "俺は挙げたメンバーに身体強化薬を渡す。｜封能薬《ふうのうやく》と超再生薬とやらは俺が持っておく事になった。これで装備の確認は概ね済んだ。残るは、戦力の問題だ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "正直、前衛が足りない。ニコラスとエルが居なくなった今、頭数が心許ないんだ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "それで……例の\"切り札\"の出番という訳ですね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ。一筋縄じゃいかない相手だが……まぁ、見てろ" },
  { text: "そして、次だが……俺は机の上に、薬箱とは別の箱を置き、その蓋を開ける。中には黒と赤を基調とした｜禍々しい《まがまがしい》一本の剣、魔剣グレモリーが入っていた。そして、その剣は｜仄《ほの》かに赤く発光しながら、おどろおどろしい声色で俺の声に応える。" },
  { hide: "all" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "起きてるか?グレモリー" },
  { name: "グレモリー", text: "……約束を忘れたか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、まぁ確かに約束したな、お前は争い事が嫌いなんだろ、それは十分理解してる" },
  { name: "グレモリー", text: "ならば話は終わりだな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そう言うなよ。神を殺せば、魔王システムは無くなる。それはお前の悲願でもあるんじゃないのか?" },
  { name: "グレモリー", text: "我は人間に興味など……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "嘘だな。お前は人間が好きだ。人類を救う勇者が魔王に堕ちる、皮肉な物だよな、このシステムは狂ってる。神は相当な悪趣味なんだろう" },
  { text: "グレモリーが押し黙る。俺は構わず言葉を続ける。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ちょっと調べさせて貰った。魔王グレモリーの前の代、魔王オロバスを倒した勇者についてな、その勇者は炎属性の魔術と封印術に長けていたらしい。そして魔王オロバスが討たれた後、消息を絶った" },
  { name: "グレモリー", text: "我の前の代の魔王の事など、知らぬ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセル、魔剣グレモリーの才能を列挙してみろ" },
  { name: "クロセル", text: "剣術6、炎魔術7、魅了5、封印術8だな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だ、そうだが……" },
  { name: "グレモリー", text: "はぁ……貴様らは分からないのか?争いは平和など生まない、新たな争いの火種を生み出すだけだ!" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "だからって見て見ぬ振りをするのか?苦しんでいる人が居るならば救ってやるべきだろ、それがただの延命措置にしかならないとしてもな" },
  { name: "グレモリー", text: "……仮に神を殺して、世界から魔王が消えても、今度は人間同士が争いを起こすのだ!今人類が団結していられるのは、他でもない魔王という共通の敵が居たからに他ならない!" },
  { text: "グレモリーは声を荒げる。冷静沈着を装ってきたグレモリーが感情的に言葉を紡ぐのは、これが初めてかもしれない。" },
  { text: "皆は、俺とグレモリーの会話を見守っていた。グレモリーの言い分は｜尤《もっと》もだ。反論の余地は存在しない。だが、彼女の心には矛盾がある。それが唯一の｜綻《ほころ》びだ。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "疑心暗鬼だな、そんなに人間が信じられないか?" },
  { name: "グレモリー", text: "あぁ、信じられない。勇者だと｜持て囃《はや》されていた私が!英雄が!魔王の血を浴びたからと迫害され、今度は人間の敵として恨まれる?こんな理不尽があってたまるか!" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だがお前は人間を殺さなかった、魔王の破壊衝動を抑えようとした。それはお前が人間を好きだからに他ならない、人間の可能性を信じていたからだ、この世界に悪人は居ないなんて｜無垢《むく》な考えを持つ程にな" },
  { name: "グレモリー", text: "そうだ!だが私は破壊衝動を抑えられなかった、だから自分を封印して、負の連鎖を断ち切ろうとした、それを｜邪魔《じゃま》したのは!" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前のやった事こそ、ただの延命措置だ。魔王システムが機能しなくなったら神は新たにこの世界に悪者を作り出す。神は。エルは愉快な物語が好きなんだ、正義が活躍するには悪が必要だからな" },
  { name: "グレモリー", text: "ならどうすれば!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "だから最初に言っただろ、神を殺せば魔王システムは無くなるし、今後同じような理不尽なルールが作り出される事も無い、人間を信じてるんだろ、ならお前のやるべき事は一つじゃないのか?" },
  { name: "グレモリー", text: "……私が力を貸せば満足か?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ。俺と契約しろ、グレモリー" },
  { text: "俺は魔剣に触れる。後はこいつの意思次第だ。" },
  { fx: "flash" },
  { name: "グレモリー", text: "はぁ……降参だ。我は魔剣グレモリー、契約に従い、貴様の剣となりその生命を守ろう" },
  { text: "最近よく聞く文言だなと思いながら、魔剣が強く発光する。そして、手のひらに｜仄《ほの》かな温もり。微弱だが、繋がりを感じる。契約は成立した。" },
  { name: "クロセル", text: "良いのか?二つの魔剣と契約するなど自殺行為だぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "安心しろ、俺には無尽蔵の魔力があるからな、使い放題だぞ" },
  { name: "グレモリー", text: "それにそもそも、教国では我の力は弱体化するが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "その心配も要らない、俺と契約したからな" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ヤマトさん……貴方なんでもありなんですか?" },
  { text: "アカツキがやれやれとばかりに溜息を吐く。もはや見慣れた光景だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "正確には俺一人の力じゃないんだが……まぁ俺の持つ力には変わりないからな" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "意味分からないんですけど、あとこれも疑問なんですがヤマトさんは一体何人の女性を｜侍《はべ》らせれば気が済むんですか?" },
  { text: "言われて気付いた。グレモリーも女だったな。クロセルにアカツキにシェル公にグレモリーに瀬野、今だけでも五人の女性を｜侍《はべ》らせてる事になる。あ、瀬野は男だった。となると……当然予測できた事態として、クロセルの刺すような強い視線を感じる。" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ぐぬぬ……ご主人、我以外の魔剣と契約するなど……この浮気者!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "不可抗力だ" },
  { name: "クロセル", who: "crocell", text: "完全にご主人の意思だ!我は全部見てたのだからな!?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "別に良いじゃねぇか……俺の相棒はお前一人なんだから" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "口では何とでも言える……どうせグレモリーにも同じ事を言うのだろう?この女ったらしめ" },
  { name: "グレモリー", text: "……我は二番目なのか?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "このタイミングでその質問は悪意しか感じないからやめろ!" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "全く……こうなる事は予想出来ましたけど" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "同感だ、助けを願えるか?アカツキ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "嫌です、自業自得なんですから自分でどうにかしてください" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……え、いやこれ俺のせいなの?" },
  { text: "瀬野は乾いた笑いを浮かべ、アカツキは知らないとばかりにそっぽを向いてしまう。じとじととクロセルに睨まれながら、俺は話題を逸らそうと口を開く。" },
  { name: "瀬野", who: "zeno", text: "あの……そもそもグレモリーさんって人型になれるの?今は剣の姿でお話してるけど……" },
  { text: "瀬野がおずおずと挙手して、そんな疑問を口にする。クロセルやラプラスの例を考えると、いけるとは思うのだが……" },
  { name: "グレモリー", text: "可能だが我は炎属性の魔術しか使えないからな、魔力で生前の姿を再現する事は出来るが｜魔杖《まじょう》クロセルのように自由な姿に化けたりは出来ないぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺はお前がどんな姿だろうと別に気にしないぞ" },
  { name: "グレモリー", text: "そうか、では試しに" },
  { se: "magic" },
  { fx: "flash" },
  { text: "魔剣から光の粒子が舞い上がり、徐々に人間の形に構築される。光が収まった時には、魔剣を片手に携えた長身の女性が立っていた。" },
  { chara: [ { slot: "left", id: "yamato", expr: "surprised" }, { slot: "center", id: "gremory", expr: "normal" } ] },
  { text: "生気を失ったような白い肌に炎のような赤い髪、そして黒色のロングドレス。クロセルが絵に描いた魔性の美少女だとすれば、グレモリーの姿は絵に描いた魔性の｜美女《レディ》と言った所か。" },
  { text: "グレモリーは、感情のない瞳で俺を見つめている。俺も彼女も立ち尽くした姿で。そのまま時間だけが過ぎていく。" },
  { chara: { slot: "right", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人?ご主人?えいっ" },
  { fx: "shake" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……いてっ" },
  { text: "俺はクロセルのビンタで目を覚ます。文字通り、目が醒める。見惚れていた?いや、それだけじゃない。完全に動けなかった。蛇に睨まれた蛙とはこの事だろう。これは……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "魅了の才能か……クロセルは何とも無いのか?" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "ふっ、バレたか。まだ二割も本気を出していないのだがな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "魅了の才能は異性にしか効きにくいのだ。よいか?ご主人、魔剣グレモリーは\"本当に僅かしか力を使っていない\"" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "マジ?俺完全に動けなかったんだけど……ってあ……そうか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そうだ、ご主人の精神汚染耐性のディザビリティだ、今のご主人はどんなに軽い魅了だろうと掛かってしまう、気を付けるのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほどな……グレモリーが敵じゃなくて助かった" },
  { bgm: "daily" },
  { chara: { slot: "rcenter", id: "shellmi", expr: "angry" } },
  { name: "シェル公爵", who: "shellmi", expr: "angry", text: "ダーリンを魅了しようとは良い度胸じゃないか?魔剣グレモリー" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "主の気を惹きたいと思うのは当然の事だろう?" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "ダーリンは私の男だ、勝手に盗らないで貰えるかね?" },
  { text: "今まで黙っていたシェル公も、流石に限界とばかりに口を挟んできた。そして、俺の片腕に抱きつく。やめろ、この先の展開が予想できる。" },
  { chara: { slot: "right", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "シェル公爵!ご主人は我の物だと何度も!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "それも違うって何度も言ってるんだけどな?" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "我は別に構わんぞ、必要とあらばいつでも魅了出来るのだからな" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "才能を使うのはずるいぞ!それに貴様はご主人の事を何も知らない癖に!" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "……一応ずっと旅に付いてきてたのだがな、少なくともシェル公爵とやらよりは長い付き合いだと思うが" },
  { name: "シェル公爵", who: "shellmi", expr: "angry", text: "ほう?言ってくれるではないか、その大切な旅の記憶、消してやっても良いのだぞ?" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "あはは……" },
  { text: "クロセルとシェル公が喧嘩するのは分かるが、グレモリーは確信犯だ。あいつ俺の事とかどうでもよくて、絶対にこの状況を楽しんでるだけ。俺には分かる。多分、そうだ。" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "……そうだ、この男と契約したら隣で寝てもいいと聞いたのだが" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "グレモリー、火種をばら撒くのやめない?" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "そうだな……我は物を燃やすのが好きなのだ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "放火魔だこいつ……魔女だわ……思ってた数倍やべぇ奴だった……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキ、グレモリーの戦力はクロセル何人分ぐらいなんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "クロセルさん0.7人分ぐらいですかね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "少し心許ないな、俺とクロセルは単騎でも大丈夫だから、皆は可能ならグレモリーの支援に回ってやってくれ" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "我が前線を張るのか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "悪いな……このメンバー前衛が居ないんだよ……" },
  { name: "アカツキ", who: "akatsuki", text: "ニコラスさんとエルさんが居なくなってしまったので、魔術師のクロセルさんすら前衛をやる事態になってるんですよね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "キツいなら後ろでも大丈夫だぞ" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "いや、我は剣術も｜嗜《たしな》んでいる、前衛は任された" },
  { text: "俺は頭を抱える。改めて仲間が増えたのは良い事でもあるのだが、これが嬉しい悲鳴という奴か。決戦間近というのに、なんとも締まらない俺達であった。" },
  { fade: "out" },
  { hide: "all" },

  // ===== 追補: ep117_eve (決戦前夜) =====
  { label: "ep117_eve" },
  { bg: "bathhouse_base_night", instant: true },
  { bgm: "heartwarm" },
  { fade: "in" },
  { text: "作戦会議を終えた夜。明日には聖都の上層へ強襲を仕掛ける。最後の夜になるかもしれない一日を、俺達は思い思いに過ごしていた。" },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "right", id: "crocell", expr: "normal" } ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、眠れないのか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、ちょっとな。明日の事を考えてたら、目が冴えちまった" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……勝てると思うか?相手は神だ。今までの誰よりも、格上の存在だぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分からん。だが、やるしかない。ここで止まったら、今まで死んでいった奴らに顔向け出来ねぇ" },
  { text: "クリスタ。クロセル奪還で別れた仲間達。理不尽に奪われた、無数の命。俺達の旅は、いつだって誰かの犠牲の上に成り立っていた。だからこそ、ここで終わらせる。この狂ったシステムを、神ごと。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我はご主人に着いていくだけだ。どんな結末になろうとも、最後の一瞬まで、ご主人の剣として在り続ける" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "……ありがとな、クロセル。お前が居てくれて、本当に良かった" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "なっ……き、急に何を言い出すのだ、ご主人は!" },
  { text: "顔を真っ赤にして慌てるクロセルに、俺は思わず笑ってしまう。あぁ、こいつのこういう所が、たまらなく愛おしい。明日、全部終わらせて、また穏やかな日々に戻ろう。そう、心に誓った。" },
  { chara: { slot: "center", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "お二人とも、まだ起きてたんですね。明日に響きますよ?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキか。お前こそ、寝てないのか" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "……柄にもなく、緊張してるのかもしれません。でも、不思議と怖くはないんです。ヤマトさんと一緒なら、なんとかなる気がして" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そりゃ買い被りだ。だが……まぁ、なんとかしてみせるさ。全員でな" },
  { text: "夜は静かに更けていく。明日、世界に反逆する七人の、最後の安らぎの夜。俺はその時間を、噛み締めるように過ごした。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 4: assault_upper (EP117 終わりへの戦い) =====
  { label: "assault_upper" },
  { bg: "arcadia_upper" },
  { bgm: "suspense" },
  { fade: "in" },
  { comment: "視点: ｜神《エル》側 → ヤマト一行の強襲" },
  { pov: "el_goddess" },
  { text: "聖都アルカディア上層、聖域。中央に位置する透明な椅子に座すのは、エメラルドグリーンの美しい長髪を持った少女。その脇には、聖剣フルティンを振り回しながらくるくると回る黒髪の少女。名も無き神と魔剣ラプラスである。" },
  { chara: [ { slot: "center", id: "el_goddess", expr: "normal" }, { slot: "right", id: "laplace", expr: "laugh" } ] },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "全面戦争とはワクワクしますなぁ!ご主人様?" },
  { name: "神", who: "el_goddess", expr: "normal", text: "……遂にですね。｜猶予《ゆうよ》は?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "2時間後に｜魔杖《まじょう》クロセルの転移魔術で上層に強襲してきますね、戦力はいつもの面子に魔剣グレモリーを加えた感じ" },
  { name: "神", who: "el_goddess", expr: "blank", text: "ここでヤマトを殺す必要があります、そうでなければ" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "無防備なご主人様が殺されてしまいますからな、仮にそうなった場合、修正力がどう働くかまでは分かりませんが" },
  { name: "神", who: "el_goddess", expr: "normal", text: "……そこまで先の事も視えているんですか" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "まぁボクはちょっと\"特別\"なんで、あんま気にしないでくださいな" },
  { text: "ラプラスは神に向かってウインク。神はそれを冷たい瞳で一瞥すると、｜徐《おもむろ》に片手を挙げる。" },
  { chara: { slot: "left", id: "eve_end", expr: "normal" } },
  { name: "神", who: "el_goddess", expr: "normal", text: "イヴ。迎撃は任せます、聖域まで誰一人として近付けない事が理想です" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "分かりました、聖教会が全力を以て神様をお守りします" },
  { name: "神", who: "el_goddess", expr: "normal", text: "えぇ、期待しています" },
  { text: "神の正面に立っていた真っ白な老人、教皇イヴ・エンドは、深く一礼をすると、そのまま聖域を後にする。" },
  { hide: "left" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "ボクも行くべきです?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "もちろん、ただ……未来が不確定な以上、投入するのは時間ギリギリにしますが" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "そうですね、因みに現時点での未来、知りたいですか?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "言いなさい" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "分かりました、ボクらの未来は――" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { bgm: "battle" },
  { pov: null },
  { text: "――2時間後。俺達はクロセルの魔術で上層に侵入。聖域を目指して進んでいた。予想通りと言った所か、俺達の侵入は予期されていたらしく、警備は厳重。" },
  { fx: "shake" },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "lcenter", id: "akatsuki", expr: "serious" }, { slot: "rcenter", id: "shellmi", expr: "smug" }, { slot: "right", id: "crocell", expr: "normal" } ] },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "お勤めご苦労。事が終わるまでぐっすり眠っていたまえ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……強いな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "身体強化魔術があるのは分かるんですが……それでも予想以上ですね" },
  { text: "次々と行く手を阻む福音使徒を、クロセルとグレモリー、あとシェル公が｜薙《な》ぎ倒していく。シェル公は戦闘系の才能を持っていないと言っていたが、知識として持っている戦闘技術は中々の物で、素手で敵を無力化すると額を軽くノックして意識を奪っていく。" },
  { text: "もしかしたら、身体強化込みなら俺より強いかもしれない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これで第六波が終わりか" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "中々進めませんね、物量に物を言わす作戦、案外厳しいかもしれません" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "こちらは少数だからな、戦力自体はイーブンかそれ以上でも、手数が足りない" },
  { text: "道は一本道だが、前と後ろの両方から次々と増援が現れるせいで中々前に進めない。だが、これも想定内だ。城を｜籠絡《ろうらく》する以上、長期戦になるのは必定。その隙に大将を逃される可能性を考慮して、クロセルに結界魔術を貼って貰っている。" },
  { text: "無論、相手には勇者や教皇が居る。結界を破壊する事も出来るが、仮に破壊された場合、神が上層を離れた事が分かる為、追撃に支障は出ない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだ、アカツキ、壁抜け魔術でショートカット出来ないか?" },
  { chara: { slot: "center", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "出来ますけど、聖域の正確な場所が分からないので……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "それなら俺が分かる。シェル公、俺の記憶を読み取ってアカツキに複写、意図的に失敗しろ" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "ほう?失敗させるのか?まぁいい、任せてくれダーリン、お安い御用さ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そんな使い方出来るんですね……" },
  { text: "シェル公が胸に手を当てて自信満々に宣言すると、俺の頭に手を伸ばす。届いてない。背伸びする。届かない。ジャンプ。届かない。数秒の沈黙。そしてアカツキの手刀が俺の頭に炸裂した。" },
  { fx: "shake" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "いってぇ!" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "意地悪してないで早くしてください" },
  { text: "俺は渋々、地面に膝をついて頭を下げる。シェル公が俺の頭に触れ、記憶を読み取る。特に何か感じる訳ではない。が、記憶の抽出は成功したようで、シェル公は今度はアカツキの元に近付き、その頭に触れる。" },
  { chara: { slot: "center", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "っ……かはっ!" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "大丈夫か?アカツキ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "記憶の上書きって……結構きついんですね……吐きそう……" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "すまない、ダーリン。失敗しようとしたのだがな……成功してしまった……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よくやった" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "これは喜んでいいのかね?" },
  { text: "アカツキが息を切らしながら暫く｜喘《あえ》ぐ。その間に、前後から第七波が。クロセルとグレモリーが対処する。そして、呼吸が落ち着いた頃には、全てが片付いていた。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "位置、分かりました。ショートカットしましょう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキよ、気付いてるか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、魔術的な障壁が｜蜘蛛《くも》の巣の如く張り巡らされてるので、最短ルートは使えません、が……福音使徒との交戦を避けて近道する事は出来ますね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、やれ" },
  { text: "アカツキが近くの壁に手を｜翳《かざ》す。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "｜魔術回路構築《クリエイト》……詠唱……\nル・トゥーム・アルガス・ティル\n空間魔術……｜接続《コネクション》" },
  { se: "magic" },
  { fx: "flash" },
  { text: "壁がぐにゃりと歪み、穴が生まれる。その先には別の廊下らしき風景が見て取れる。クロセルが先行して穴を通り、辺りを軽く見渡すと、頷く。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "福音使徒は居ないな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、この方法ならだいぶ早く聖域に近付けそうだな" },
  { text: "俺達は空間の穴を潜る。辺りを見渡し、記憶から位置を参照すると、確かに聖域に近付いている。これを数度繰り返せば聖域に辿り着けるだろう。そんな事を考えているうちに、アカツキが再び次の空間の穴を生み出す。" },
  { text: "二つ目の穴を抜けると、広間のような場所に出た。相変わらず福音使徒の姿はない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……待てよ?" },
  { text: "俺はふと呟く。違和感だ。これだけ厳重な警備体制でありながら、福音使徒の姿が無い事。そして張り巡らされている魔術的な障壁に穴がある事。教皇の奴がそんなミスをするだろうか。まるで、このルートが意図的に用意されたかのような……" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "繋がりました、クロセルさん、先行してください" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、大丈夫だ、福音使徒の姿は無い" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "では進みましょうか" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "っ!?待て!その先に進むな!" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "俺は気付いた。慌てて穴を通ろうとする仲間を呼び止めるが、もう遅い。バチン、と何かが弾けるような音と共に、穴が消失する。魔術的な障壁が張られ、空間を繋ぐ穴が破壊された。\n――そう、これは罠だ。" },
  { hide: "all" },
  { chara: [ { slot: "left", id: "yamato", expr: "surprised" }, { slot: "center", id: "akatsuki", expr: "surprised" } ] },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "私は閉じてません、って事は……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "アカツキ、急いでもう一度、今と同じ場所に繋いでみてくれ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "分かりました" },
  { text: "アカツキが詠唱する。そして、空間がぐにゃりと歪んだかと思うと、バチンと弾ける音を立てて、空間の歪みは消失する。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "魔術的な障壁ですね……このタイミングでって事は……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "チッ……分断されたな、こっちは" },
  { text: "こっち側に残ったのは俺、アカツキ、グレモリーの三人。先に進んだのはクロセル、瀬野、シェル公の三人という事になる。クロセルとグレモリーが分かれたのは幸いだ。向こうはクロセルが居るから大丈夫だろう。問題はこっちだ。" },
  { text: "相手にとって、戦力が分断された今は最大の好機だ。確実に仕掛けてくる。誰が来る?雑兵の福音使徒ではない。このタイミングで出し惜しんでは来ないはずだ。" },
  { fx: "shake" },
  { chara: { slot: "center", id: "gremory", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "っ!グレモリー!後ろだ" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "分かっている" },
  { text: "グレモリーは、半歩下がりながら身を捻る。風を切る音。彼女の胸元を、不可視の刃が｜掠《かす》めていった。この攻撃には見覚えがある。だが認めたくない。現実から逃げたくなる気持ちを押し殺して、俺は襲撃者の存在を確認する。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ティア……と!お前か!" },
  { text: "｜咄嗟《とっさ》に腰の鉄棒を抜く。そして、それを顔の前で構えた瞬間、大きな金属音が響き渡る。" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "どうも～?悪魔で～す!" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "てめぇ……" },
  { text: "力任せに鉄棒で剣を振り払うと、魔剣ラプラスは空中で後方に回転しながら、ゆっくりと地面に降り立つ。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "いやーボクの担当がヤマト様の方で良かった!こっちの方が面白い物が見れそうですしね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その言い方だとクロセルの方は勇者と教皇か" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "ま、隠す事でも無いですし言ってしまえばその通りです。上手いこと戦力が偏ってくれればこちとら都合が良かったんですが、見事にクロセルとグレモリーが分断されましたね、やはりヤマト様は運が良い!" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……グレモリー、いけるか?" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "我は魔剣の相手か?" },
  { name: "ヤマト", who: "yamato", expr: "serious" , text: "あぁ、ティアの方は俺とアカツキでなんとかする" },
  { text: "そう言い放つと、俺は地面を蹴って駆ける。あの精度で魔術を放ったのならば、そう遠くはない筈だ。居た。50m程度先に、小さな人影。手を前に向けて、詠唱している。方向は……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "アカツキ!" },
  { fx: "shake" },
  { text: "俺の声とほぼ同時にアカツキが飛び退く。そして不可視の刃が音を立てて｜掠《かす》めていく。アカツキとは思えない中々に機敏な動きだ、逆に言えばあれほどの動きが出来なければ回避は難しい。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "身体強化魔術が効いてる今は大丈夫です、なるべく早く決着を付けてください" },
  { text: "そう、今アカツキがティアの魔術を回避出来たのはクロセルの身体強化魔術が効いてるからだ。さっき俺がラプラスの一撃を受け止めれたのも同じ。逆に言えば、この魔術の効果時間が切れれば、俺達の勝機は一気に薄れる。故に、短期決戦を目指す。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ティア……" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 5: tia_bomb (EP118 究極の選択) ◆B09 =====
  { label: "tia_bomb" },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "right", id: "tia", expr: "sad" } ] },
  { text: "プランはシンプル。後ろに回り込み組み伏せた後に手錠で拘束し｜封能薬《ふうのうやく》を飲ませる。これでティアは無力化出来る。だが、現実はそう簡単には行かない。" },
  { text: "ここはただっ広い広間だ。魔術師は閉所では力を発揮できないが、広い場所では無類の強さを発揮する。罠に嵌ってここに誘い込まれた時点で、俺達は半分負けているのだ。" },
  { name: "ティア", who: "tia", expr: "sad", text: "ヤマト……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "悪いなティア、出来れば大人しくしててくれ" },
  { name: "ティア", who: "tia", expr: "sad", text: "そうしたいけど……御告げが……" },
  { text: "ティアの表情は暗い。戦う事が彼女の本意ではない事は目に見えて明らかだ。だが、御告げの強制力には抗えない。今の彼女は神の｜傀儡《かいらい》なのだ。" },
  { name: "ティア", who: "tia", expr: "normal", text: "｜魔術回路構築《クリエイト》……詠唱……\nロ・スォーム・エリアライズ・ティロ\n風魔術……｜風神覇気《インペリアルオーラ》……｜連続詠唱《コネクト》……\nレ・スォーム・ヘイザミリル・ティル\n風魔術……｜突風暴流《ランストルネード》" },
  { text: "淡々と紡がれる連続詠唱。彼女の得意とする風属性魔術だ。ティアの身体が緑色の光を纏う。恐らくは身体強化魔術。そしてもう一つは……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "っ!狙いは俺か!" },
  { fx: "shake" },
  { text: "ティアの手が俺に向けられると同時に、その掌から白い渦のような物が放たれる。竜巻を横に倒したような、空気のドリルと言った所か。俺は地面を蹴って斜めに進路を変更する。あの魔術が直線的な攻撃ならば、回避できる……筈だった。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なっ!?" },
  { text: "足が｜縺《もつ》れる。理由は単純、強い風の力で吸い寄せられたからだ。文字通り竜巻の如く周囲の物を吸引し、粉々に破壊する。それが彼女の放った魔術だ。全力で踏ん張り、攻撃から逃れようとするが、あまりにも強すぎる風の力に、俺は空気の渦に接触してしまう。" },
  { fx: "red" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ぐっ……あああああああ!?" },
  { text: "渦に巻き込まれた脇腹に激痛が走る。意識を持っていかれそうになるが、ここで足を踏み外せば全身木っ端微塵だ。" },
  { text: "悠久にも等しい耐久の末、風の渦は消え失せる。同時に、脇腹からどぷっ……という嫌な音を立てて大量の血液が流れ出す。確認すると、見事に風の渦に巻き込まれた部分だけが｜抉《えぐ》れていた。激痛に倒れ込みたくなる気持ちを抑え、俺はティアを見据える。" },
  { fx: "clear-red" },
  { text: "ティアの魔術は強力だが、反面、詠唱を必要とする為に連射は効かない。追撃が来る前に、決着を付ける。俺は傷が開く事も構わず、再び走り出した。あと少しで手が届く距離まで迫り、手を伸ばすが、それは宙を切る。ティアは地面を蹴って飛び退き、再び詠唱を開始する。" },
  { name: "アカツキ", text: "｜亜空切断《ディメンションカッター》!" },
  { name: "ティア", who: "tia", expr: "sad", text: "ごめんなさい……" },
  { fx: "flash" },
  { text: "アカツキの詠唱と同時にティアが身を翻す。身体強化魔術の賜物で、その動きは魔術師とは思えない程に機敏だ。空間断裂による攻撃はいとも簡単に避けられる。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "狙って撃つだけじゃ当たらねぇぞアカツキ" },
  { name: "アカツキ", text: "分かってます!そもそも空間魔術は戦闘用の魔術じゃないんですから……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なら攻撃はいい、俺を支援しろ" },
  { name: "アカツキ", text: "どうやって……?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ティアの攻撃魔術を空間ごと移動できないか?この距離で撃たれると俺じゃ回避出来ないんだ" },
  { name: "アカツキ", text: "なるほど……出来ます。任せてください" },
  { text: "このやり取りはティア、そしてそれを通して神に聞かれている。つまり次にさっきの吸引攻撃を放ってくる確率は低い。効果が無いと分かっている攻撃をする意味はないからだ。" },
  { text: "これは所詮フェイクだ。実際は、ティアの攻撃魔術が発生してからアカツキが詠唱を始めても時間差がある為、間に合わない。" },
  { text: "アカツキもそれは理解しているはず。それでも\"出来る\"と言ったのは、俺の意図を汲んでくれたのだろう。" },
  { text: "分析の才能のお陰か、或いは単純に信頼関係の問題か、どちらにせよ上手くいって助かった。こうなると、ティアの使える魔術は限られてくる。即効性があり速度が高く回避しにくい攻撃魔術。そう多くはないはずだ。" },
  { name: "ティア", who: "tia", expr: "sad", text: "｜魔術回路構築《クリエイト》……詠唱……\nロ・スォーム・リクシアリアル・ティル\n風魔術……｜鎌鼬《エアスラッシュ》・｜雨《マシンガン》" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ちょっと待て、｜雨《マシンガン》って事は……" },
  { text: "クロセルの得意魔術である水の弾丸を雨のように降らす攻撃。それとよく似た詠唱。聞き覚えのある詠唱。そこから推測される事実は、あの不可視の刃が雨のように放たれるという意味であり……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嘘だ……ろ……!?うおおおおおおおお!?" },
  { fx: "shake" },
  { text: "攻撃は見えない。本能のままに風の刃を避ける。傍から見たら、何も無い所で死に物狂いに踊り狂ってるように見えるだろうか。ヒュンヒュンと風を切る嫌な音が耳を叩く。" },
  { text: "｜鎌鼬《かまいたち》の余波として発生した風が身体に冷たい息を吹きかける。幸い、狙いは甘い。いつもの｜鎌鼬《かまいたち》が狙撃なら、こちらは乱射と言った所。それでも攻撃の物量はえげつない。全部避けるのは恐らく……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "っ……ってぇ!?" },
  { text: "身体の末端。手足に深い切り傷が生まれていく。これは見えないナイフを無数に投擲されているのと等しい。というか、これをナイフと形容して良い物か?肉どころか骨を断つんじゃないかと思える鋭利さだ。襲いかかる激痛に対し、八つ当たりのように叫び散らしながら、俺は刃の雨を凌ぎ切る。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "はぁ……はぁ……まだだ、甘いんだよエル!俺を殺すならもっと殺傷性の高い攻撃を撃つんだなぁ!?" },
  { text: "指先からだらだらと血液が滴り落ちる。気が付けば足元には血溜まり、これ以上の被弾は流石にまずいか。" },
  { text: "出し惜しみしていては目的は果たせない。だが、経験上、才能の解放を使えるのは三回までだ。エルとの戦いに備えて一回分は残しておく必要がある。そして超再生薬を使うのにも一回必要だ。" },
  { text: "となると、この戦いで使えるのは一回のみ。考えろ、一つだけでティアに勝つことの出来る才能を。" },
  { name: "ティア", who: "tia", expr: "normal", text: "｜魔術回路構築《クリエイト》……詠唱――" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "これだ。これならいける……｜解除《アンロック》!" },
  { text: "俺は目を閉じると、身体の奥深くに眠っている才能にスイッチを入れる。スイッチを入れると言っても、ボタン一つ押すだけの簡単な話じゃない。俺の身体に宿る魔王ハーゲンティの意思、才能指数10による強引な力によっての入力だ。" },
  { text: "その代償は、一定時間後にディザビリティとして残る。俺が解放した才能、それは――" },
  { se: "chime" },
  { fx: "flash" },
  { text: "\"才能『対魔力10』を強制解放しました\nエラー……才能データが破損しました\"" },
  { name: "ティア", who: "tia", expr: "normal", text: "風魔術……｜鎌鼬《エアスラッシュ》・｜雨《マシンガン》" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くっ……" },
  { text: "俺は両腕を顔の前でクロスさせるようにして、再び降り注ぐ刃の雨を防ぐ。当然、避けていないのだから風の刃は俺の全身に命中する。が……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……痛くない、これが勇者の気分か" },
  { name: "ティア", who: "tia", expr: "surprised", text: "ヤマト!?どうして……" },
  { text: "本能的にガードしてしまったが、本来はそれすら必要ない。対魔力の才能、それはあらゆる魔術的な干渉を無効化する才能だ。ティアが驚いたような顔で俺を見る。そう言えばティアは俺のこの力の事を知らなかったか。" },
  { name: "アカツキ", text: "ヤマトさん……\"使った\"んですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "やむを得なかった" },
  { name: "アカツキ", text: "分かってます、それより急ぎましょう" },
  { name: "ヤマト", who: "yamato", text: "あぁ、そうだな" },
  { text: "俺は地面を駆ける。先程より速度が落ちている。恐らくクロセルの強化魔術も対魔力の才能で弾いてしまったのだろう。だがそれは些細な問題だ。俺自身の身体能力はクロセルや勇者との特訓の甲斐もあって人並み外れている。身体能力を使ったティアと互角か、或いは僅かに上回るはずだ。" },
  { text: "ティアは魔術以外の攻撃手段を持たない。つまり対魔力のある俺に対して、攻撃を加える手段が無いのだ。この勝負、俺の勝ちだ。" },
  { text: "ティアは攻撃の手を止め、俺に背を向けて逃げ出す。流石に効かないと分かった上で魔術を撃ち込んでくることはないか。逃げるティアの手を掴み、そのまま足払いで体勢を崩し、優しく押し倒す。じたばたと抵抗して、俺から必死で逃げようとする。本人の意思では無いといえ、少しショックだ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "……捕まえた。そう言えば最初にお前と会った時も、こうやって追いかけっこしてたな" },
  { text: "ふと、そんな思い出を懐かしみながら、俺はティアの両手に手錠を嵌める。そして、｜封能薬《ふうのうやく》の瓶の栓を口で開けると、それをティアの口元に持っていき、飲ませる。" },
  { name: "ティア", who: "tia", expr: "surprised", text: "んっ……んんっ!" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "大人しくしててくれ、毒じゃない" },
  { name: "ティア", who: "tia", expr: "surprised", text: "ヤマト!離れて!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "言動まで神に支配されてるのか、可哀想に……" },
  { name: "ティア", who: "tia", expr: "sad", text: "違う!早くわたしから離れて!じゃないと……" },
  { text: "ティアは無力化した。ラプラスの｜邪魔《じゃま》が入る様子もない。それなのに、ティアは何故か焦った様子で俺に離れるように言う。何か理由があるのだろうが……分からない。取り敢えず従っておこう。" },
  { chara: { slot: "center", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "っ!ヤマトさん!ティア様から離れてください!" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おいおい、アカツキまで何を言い出すんだよ" },
  { text: "俺はティアの上から離れると、そのままゆっくりと後ずさりする。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "あの距離だと間に合わない……｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》!" },
  { fx: "flash" },
  { fx: "shake" },
  { se: "explosion" },
  { text: "その瞬間。俺の目の前は真っ白になった。" },
  { fade: "white" },
  { bgm: null },
  { wait: 1000 },
  { hide: "all" },
  { fade: "in" },
  { bgm: "tension" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ごほっ……俺は……今何が……" },
  { text: "一瞬意識を失っていた。最後に覚えているのは、目の前が真っ白になって、鼓膜を破るような爆音が響いた事。辺りが見えない。煙?ということは何かが爆発したのか?" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "アカツキ!どうなってる?ティアがやったのか……?" },
  { text: "声を張り上げるが、返事はない。俺の耳が麻痺しているのか、或いは。俺は煙を掻き分けて前に進む。僅かに感じる嫌な予感が胸をチクチクと苛む。そして、俺はその光景を目の当たりにする。" },
  { fx: "red" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なっ……嘘……だろ?" },
  { text: "巨大な血溜まり。その中央にはティアだった何かが転がっていた。片腕が吹き飛び、火傷で顔すら識別できない。身体の大部分が炭化している。" },
  { text: "そこから、俺は一つの事実を理解する。ティアは自爆した。いや、させられた。エルの手によって。頭に血が上る感覚を覚えつつも、冷静さを欠くことなく思考を回す。ティアが自爆した、俺の目の前で。" },
  { text: "なら何故俺は無事なんだ?そんな疑問が浮かぶ。そして、その理由は直ぐに分かった。煙が晴れていく。それは、俺の足元に転がっていた。" },
  { fx: "clear-red" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "アカツキ……?" },
  { chara: [ { slot: "left", id: "yamato", expr: "surprised" }, { slot: "center", id: "akatsuki", expr: "smile" } ] },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "無事……ですか?ヤマトさん" },
  { text: "俺の足元には重症のアカツキが倒れていた。アカツキはティアと距離があったはず、爆発に巻き込まれる筈がない。いや、詠唱を省略して放った最後の魔術。あれはもしかして……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "俺の位置と空間を入れ替えたのか!?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ギリギリセーフでしたね……空間の入れ替えは空間魔術の初歩ですから……私でも略式詠唱に成功できたというわけ……です……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "セーフじゃねぇよ!なんでそんな事を!" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "あの一撃でヤマトさんが即死、そうでなくとも意識を失ったら、全てが終わりですから……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "っ……待ってろ、今治してやる!" },
  { text: "ティアもそうだが、アカツキの怪我も酷い。全身にガラスのような破片が刺さり大量の出血と重度の火傷、致命傷だ。" },
  { name: "ティア", who: "tia", expr: "sad", text: "……ヤマト" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ティア!?大丈夫なのか?" },
  { name: "ティア", who: "tia", expr: "sad", text: "大丈夫なわけ……無いじゃない……離れてって言った……のに……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "悪かった……まさかエルがあれほど非道な手段を取ってくるとは思わなかったんだ" },
  { text: "俺は懐から一本の瓶を取り出す。中には血液のような赤色の液体。｜超再生薬《エリクサー》と称される最高クラスの回復薬だ。これがあれば二人を治せる。" },
  { text: "……二人を?何かがおかしい。落ち着け。俺の手にはどんな傷でも治せる薬が一本ある。" },
  { text: "……一本しか、無いのだ。" },
  { bgm: "sad" },
  { fx: "shake" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "嘘だろ?嘘だ嘘だ嘘だ!どうすればいい……!?薬は一本しかない……ティアかアカツキ、どちらかしか救えない……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……ティア様に使って下さい、私は足手まといです、ここまでヤマトさんと一緒に来れたのが奇跡なぐらい、私は凡庸な人間ですから……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "違う!アカツキが居なければ俺達はここまで来れなかった、アカツキが居なければ、俺はあの森で野垂れ死んでたんだよ!" },
  { text: "俺は地面を殴りつける。こんな残酷な選択があるだろうか。俺には出来ない。俺には選べない。こうしてる間にも、ティアとアカツキの命の灯は消えかかっている。早く決断しなければ。" },
  { name: "ティア", who: "tia", expr: "normal", text: "ヤマト、わたしには祝福がある……から……大丈夫" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そうか!ティアには祝福があったな、完全に忘れてた" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ティア様……" },
  { text: "魔王戦で祝福は勇者ニコラスからティアに移った。祝福がある限り、ティアは死なない――筈だ。エルの手で起きた厄災をエルに救われる事になるとは皮肉な物だ。それでも、目の前で冷たくなっていく少女を前に、手が震える。" },
  { text: "頭では分かっている。薬はアカツキに使うのが正しい。ティアには祝福がある、だから死なない。理屈はそうだ。だが、その\"筈だ\"という一語と、腕の中で急速に冷えていく小さな身体の重みが、どうしても噛み合ってくれない。" },
  { text: "どちらに使う?この一本を。" },
  { comment: "◆B09 原作公式分岐: エリクサーの選択" },
  { choice: [
    { label: "超再生薬をアカツキに使う――ティアの「祝福」に賭ける", jump: "b09_canon" },
    { label: "超再生薬をティアに使う", jump: "b09_tia", kind: "if" },
  ]},

  // ----- B09 正史側: アカツキに使う -----
  { label: "b09_canon" },
  { text: "祝福がある限り、ティアは死なない。エルの手で起きた厄災をエルに救われる事になるとは皮肉な物だ。決断した。俺はアカツキの身体の上で瓶を握り潰す。", tid: "ch07__b09_canon__01" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "よし、アカツキ、これを使うぞ", tid: "ch07__b09_canon__02" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……分かり、ました", tid: "ch07__b09_canon__03" },
  { se: "chime" },
  { fx: "flash" },
  { text: "\"才能『魔法薬10』を強制解放しました\nエラー……才能データが破損しました\"", tid: "ch07__b09_canon__04" },
  { text: "先程と同じように、身体の奥底のロックを外す。これで二回。仮に二回分の反動に耐えれたとしても、その次が最後だ。", tid: "ch07__b09_canon__05" },
  { name: "ヤマト", who: "yamato", text: "｜魔術回路通力《ライン》……詠唱……\nロ・ラルム・デルタイト・ティロ\n光魔法薬……｜超再生《リジェネレイト》", tid: "ch07__b09_canon__06" },
  { fx: "flash" },
  { text: "瞬間、液体が粒子状に変化しアカツキの全身を包んだかと思えば、時間が逆行するかのようにアカツキの傷が塞がっていく。異物は自動的に取り除かれ、いつもの姿に戻る。……燃え尽きた服までは元に戻らないのが欠点か。", tid: "ch07__b09_canon__07" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……意外と大きいな、着痩せするタイプなのか", tid: "ch07__b09_canon__08" },
  { name: "アカツキ", who: "akatsuki", expr: "blush", text: "こんな状況で何を言い出すんですか!", tid: "ch07__b09_canon__09" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "冗談だ、これ着てろ", tid: "ch07__b09_canon__10" },
  { text: "俺は上着を脱ぐと、それをアカツキに放り投げる。大きさ的に動きずらいだろうが、局部を隠す分には十分だろう。無論、紳士故に視線はそらしておく。クロセルが居なくて良かった。", tid: "ch07__b09_canon__11" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "グレモリーとラプラスの方は……まだ戦闘中か。悪いが多分俺は一度戦闘不能になる", tid: "ch07__b09_canon__12" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "分かってます、私はヤマトさんを守りつつ向こうの援護をするので", tid: "ch07__b09_canon__13" },
  { text: "\"致命的なエラーが発生した為……破損箇所のある才能を破壊します『対魔力0』\"\n\"致命的なエラーが発生した為……破損箇所のある才能を破壊します『魔法薬0』\"", tid: "ch07__b09_canon__14" },
  { fx: "shake" },
  { text: "アカツキが立ち上がると同時に、俺は地面に尻餅をつく。理由は単純、一瞬にして意識が無くなったからだ。短時間に二回の才能の解放をした代償は大きい。あまりのダメージに一瞬で意識を奪われ、苦痛を伴わないのが幸いか。", tid: "ch07__b09_canon__15" },
  { text: "思考が回らない。視界は暗転し、音は遠のく。そして俺は、静かに首を垂れ、意識を失った。", tid: "ch07__b09_canon__16" },
  { fade: "out" },
  { hide: "all" },
  { jump: "gremory_vs_laplace" },

  // ===== B09分岐ルート: ティアを選んだ世界線 → BAD END =====
  { label: "b09_tia" },
  { text: "考えるより先に、身体が動いていた。", tid: "ch07__b09_tia__01" },
  { text: "目の前で冷たくなっていく少女。出会った日、王城の中庭を一日中駆け回った、あの｜屈託《くったく》のない笑顔。それを失う想像が、俺には出来なかった。", tid: "ch07__b09_tia__02" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "すまない、アカツキ……ティアに使う", tid: "ch07__b09_tia__03" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "……はい。それで、良いと思いますよ……それが、ヤマトさんの優しさです……から", tid: "ch07__b09_tia__04" },
  { fx: "flash" },
  { text: "\"才能『魔法薬10』を強制解放しました\nエラー……才能データが破損しました\"", tid: "ch07__b09_tia__05" },
  { name: "ヤマト", who: "yamato", text: "｜魔術回路通力《ライン》……詠唱……\nロ・ラルム・デルタイト・ティロ\n光魔法薬……｜超再生《リジェネレイト》", tid: "ch07__b09_tia__06" },
  { fx: "flash" },
  { text: "赤い液体が粒子となってティアの全身を包む。炭化した皮膚が剥がれ落ち、その下から新しい肌が生まれていく。失われた腕が、時間を巻き戻すように再生していく。", tid: "ch07__b09_tia__07" },
  { chara: { slot: "right", id: "tia", expr: "surprised" } },
  { name: "ティア", who: "tia", text: "……ヤマ……ト?わたし……生きてる……の?", tid: "ch07__b09_tia__08" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、生きてる。もう大丈夫だ", tid: "ch07__b09_tia__09" },
  { text: "ティアの目から大粒の涙が零れる。良かった。間に合った。俺は確かに、一つの命を救ったんだ。", tid: "ch07__b09_tia__10" },
  { text: "――なら、この足元の冷たさは、なんだ。", tid: "ch07__b09_tia__11" },
  { chara: { slot: "center", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", text: "良かった……ですね。ティア様が笑ってる未来は……きっと、良い未来です……", tid: "ch07__b09_tia__12" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おい、アカツキ?喋るな、今クロセルを呼ぶ、回復魔術なら……", tid: "ch07__b09_tia__13" },
  { name: "アカツキ", who: "akatsuki", text: "間に合わない事くらい……分析の才能が無くても……分かりますよ……", tid: "ch07__b09_tia__14" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん……私、貴方に会えて……この世界も、悪くないって……思えたんです……", tid: "ch07__b09_tia__15" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "やめろ、遺言みたいな事を言うんじゃねぇ!お前はまだ……お前の復讐は、まだ終わってないだろ!", tid: "ch07__b09_tia__16" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そう……ですね。続きは……お任せ、します……正義のヒーロー……なんてね……らしくない、ですか……", tid: "ch07__b09_tia__17" },
  { text: "それが、最後の言葉だった。", tid: "ch07__b09_tia__18" },
  { fx: "red" },
  { text: "ミナモアカツキ。水若 暁(みなも あかつき)。元・異世界人。俺と同じ日本から来た転生者。森で攫われた俺を助けに来てくれた、最初の仲間。", tid: "ch07__b09_tia__19" },
  { se: "heartbeat" },
  { text: "――い き を し て い な い。", tid: "ch07__b09_tia__20" },
  { fx: "shake" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あ……ああ……あああああああああ!!!", tid: "ch07__b09_tia__21" },
  { name: "ティア", who: "tia", expr: "sad", text: "アカツキ……?ねぇ、起きてよ……わたしのせいだ……わたしが……わたしが爆発なんかしたから……!", tid: "ch07__b09_tia__22" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "違う……お前のせいじゃない。エルだ。全部、あいつがやった事だ……", tid: "ch07__b09_tia__23" },
  { text: "俺はアカツキの瞼をそっと閉じさせる。涙は出なかった。代わりに、腹の底から冷たい何かがせり上がってくる。", tid: "ch07__b09_tia__24" },
  { fx: "clear-red" },
  { bgm: "dark" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "エル……お前だけは、絶対に許さない", tid: "ch07__b09_tia__25" },
  { fade: "out" },
  { hide: "all" },
  { label: "b09_laplace_alive" },
  { bg: "arcadia_upper", instant: true },
  { fade: "in" },
  { comment: "B09分岐: アカツキ不在のラプラス戦" },
  { text: "その頃、広間の反対側ではグレモリーが魔剣ラプラスと斬り結んでいた。", tid: "ch07__b09_laplace_alive__01" },
  { chara: [ { slot: "left", id: "gremory", expr: "serious" }, { slot: "right", id: "laplace", expr: "laugh" } ] },
  { name: "グレモリー", who: "gremory", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》\n炎魔術……｜炎槍《フレイムランス》・｜射《ショット》", tid: "ch07__b09_laplace_alive__02" },
  { fx: "flash" },
  { text: "宙に跳ね上がったラプラスの胸を、炎の槍が深々と貫いた――かに見えた。", tid: "ch07__b09_laplace_alive__03" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "なんてね?", tid: "ch07__b09_laplace_alive__04" },
  { name: "グレモリー", who: "gremory", expr: "angry", text: "｜偽物《フェイク》か!?本体は!?", tid: "ch07__b09_laplace_alive__05" },
  { text: "両腕両足に、地面から生えた紫色の触手が巻き付く。天井から降ってきたラプラスが、聖剣フルティンを構えて猪突してくる。", tid: "ch07__b09_laplace_alive__06" },
  { text: "本来の歴史なら――此処でアカツキが駆け付け、拘束を破壊していた筈だった。だがアカツキはもう居ない。誰も、来ない。", tid: "ch07__b09_laplace_alive__07" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "死ね!グレモリー!", tid: "ch07__b09_laplace_alive__08" },
  { se: "slash" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "聖剣がグレモリーの首を落とし、返す刃が魔剣本体を地面に縫い付ける。", tid: "ch07__b09_laplace_alive__09" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "あれぇ?随分あっさり終わっちゃいましたね。……あはっ、そうか、そういう事ですか", tid: "ch07__b09_laplace_alive__10" },
  { text: "ラプラスの瞳がチカチカと青く点滅し、やがて青い光のまま固定される。", tid: "ch07__b09_laplace_alive__11" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "未来が確定した。あーあ……ヤマト様、選んじゃいましたねぇ、\"そっち\"を", tid: "ch07__b09_laplace_alive__12" },
  { fade: "out" },
  { hide: "all" },
  { label: "b09_last_stand" },
  { fade: "in" },
  { text: "俺はティアを連れてクロセル達と合流した。だが、状況は最悪だった。", tid: "ch07__b09_last_stand__01" },
  { chara: [ { slot: "left", id: "yamato", expr: "angry" }, { slot: "center", id: "crocell", expr: "sad", ghost: true }, { slot: "right", id: "zeno", expr: "scared" } ] },
  { text: "教皇との戦いは、辛うじて凌ぎ切った。クロセルは『代行者9』の攻撃反射に一度は嵌められたものの、二度同じ手は食わない。賢明な彼女は反射技を見切ると詠唱を切り替え、瀬野の時止めの一撃と合わせて教皇を討ち取った。", tid: "ch07__b09_last_stand__02" },
  { text: "だが、深手は深手だ。クロセルは半透明のまま辛うじて再構築された身体で立っている。そして、グレモリーは戻らなかった。", tid: "ch07__b09_last_stand__03" },
  { name: "クロセル", who: "crocell", text: "ご主人……アカツキは……", tid: "ch07__b09_last_stand__04" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……すまない。俺が、選んだんだ", tid: "ch07__b09_last_stand__05" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……そうか。誰もご主人を責めはしない。責めて良いはずがない", tid: "ch07__b09_last_stand__06" },
  { name: "瀬野", who: "zeno", text: "ヤマト……それでも、行くんだよね", tid: "ch07__b09_last_stand__07" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あぁ。ここで止まったら、アカツキに顔向け出来ねぇ", tid: "ch07__b09_last_stand__08" },
  { text: "空間魔術の使い手を失った俺達は、一本道を正面から進むしかなかった。福音使徒の波状攻撃に消耗し、聖域の扉に辿り着いた時には、全員が満身創痍だった。", tid: "ch07__b09_last_stand__09" },
  { fade: "out" },
  { bg: "arcadia_upper", instant: true },
  { fade: "in" },
  { hide: "all" },
  { text: "透明な建材で出来た広い空間。その中央の玉座に、彼女は居た。", tid: "ch07__b09_last_stand__10" },
  { chara: { slot: "center", id: "el_goddess", expr: "normal" } },
  { name: "神", who: "el_goddess", text: "来ましたね、ヤマト", tid: "ch07__b09_last_stand__11" },
  { chara: { slot: "left", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", text: "エル……!よくも、ティアを、アカツキを……!", tid: "ch07__b09_last_stand__12" },
  { name: "神", who: "el_goddess", expr: "blank", text: "おかしいですね。ラプラスの視た未来では、貴方はアカツキを選ぶ筈でした。確定していた筈の未来が、揺らいでいる", tid: "ch07__b09_last_stand__13" },
  { name: "神", who: "el_goddess", expr: "normal", text: "……あぁ、そういう事ですか。これは\"確定した座標\"から外れた世界線。本来の歴史なら此処で討たれていた私が、今は違う。アカツキの居ないこの盤面では――もう、私が負ける道理は何処にもありません", tid: "ch07__b09_last_stand__14" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "御託はいい。お前を殺す、それだけだ!", tid: "ch07__b09_last_stand__15" },
  { name: "神", who: "el_goddess", expr: "normal", text: "無論、大人しく殺されるつもりは更々ありません。私はここで貴方達を殺します。――目覚めなさい、バアル", tid: "ch07__b09_last_stand__16" },
  { text: "神の少女が杖に手をかざす。煙のように曖昧な何かが、一瞬にして実体を得た。小麦色の肌、白髪に赤い鉢巻、両手に五枚刃の鉤爪。｜原初《げんしょ》の魔王――聖剣の中に封じられた、最初の魔王バアル。", tid: "ch07__b09_last_stand__17" },
  { chara: { slot: "right", id: "baal", expr: "normal" } },
  { name: "バアル", who: "baal", text: "ようやく出番か。全員殺せば良いんだな?特に、あの男を", tid: "ch07__b09_last_stand__18" },
  { fx: "shake" },
  { text: "クロセルが半透明の身体で前に出る。瀬野が震える手で銃を構える。ティアが、泣きながら詠唱を始める。だが――", tid: "ch07__b09_last_stand__19" },
  { chara: { slot: "lcenter", id: "crocell", expr: "angry", ghost: true } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人に、指一本触れさせはしない!", tid: "ch07__b09_last_stand__20" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "属性魔術……｜水弾《ウォーターボール》・｜雨《マシンガン》!", tid: "ch07__b09_last_stand__21" },
  { se: "magic" },
  { fx: "flash" },
  { text: "再構築途中の身体では、大魔術は撃てない。絞り出した無数の水弾がバアルに殺到する。が、その鉤爪の一振りで全てが霧散した。バアルは強靭の才能を持っている。生半な攻撃は、その肉体に触れた瞬間に砕け散る。", tid: "ch07__b09_last_stand__22" },
  { name: "バアル", who: "baal", expr: "normal", text: "効かねぇんだよ、そんな攻撃", tid: "ch07__b09_last_stand__23" },
  { fx: "shake" },
  { text: "瞬間、バアルが地を蹴った。十メートルの間合いが、一瞬で消える。鉤爪の刃が、半透明のクロセルを横薙ぎに薙ぎ払った。", tid: "ch07__b09_last_stand__24" },
  { fx: "red" },
  { fx: "shake" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご……主人……すまな……い……", tid: "ch07__b09_last_stand__25" },
  { hide: "lcenter" },
  { text: "クロセルの身体が光の粒子となって崩れ、一本の杖だけが、乾いた音を立てて転がった。反射技に二度嵌るような愚を犯した訳ではない。ただ純粋に――再構築しきれない身体では、｜原初《げんしょ》の魔王の一撃を受け切れなかった。それだけだ。", tid: "ch07__b09_last_stand__26" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "クロセル!!!", tid: "ch07__b09_last_stand__27" },
  { chara: { slot: "rcenter", id: "zeno", expr: "scared" } },
  { name: "瀬野", who: "zeno", expr: "scared", text: "僕が……僕がやらなきゃ……!", tid: "ch07__b09_last_stand__28" },
  { text: "瀬野が時間を止める。完璧なタイミング、完璧な狙い。必中の弾丸が、バアルの胸に吸い込まれた。だが――時間が動き出した時、潰れた弾丸が、バアルの足元に転がっているだけだった。", tid: "ch07__b09_last_stand__29" },
  { name: "バアル", who: "baal", expr: "normal", text: "鉛玉如きで俺が殺れるかよ", tid: "ch07__b09_last_stand__30" },
  { fx: "flash" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "あ……", tid: "ch07__b09_last_stand__31" },
  { text: "止まった時間の中で動けたのは瀬野だけ。だがその一撃が通じなかった瞬間、勝負は決していた。鉤爪が翻り、瀬野の細い身体は床に沈んだ。", tid: "ch07__b09_last_stand__32" },
  { hide: "rcenter" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "(……強靭の才能。アカツキが居れば――｜亜空切断《ディメンションカッター》で、空間ごと断ち切れたのに)", tid: "ch07__b09_last_stand__33" },
  { text: "そうだ。本来の歴史なら、ここでスタングレネードで目を眩ませ、その一瞬の隙にアカツキの空間魔術がバアルを両断する筈だった。強靭だろうと、存在する空間そのものを切られれば抗えない。だが――その切り札たるアカツキは、もう此処には居ない。", tid: "ch07__b09_last_stand__34" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "それでも……!", tid: "ch07__b09_last_stand__35" },
  { text: "俺は腰のスタングレネードを引き抜き、バアルへ投げつけた。閃光と轟音。バアルの視界と聴覚が、確かに一瞬奪われる。好機だ。だが――この隙を勝利に変える刃が、俺達にはもう無い。空間を断つ手が、欠けている。", tid: "ch07__b09_last_stand__36" },
  { fx: "flash" },
  { name: "バアル", who: "baal", expr: "normal", text: "……仕掛けは見えたが、詰めが甘ぇな。誰も俺を斬れねぇんだろ?", tid: "ch07__b09_last_stand__37" },
  { text: "閃光が晴れる。バアルは無傷のまま、嗤っていた。とどめの刃は、ついぞ振るわれなかった。アカツキの居ない盤面では、｜原初《げんしょ》の魔王を討ち漏らす――ただそれだけの、当たり前の帰結。", tid: "ch07__b09_last_stand__38" },
  { name: "ティア", who: "tia", expr: "sad", text: "ヤマト……ごめんなさい……わたしのせいで……わたしが弱いから……", tid: "ch07__b09_last_stand__39" },
  { text: "ティアの詠唱は、最後まで紡がれる事はなかった。再び響いた御告げが、少女の意識を闇に沈める。神は自分の駒を、壊しはしない。それが一番、残酷だった。", tid: "ch07__b09_last_stand__40" },
  { text: "戦いは、戦いにすらならなかった。バアルの強靭は破れず、刃は届かず、時間を止めても何一つ届かない。一人、また一人と、仲間が崩れ落ちていく。", tid: "ch07__b09_last_stand__41" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "やめろ……やめてくれ……俺だ!俺を殺せば終わるんだろ!?", tid: "ch07__b09_last_stand__42" },
  { name: "神", who: "el_goddess", expr: "normal", text: "えぇ、終わります。バアル、あの男を。――そして、最後まで見ていてください。アカツキを選ばなかった、貴方のその選択が作った結末を", tid: "ch07__b09_last_stand__43" },
  { text: "バアルが俺の前に立つ。鉤爪が振り上げられる。神の瞳には、憎しみも、怒りもない。ただ静かな、観測者の色だけがあった。", tid: "ch07__b09_last_stand__44" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "俺の選択は……間違って、たのか……?アカツキ……ティア……クロセル……", tid: "ch07__b09_last_stand__45" },
  { fx: "shake" },
  { text: "薄れゆく意識の中、最後に見えたのは、心から愉しそうに微笑む神の顔だった。", tid: "ch07__b09_last_stand__46" },
  { name: "神", who: "el_goddess", expr: "normal", text: "「こちらの物語も、見てみたかったんです」", tid: "ch07__b09_last_stand__47" },
  { text: "正しい優しさが、世界を救えるとは限らない。アカツキを欠いた一行は、｜原初《げんしょ》の魔王バアルを討てぬまま、潰えた。", tid: "ch07__b09_last_stand__48" },
  { fade: "out" },
  { hide: "all" },
  { jump: "ending:bad_paradox" },

  // ===== Scene 6: gremory_vs_laplace (EP119 アデュー) =====
  { label: "gremory_vs_laplace" },
  { bg: "arcadia_upper" },
  { bgm: "battle" },
  { fade: "in" },
  { comment: "視点: グレモリー" },
  { pov: "gremory" },
  { chara: [ { slot: "left", id: "gremory", expr: "normal" }, { slot: "right", id: "laplace", expr: "laugh" } ] },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "さて、こっちも始めましょうか" },
  { text: "魔剣ラプラスは準備運動とばかりに軽く聖剣フルティンを振る。そして、片手で構えると、そのままこちらに向かって走り出す。" },
  { text: "私も腰の魔剣グレモリーを抜く。魔剣グレモリーが魔剣グレモリーを抜く、一見するとおかしな文脈だが、本来はこれが正しい魔剣の在り方だ。" },
  { text: "魔剣が本体で、それに付属する形で肉体が存在する。魔剣自体が人の形に変化するのはクロセルとラプラスだけだ。" },
  { text: "ラプラスの高速の斬撃を顔の前で受け止める。至近距離で｜鍔迫り合い《つばぜりあい》になりながら、私は小さく笑う。" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "ふん、お前の事は前から気に食わないと思っていた、丁度いい、ここで｜鬱憤《うっぷん》を晴らすとしよう" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "へ?何ですか?もしかしてボクに勝てるとでも思っているんですか?あはっ……あははははは!なんて馬鹿なんだ、｜魔杖《まじょう》クロセルの足元にも及ばない弱小魔剣がボクに勝てる訳無いじゃないですか!" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "｜魔杖《まじょう》クロセルは魔剣の中でも例外だからな、基本的には世代が新しい魔剣の方が強力なのが常識だ" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "は?最新機種だからって調子に乗るなよ?｜魔杖《まじょう》クロセルが例外ならボクも例外だ、ただの魔剣が勝てる訳無い!" },
  { text: "随分と喜怒哀楽の激しい人物だ。愉快に笑っていたかと思えば急に怒り出す。本人や主が\"悪魔\"と形容するのも理解できる。こいつは根本的に狂っている。" },
  { text: "剣に力を込めながら、冷静に分析する。力では互角。だがこいつには未来視の才能がある。攻撃を防ぐのは容易だが攻撃を加えるのは難しい。中々に厄介な相手だ。" },
  { text: "剣圧が弱まったのを確認すると、切り払いながら後方に飛び退く。お互いに詠唱を開始、恐らく目的は同じ。" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "無尽の魔力とやら、試させて貰おうか……｜魔術回路構築《クリエイト》……詠唱\nロ・フォース・アダマイト・ティロ\n炎魔術……｜炎帝覇気《インペリアルオーラ》" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "身体強化魔術ですか、ずるいですねぇ……ま、ボクも使えるんですが、｜魔術回路構築《クリエイト》……詠唱\nロ・ダーム・ヴェリテイル・ティロ\n闇魔術……｜魔神覇気《インペリアルオーラ》!" },
  { se: "magic" },
  { fx: "flash" },
  { text: "私の身体の奥底で魔力が燃え上がる。それは視覚的な効果としても現れる。使用したのはお互いに最上位の強化魔術。私の身体が赤いオーラで包まれ、熱を放つ。目の前のラプラスも、私と同じように紫色のオーラを纏う。" },
  { text: "余談だが、最上位の強化魔術は各属性ごとに存在する。そして属性ごとに僅かだが効果に違いがある。" },
  { text: "炎属性の強化魔術の効果は熱に対する耐性を持つ事だ。最上位ともなれば、極寒の環境でも炎の中でも活動できる。闇属性の強化魔術は強力な暗視効果。主に夜での戦闘で優位を取れる。……今回はどちらもあまり関係が無いが。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "それでは再開といきましょうか" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "かかってこい" },
  { text: "身体の中で急速に魔力がくべられていくのを感じる。だが、魔力で構成された肉体の存在が希薄になる感覚は無い。つまり膨大な魔力消費がありながら私の身体は殆ど魔力を失っていない。これが、主の無尽の魔力という奴だろう。理屈は不明だが、強力な力だ。" },
  { text: "身体強化魔術の欠点はその驚異的な魔力消費量である。それは目の前のラプラスとて例外ではない。神も無尽の魔力を持っているならば話は別だが、件の夜の事を考えるとそれは考えにくい。つまり、長期戦になればなるほど、こちらが有利だ。" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "さぁ、ショータイムだ!" },
  { fx: "shake" },
  { text: "ラプラスが地面を蹴り、切りかかってくる。横薙ぎの一閃を受け止め、切り払う。軽い。軽すぎる。強化魔術のランクはこちらが上か。これならしっかりと攻撃を見切っていれば被弾する事は無い。" },
  { text: "高速の斬撃の応酬。袈裟掛けに放たれた剣戟を踊るような動作で打ち返す。技量の高い物同士の戦いは、傍から見ればダンスのように見えるらしい。特に、その剣に殺意が無ければ猶更である。もはや何度目か分からない攻撃を防ぎながら、私は淡々と時間を数えていた。" },
  { name: "ラプラス", who: "laplace", expr: "sulk", text: "時間稼ぎをしようとか考えてます?" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "時間を稼ぐ必要などない、お前はここで私に敗れるのだからな" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "強気ですねぇ……ボク未来見えるんですけど" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "魔眼系の才能を発揮する時は目が発光する、お前にはその様子が見て取れない、つまりお前は未来など見ていない" },
  { name: "ラプラス", who: "laplace", expr: "sulk", text: "へー……良く知ってますね" },
  { text: "露骨に声のトーンが下がる。この様子だと図星か。だが、何故使わない?未来視の才能を使えば圧倒的な有利を取れる。それを敢えて温存する理由はなんだ?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "ま、要するに使わなくてもボクが負けるわけないので?" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "そうだといいな!" },
  { text: "どちらにせよ、これは好機だ。未来視を使われれば不利。だが力は互角、今なら勝機はある。一気に踏み込み、ラプラスの懐に潜り込みながら切り上げる。ラプラスはそれを受け止めるが、軽い。" },
  { text: "近接戦闘において重さは即ち力だ。体重を乗せた一撃の威力は文字通り体格や体重に依存する。その点において、ラプラスは軽すぎる。華奢な少女の姿を取っているからだ。" },
  { text: "下からの攻撃を受け止める際に、地に足を張って威力を殺す事が出来ない。下からの攻撃を抑え込めるのは体重のみ。それが欠けているラプラスは、この攻撃を受け止められない。" },
  { text: "故に……ラプラスの身体が宙に跳ね上がる。流石と言うべきか、姿勢こそ崩さないが、それでも空中では自由に身動きが取れない。推定、着地まで1.4秒。これだけあれば十分だ。" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》\n炎魔術……｜炎槍《フレイムランス》・｜射《ショット》" },
  { text: "詠唱省略での魔術の発動の経験はある。戦闘において数秒の詠唱時間の短縮はとても大きいからだ。反面、反動も大きい。魔力消費は倍以上だし、神経も摩耗する。連発出来る物ではない。" },
  { fx: "flash" },
  { text: "私が突き上げるように挙げた手のひらから、炎の槍が生み出され、矢の如く放たれる。その軌道は、ラプラスの身体を完全に捉えていた。最後の抵抗とばかりに身を捻るが、攻撃範囲からは逃れられない。" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "避けられ……!?" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "うぐっ……ああああああああ!?" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "悪いが徹底的にやらせて貰う、止めだ" },
  { text: "炎の槍がラプラスの胸を深々と貫き、胸元から広がるようにして全身を炎が包む。そして、そのまま燃焼しながら地面に落ちてくる。私は剣を構え直すと、そのまま倒れたラプラスに近付き、止めを刺そうとする。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "なんてね?" },
  { text: "ラプラスが小さく呟きながらニヤリと笑う。その時、私は異変に気が付く。ラプラスに実体がない。そう、ラプラスの身体には傷一つ付いていないのだ。私の魔術は命中した、対魔力の才能を持たないラプラスならば深手を負うはずである。それが無いという事は……" },
  { name: "グレモリー", who: "gremory", expr: "angry", text: "なっ……｜偽物《フェイク》か!?本体は!?" },
  { fx: "shake" },
  { text: "高笑いと同時に、偽物のラプラスの身体が透明化して消え失せる。まずい。危険を察知してその場から離れようとする。が、出来なかった。両腕両足に地面から生えた紫色の触手が巻き付いている。" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "｜魔術回路改竄《カスタマイズ》……" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "遅い!残念だけどボクの勝ちだ!" },
  { text: "方向は……上!本体は天井に潜んでいたか。ラプラスが未来視を使っていなかったのも、あのあまりの手応えの軽さも、あれが魔力で作られた偽物だったとすれば｜辻褄《つじつま》は合う。" },
  { text: "略式詠唱で拘束を解こうとするが、間に合わない。空から降ってきたラプラスは、偽物の肉体からフルティンを掻っ攫い、そのまま流れるような動作でこちらに猪突してくる。" },
  { text: "何か、何か活路は無いか。生憎、私には特に特別な武器は渡されていない。万事休す。だが私は諦めない。私は諦めの悪い女だ。命尽きるその瞬間まで、可能性があるならば足掻く。" },
  { text: "魔術は間に合わない。なら力づくだ。腕に力を込め、拘束を解こうとする。瞬間、奇跡が起きた。" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "死ね!グレモリー!" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "――死ぬのはお前だ、ラプラス" },
  { se: "slash" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "バチンと何かが弾ける音と共に私の右腕の拘束が解ける。もはや、その理由など考えている暇はない。大きく剣を後ろに振りかぶった姿勢で懐に入ってきたラプラス、その胸元に向けて、私は剣を突き上げた。" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "……は?" },
  { fx: "red" },
  { text: "ラプラスの攻撃は止まらない。聖剣フルティンは、見事に私の首を切り落とす。視界が落下し、世界が横に傾く。首より下の感覚は無い。" },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "は?は?はぁぁぁぁぁぁ!?なんで動けたんだ!?ボクの未来ではこんな筈じゃ!?" },
  { text: "私は目だけを動かす。そこには胸に深々と魔剣グレモリーが突き刺さったラプラスと……片手を私に向けて立っているアカツキの姿が目に入った。" },
  { name: "グレモリー", who: "gremory", expr: "smirk", text: "……なるほどな、これは後で感謝を述べなければ" },
  { fx: "clear-red" },
  { text: "ふっ、と私は小さく笑うと、そのままゆっくりと視界が暗転する。魔剣の本体は剣だ。肉体が破壊されても死ぬわけでは無いが、再構築まで時間は掛かる。" },
  { text: "アカツキがこちらに加勢したということは、主とアカツキは勇者ティアに勝利したのだろう。そしてラプラスも落とした。これは、私達の勝利だ。" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { comment: "視点: アカツキ" },
  { pov: "akatsuki" },
  { chara: [ { slot: "left", id: "akatsuki", expr: "serious" }, { slot: "right", id: "laplace", expr: "surprised" } ] },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "グレモリーさん!くっ……僅かに間に合いませんでしたか……" },
  { text: "私が駆け付けるのがあと少し早ければ、グレモリーさんを救えた。僅かな後悔を覚えながらも、私はラプラスと対峙する。ヤマトさんもグレモリーさんも倒れた。今戦えるのは私しか居ない。" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "アカツキ!?お前は死ぬはずじゃ……いや、両方生き延びる!?この曖昧な未来はなんだ!?何が未来を不確定にしている!?" },
  { text: "ラプラスの目がチカチカと青く点灯する。あれは未来視の才能を使っているのだろう。胸には深々と魔剣グレモリーが突き刺さっているが、抜こうとしない。そして、何か必死そうに呟いていたかと思えば、瞳の点滅が止まり、青く発光したままになる。あれは……未来が確定した、という事だろうか。そして、その瞬間、ラプラスは大声で笑いだした。心底楽しそうに。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "くっ……くくく……あははははは!面白い!これはこれで面白いじゃないか!ボクはここで退場しておこう。この座標での結末は確定した、もうボクの仕事は終わりだ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "貴方は何を言ってるんですか……説明を" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "は?敵にそんな事を説明すると思います?あぁするとも、説明しよう!だが残念!時間切れだ、ではアカツキ、アデュー、別の座標でまた会いましょう" },
  { text: "いきなりキレたかと思えば、にっこりと笑顔を浮かべて、名残惜しそうに悲しげな表情を浮かべたかと思えば、再び笑顔を浮かべて。" },
  { fx: "flash" },
  { text: "ラプラスの肉体は粒子状に変化し、バラバラになった。そこには三本の剣、フルティン、グレモリー、ラプラスが残された。" },
  { hide: "right" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "また会おうって……私が見逃す訳無いじゃないですか" },
  { text: "私は聖剣フルティンを手に取る。そして、それを両手で振り上げると、魔剣ラプラスに向けて振り下ろした。" },
  { se: "slash" },
  { fx: "flash" },
  { text: "音が鳴った。パリンと砕ける音。思っていたよりも綺麗な音色だった。金属を破壊したとは思えない程に。いや、破壊したのは金属ではない。魂だ。魔剣ラプラスはこれで、完全に破壊された。" },
  { bgm: "sad" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "最後まで貴方の事は分かりませんでした……最低の屑だってのは分かりますが、憎み切れないのも事実です、実際……貴方が本当に悪魔ならば、｜魔窟《まくつ》で私達の旅は終わっていたんですから" },
  { text: "もう聞こえていないだろう。それでも、私は別れの言葉を呟かずにはいられなかった。光の粒子となって、空気に溶けていく魔剣を見ながら、私は静かに告げた。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "さようなら、悪魔ラプラス" },
  { fade: "out" },
  { hide: "all" },
  // ===== Scene 7: pope_final (EP120 代行者) =====
  { label: "pope_final" },
  { bg: "arcadia_upper" },
  { bgm: "battle" },
  { fade: "in" },
  { comment: "視点: クロセル → 瀬野" },
  { pov: "crocell" },
  { chara: [ { slot: "left", id: "crocell", expr: "serious" }, { slot: "center", id: "zeno", expr: "scared" }, { slot: "right", id: "shellmi", expr: "smug" } ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "分断……これが教皇の狙いか" },
  { text: "完全に閉じた空間の穴の前で、私は冷静に呟く。｜迂闊《うかつ》だった。これほど分かりやすい罠に｜嵌《は》まるとは。こっち側に残されたのは私、瀬野、シェル公爵の三人だ。" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "どうしよう……クロセルさん" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "こっちはゼノとシェル公爵か……" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "さっきの部屋と再び繋げられないのかね?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "少し時間を掛ければ可能だ、魔術障壁を破って空間を繋げる、数分もあれば出来る、だが……" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "なるほどね、｜邪魔《じゃま》が入るのは必然か……ほら、見るが良い。盛大に出迎えて貰えるようだよ" },
  { text: "シェル公爵が片手で指した方向に視線を送ると、そこには二人の人影が。長杖に儀礼的な服を纏った老人、教皇イヴ・エンド。刀を携え黄金の鎧に身を包んだ青年、勇者ニコラス。" },
  { chara: [ { slot: "left", id: "crocell", expr: "normal" }, { slot: "center", id: "eve_end", expr: "normal" }, { slot: "right", id: "nicholas", expr: "serious" } ] },
  { name: "瀬野", who: "zeno", expr: "scared", text: "ど、どうするの?クロセルさん" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我々に選択肢はない。決めるのは向こうだ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "無論、通すつもりはありませんよ" },
  { text: "教皇は優しげな笑顔を浮かべながら、淡々と言い放つ。そして、杖を顔の前でくるくると回すと、そのまま地面に突き立て、目を見開く。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "我らが神を害する者は、誰であろうと容赦しません!行きますよ、大英雄ニコラス" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "お任せください" },
  { text: "教皇の号令と共に、勇者が駆ける。そこには｜一縷《いちる》も迷いはない。という事はつまり……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "勇者……お主、本心から神に仕えているな?" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "当然だ、僕は正義の執行者。大英雄ニコラス。神に牙を剥いた君達を成敗する" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "――属性魔術 ｜氷剣《アイシクルソード》" },
  { se: "magic" },
  { text: "私は無詠唱魔術で氷の剣を生成する。そしてそれをシェル公爵の方に投げ付けた。剣は空中をくるくると回りながら飛んでいき、シェル公爵の前の地面に突き刺さる。" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "これは?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "使え、素手では分が悪いだろう。我は先に教皇を倒す、勇者の相手は任せたぞ" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "剣の扱いはあまり得意では無いのだがね。まぁいい、無いよりはましだ" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "良いだろう、任せられた" },
  { text: "シェル公爵は地面に刺さった剣を抜き、素振りとばかりに片手で軽く振るう。彼女は私よりも昔から生きている賢者だ。能力では劣っていても、その知識では敵わない。" },
  { text: "彼女の膨大な知識から繰り出される戦闘技術は、才能持ちの人間を凌ぐほどだ。無論、身体強化魔術による補助を前提とした話ではあるが。" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "えっと……僕は……?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……死ぬな?" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "それだけ!?あとなんで疑問形!?" },
  { text: "ぶっちゃけゼノは戦力外だ。前線で戦っては寧ろ足手まといになる。だから、取り敢えず死なないように大人しくしてて貰うのが一番だろう。" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "聖剣抜刀……ニコラス流……ニコン式奥義……ヒーローアターック!" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "そんな大振りの攻撃が当たるとでも?" },
  { text: "勇者は聖剣を抜刀、大きく頭上に振りかぶると、そのままシェル公爵頭蓋目掛けて斬り下ろす。それをシェル公爵は、鼻で笑いながら飛び退いて｜躱《かわ》す。いや、ダメだ。あの攻撃は……" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "違う!防げ!シェル公爵!" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "なに?っ!" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "私の声を聞き、シェル公爵が氷の剣を眼前に構えたのと、勇者の剣先から放たれたビームが着弾するのはほぼ同時だった。ビームは数秒の間持続し、その勢いでシェル公爵は後退する。そして、ビームが止んだ事を確認すると、シェル公爵は息を吐きだしながら剣を払う。" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "何故剣からビームが出るのか説明して貰えるかな" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "我も知らん!ご主人曰く勇者が聖剣振ったらビームが出るのはお約束らしいぞ" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "意味が分からないのだが……それとまずいぞ、今ので剣が使い物にならなくなった" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なんだと?" },
  { text: "言われた通りシェル公爵の手元の剣に視線を送ると、板状に溶けて変形していた。あのビームを耐えられたのが奇跡と言った所か。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "待て、もう一度生成する" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "いや、その必要は無い。――｜複製《ディプケーション》" },
  { text: "シェル公爵は変形した剣を地面に捨てると、手を前に突き出し呟く。その一言を紡ぎ終わると同時に、シェル公爵の手には再び氷の剣が握られていた。" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "物質複製の才能か" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "あぁ、そうだよ、言っていなかったか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "妖精は多くの｜稀有《けう》で優秀な才能を持つ、物質複製の才能など……我も初めて見た" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "感心してる場合かね?" },
  { text: "勇者はシェル公爵に任せて良さそうだ。私は教皇に視線を移す。杖を地面に突き立てたまま、口元が動いている。教皇の主な才能は三つ。杖術6と光魔術6、そして代行者9。" },
  { text: "代行者の才能の効果は不明だが、才能指数9である以上、確実に脅威となるのは必至だ。ご主人なら分かるだろうが、私の知識では推測する以上の事は出来ない。警戒は怠らないようにせねば。詠唱する時間を稼がれたか!" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "――光魔術……｜神罰代行《ゴッドパニショメント》・｜神魔鎖錠《ホールロック》" },
  { fx: "flash" },
  { text: "教皇の魔術が発動する。私の足元と頭上に光を放つ穴が生まれ、中から光の鎖が無数に飛び出てくる。鎖は私の前後左右を囲むように張られ、そのまま私の全身に絡み付く。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ぐあっ……" },
  { text: "鎖が私の身体を締め付ける。焼けるような痛み。ただの圧迫から来る痛みではない。鎖自身がマグマの如く熱を帯びているかのような痛みだ。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "これは生涯で重ねた罪の分だけその身体を痛め付ける魔術、魔王であった貴女にはよく効くでしょう" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "くくく……あぁ確かにこれは効くな……だが!この程度の痛み、我が今まで受けた苦痛に比べれば痒くも無い!｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……\n――属性魔術 ｜纏刃《スラッシュボディ》・｜闇《ダークネス》!" },
  { fx: "flash" },
  { text: "全身に走る痛みに耐えながら、私は魔術を発動する。それは属性を付与した刃を纏い、触れた物を切り裂く魔術。光魔術に対抗する一番の方法はより上位の闇魔術を使う事だ。実際、才能指数では私が勝っている。私の身体に巻き付いていた光の鎖は粉々に断たれ、光の粒子になって消えていく。" },
  { text: "追加とばかりに上下から光の鎖が伸びて来るが、それも私の身体に触れる前に霧散していく。こうして拘束を解くと、私は教皇に向けて手を｜翳《かざ》す。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "やはり私の魔術では抑え切れませんか……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "これで終わりだ、教皇……｜魔術回路構築《クリエイト》……詠唱\nロ・アイス・エネミリィルヴァラメンツ・ティル\n――属性魔術 ｜絶大零砲《アブソリュートゼロキャノン》・｜終焉《ファイナル》" },
  { se: "magic" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "各属性における最高位の攻撃魔術四種の内の一つ。対単体における最強の魔術であり、私の最終兵器だ。放たれるは極太の光線。触れた物を全て凍て付かせ、素粒子に至るまで破壊する白銀色の光。これを使えるのは恐らくこの世界で私とご主人しか存在しない。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "……ふっ" },
  { text: "教皇は、笑った。優しげで、穏やかな笑顔を浮かべる。何故?" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "私は神の代行者、第六権能発動\n――『天罰｜覿面《てきめん》』" },
  { fx: "flash" },
  { text: "まずい。そう思った時には遅かった。私の推測が正しければ、代行者の才能は他人の能力を自分の物として借り受ける力。つまり、教皇は神の権能を代行して使う事が出来る。神の権能は全部で七種類。その全ては判明してない。そして、今教皇が発動した権能は何だ?教皇の身体が光に包まれる。私の放った光線の光ではない。" },
  { text: "光を纏った教皇が、更に上から私の光線で包まれる。目も眩むような眩い光の中、私の放った光線は全てを凍らせ、砕き、破壊する。遥か彼方に外が見える。光線は上層の数十枚の壁を破り、外まで至ったのだ。我ながら恐ろしい破壊力だ。教皇が何らかの防御措置を取ったにしろ、これでは……" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なっ……" },
  { text: "光線が収まる。だが辺りを包む光は衰える事が無い。その光は、教皇の身体から放たれていた。あの攻撃を受けて原型を留めている。そして、光が一層強くなったかと思えば……教皇の身体から白銀色の光線が放たれる。\n――私に向かって。" },
  { text: "攻撃範囲が広すぎて回避は出来ない。｜掠《かす》れば終わり。これはそういう魔術だ。教皇の使った権能は恐らく、攻撃の反射。｜迂闊《うかつ》だった。今更どんなに反省しても遅い。もう私は負けたのだ。" },
  { fx: "red" },
  { fx: "shake" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "がはっ……" },
  { text: "圧倒的な質量で押し潰される。身体がバラバラになり、感覚が消失する。死ぬことは無い。杖に戻るだけだ。だが、瀬野とシェル公爵の二人で勇者と教皇に勝てるだろうか?……信じるしかない。そして私は意識を失った。" },
  { fx: "clear-red" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { comment: "視点: 瀬野" },
  { pov: "zeno" },
  { chara: { slot: "left", id: "zeno", expr: "scared" } },
  { name: "瀬野", who: "zeno", expr: "scared", text: "僕がやるんだ……" },
  { text: "僕は拳銃を握り締める。霧雨組に所属していながら、僕はまだ、人を殺した事が無い。その覚悟が、まだ決まっていなかった。だが、今がその時だと｜警鐘《けいしょう》が鳴る。" },
  { text: "分かるんだ。感覚的に。このままだとクロセルさんかシェルさんのどちらかが負ける。だから僕も戦わなければならない。" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "(動け!動け!動け!)" },
  { text: "足が震える。指に力が入らない。それでも戦わなければ。何の為に?僕は何の為に戦うんだ?……そうだ、ヤマトの為だ。僕の命はヤマトの為にある。一度捨てた命。死を超えたこの命。自分ではない誰かの為ならば、僕は動ける。" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "はっ……クロセルさん!" },
  { text: "目の前で起きている事を上手く理解できない。僕はヤマトほど頭が回らないから。それでも分かることがある、あの教皇さんの笑顔。確実に何かある。何らかの秘策があるのだろう。逆に言えば、教皇さんは自身の思惑通りに事が運んでいる事から慢心している。" },
  { text: "僕は拳銃の引き金に指を掛ける。狙いは付けない。まだ早い。タイミングが肝心だ、教皇さんがクロセルさんを倒して油断する一瞬。それが唯一の隙だ。" },
  { text: "帝国の技術力で作られた自動式拳銃、この世界ではオーバーテクノロジーに分類される。魔王の配下であるテラという機械技師に協力して貰って作れた物だ。だから厳密には僕が作ったわけじゃない。まぁそこはどうでも良いんだ。弾薬は元の世界と同じ9パラ弾。装弾数は7発。予備のマガジンは二つ。武装の確認を済ませると、僕は神経を集中させる。" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "瀬野", who: "zeno", expr: "sad", text: "っ……ごめんなさい" },
  { text: "僕は、クロセルさんが魔術を放ち、それを教皇が跳ね返す一部始終を見守っていた。僕にもう少し力があれば、クロセルさんを守れたかもしれない。そんな事を｜仄《ほの》かに思いつつも、僕の意識は教皇さんに向いていた。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "神に逆らうというのは、こういう事です" },
  { text: "教皇さんは、消滅するクロセルさんを見ながら、憐れむように呟く。僕はその\"背中\"を見ながら、静かに拳銃を構える。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "pain", text: "……!?後ろ……いつから!?" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "……ごめんね" },
  { text: "教皇は一瞬にして僕の気配を感じ取ると、回避姿勢を取ろうとする。だが、｜猶予《ゆうよ》は十分すぎた。能力を発動する。僕以外の時間が止まる。この世界で今動けるのは僕だけだ。時間操作による時間停止、僕の力では5秒も維持は出来ないが……冷静に狙いを定めて、僕は引き金を引く。" },
  { se: "gunshot" },
  { fx: "flash" },
  { fx: "shake" },
  { hide: "center" },
  { text: "放たれた弾丸が、教皇さんの頭蓋を撃ち貫くと同時に時間は進み始める。多分、教皇さんには何が起きたか理解できなかったのだろう。" },
  { text: "空間操作で一瞬にして背後に回り、時間を止めて確実に弾丸を当て、殺す。今までは机上の空論だったが、まさか実際に出来てしまうとは思わなかった。教皇さんが地面に倒れ込む。" },
  { text: "｜断末魔《だんまつま》は無かった。即死だったのだろう。\n――これで、僕は初めて人を殺した。" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "思ったより……何も感じない" },
  { text: "人を殺す。それは虚無だ。罪悪感を感じる事も、嬉しいとも悲しいとも思わない。ただ殺人という事実だけが僕という存在にレッテルを貼り付ける。\nあぁ、もう戻れないんだ。それだけ。そう思った。" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "シェルさんの方も助けないと……" },
  { text: "教皇さんは片付いた。人の命とは呆気ないものだ。神の力を借り受ける代行者でも、人である以上、死からは逃れられない。シェルさんと勇者は接戦を繰り広げていた。" },
  { text: "地面には使い物にならなくなった氷の剣が無数に散らばっている。勇者さんの意識は完全にシェルさんに向いている。僕など眼中にない。" },
  { chara: { slot: "center", id: "nicholas", expr: "serious" } },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "……!ゼノ君!?" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "ごめん" },
  { text: "僕の身体は勇者さんの後ろに移動し、時間が停止する。身体は鎧で守られているが、頭は無防備だ。教皇さんの時には3秒使った。今回は2秒で済んだ。時間が動き出す。勇者さんは頭から血を噴き出して……" },
  { chara: { slot: "center", id: "nicholas_damaged", expr: "serious" } },
  { name: "ニコラス", who: "nicholas_damaged", expr: "serious", text: "っ……痛いなぁ!" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "えっ!?死んでな……ぐはっ" },
  { text: "勇者さんの回し蹴りで僕の身体は宙を飛ぶ。なんて威力だ、人間の身体をこうも簡単に吹き飛ばすなんて。僕は壁に叩き付けられる。グシャッ……と嫌な音。確認すると、右足と左腕がありえない方向に曲がっている。激痛に悶えながら、僕は地面を這いつくばって勇者さんの方を見る。" },
  { chara: { slot: "right", id: "shellmi", expr: "smug" } },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "貴様、化け物かね?" },
  { name: "ニコラス", who: "nicholas_damaged", expr: "smile", text: "祝福の勇者を舐めないで貰えるかな……僕は死なないんだよ" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "これは厄介だな……｜魔杖《まじょう》クロセルが戦闘不能になった以上、身体強化魔術もどの程度持つか分からない……" },
  { text: "勇者さんは頭から大量の血を垂れ流しながらも、立っていた。どころか意識もある。戦闘を続行し、シェルさんの攻撃を防いでいる。" },
  { text: "あれが祝福の力か。失念していた。あれ……でも祝福はティアさんに移ったんじゃ無かっただろうか。また祝福がニコラスさんに移動したのだろうか。" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "右手は……動く……けど……" },
  { text: "足が使えなくなった以上、いつもの撃ち方はもう使えない。だが、似たような事なら出来る。僕は時間を停止させると、右手だけで勇者さんに照準を合わせ、引き金を引く。" },
  { text: "五発の弾丸が空中で｜数珠《じゅず》繋ぎのように浮かび、勇者に向かって飛んでいく。そして、着弾の瞬間、再び時間を動かす。" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "かはっ……" },
  { text: "僕は吐血する。｜眩暈《めまい》と頭痛が酷い、これは時間停止の反動だ。今回は5秒使った。" },
  { name: "ニコラス", who: "nicholas_damaged", expr: "pain", text: "発射した瞬間に着弾するのはどういう理屈なんだ……い" },
  { text: "五発の弾丸を頭に食らい、流石の勇者さんも地面に膝をつく。" },
  { text: "その隙にシェルさんは剣を構え直すと、勇者さんの心臓目掛けて一気に突く。鎧を貫通し、勇者さんの背中から剣が生える。" },
  { name: "ニコラス", who: "nicholas_damaged", expr: "pain", text: "くっ……" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "まだ立つか、化け物め" },
  { text: "勇者は再び立ち上がる。が……もはやまともに動けないらしい。シェルさんは再び氷の剣を複製すると、それを勇者さんの身体に突き刺す。それを何度も繰り返し、五本目の剣が勇者さんの身体を貫いた時、勇者さんは遂に地面に倒れ込んだ。" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "……死んだの?" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "生きている。が……暫くは動けないだろうね。何も出来ない無能かと思ったら、中々やるじゃないか、ゼノ君" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "僕も動けないんだけどね……これからどうする?ヤマトと合流出来るかな" },
  { name: "シェル公爵", who: "shellmi", expr: "normal", text: "｜魔杖《まじょう》クロセルが復活するまでは待機だな、私達の方が奥に進んでいるから、ダーリンが先に進めば合流出来るだろう" },
  { name: "瀬野", who: "zeno", expr: "scared", text: "その間に勇者さんが復活しないかな" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "あまり気が乗らないが、復活に時間が掛かるようにもう少し痛め付ける、君は見ない方が良いと思うがね" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "あはは……そうだね……" },
  { text: "犠牲は少なくない。それでも僕達はなんとかここを乗り越える事に成功した。後は、ヤマト達が無事である事を祈るだけだ。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 8: tia_loss (EP121 喪失) =====
  { label: "tia_loss" },
  { pov: null },
  { bg: "arcadia_upper" },
  { bgm: "tension" },
  { fade: "in" },
  { chara: [ { slot: "left", id: "yamato", expr: "sad" }, { slot: "center", id: "akatsuki", expr: "normal" } ] },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "……ヤマトさん!ヤマトさん!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "うるさい、聞こえている" },
  { text: "目覚めは最悪。二回の才能の解放の反動で頭痛が酷い。だが、まだ動ける。俺達はまだ何も成し遂げていないんだ。身体を起こし、ぼやけた視界のピントを合わせる。目の前には、アカツキ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "悪魔とグレモリーは?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "相討ちです、ラプラスは破壊しました" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前は……無事みたいだな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "はい、おかげさまで" },
  { text: "ふらふらとよろめきながらも、立ち上がる。俺の隣には魔剣グレモリーと聖剣フルティンが転がっていた。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "取り敢えず、凌ぎきったな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……はい……そうです……ね……" },
  { text: "俺は勝利に安堵する中。何故かアカツキの表情は暗い。あれ……そう言えば、何かを忘れている気がする。大切な何かを。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おいおい……なんだよアカツキ……俺達は勝ったんじゃないのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "勝ちました、ですが……" },
  { text: "アカツキは重々しく呟くと、目を伏せるようにして視線を移す。俺もそれを追うようにして頭を動かすと、それが目に入る。それは黒焦げになって原型を留めていないが、ティアだ。祝福が無ければ間違いなく致命傷だろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "こればっかりはエルに感謝しないとな、自爆とかいう手段こそ非人道的だが、ちゃんと死なないように祝福を与えている事は評価出来る" },
  { text: "俺はティアに近付き、おもむろに手を口元へと持っていく。祝福があるのだから、生存確認など必要ないが、確認せずにはいられなかった。大丈夫だ。ティアは。ティアは。" },
  { bgm: null },
  { wait: 800 },
  { se: "heartbeat" },
  { fx: "red" },
  { text: "――い き を し て い な い。" },
  { fx: "shake" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ぁ……あぁ……あああああああああ!?" },
  { text: "ジジッと視界にノイズが走る。一瞬の思考停止。そして叫び。理解できない。理解したくない。理解など出来るものか。俺は頭を抑え、叫ぶ。目の前の現実から目を逸らす。" },
  { bgm: "sad" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ごめんなさい……ティア様……ヤマトさん……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "嘘だ!祝福があるんだよな!?今は死んでるが、これから生き返るんだよな!?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……祝福は死者を生き返らせる才能ではありません。生者が死者とならない才能です。つまり……今のティア様に祝福はありません" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "嘘だ……ろ?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……ごめんなさい" },
  { text: "祝福は、いつの間にかニコラスの方へ戻っていた。俺は再び確認する。自分の観測が間違いであることを信じて。" },
  { wait: 500 },
  { text: "呼吸はない。" },
  { wait: 350 },
  { text: "だが脈は?" },
  { wait: 300 },
  { text: "ない。" },
  { wait: 400 },
  { text: "心臓は?" },
  { wait: 300 },
  { text: "動いていない。" },
  { wait: 500 },
  { text: "紛れもない。" },
  { wait: 650 },
  { text: "――死んでいる。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ハッピーエンドが好きなんじゃないのかよ……こんなの……何もハッピーじゃねぇ……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ヤマトさん……" },
  { fx: "shake" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ……エル!!!!!俺は!お前を!絶対に許さない!!!!!" },
  { text: "ティアが死んだ以上、観測者はもう居ない。つまり、エルには聞こえない。それでも、俺は怒りを表さずには居られなかった。俺はエルを、神を、必ず。殺す。動かなくなったティアを抱き締めながら、俺は呪いの言葉を吐き散らした。" },
  { fx: "clear-red" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさん" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるさい" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "先に進みましょう、今なら合流出来ます" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるせぇ!お前を選ばなければ……ティアは……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、その通りです、私が生き残ったからティア様が死んだ、それは紛れもない事実でしょう" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "くそっ……俺の選択は……間違ってたのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それを決めるのは今ではありません、私達には成し遂げなければならない事がある、そうでしょう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……分かった、先に進もう" },
  { text: "俺はティアの｜亡骸《なきがら》を優しく地面に置き、立ち上がる。アカツキが二つの剣を拾い上げ、先程閉じた空間の穴のある壁へと近付いていく。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "空間の穴が使えるのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、上層に存在する結界が全て消滅しました、恐らくは……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……教皇を倒したか" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "と、信じたい所です。｜魔術回路構築《クリエイト》……詠唱……\nル・トゥーム・アルガス・ティル\n空間魔術……｜接続《コネクション》" },
  { se: "magic" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { text: "アカツキが詠唱すると、壁に空間の穴が生まれる。それを潜り、俺達は先に進む。そこには、今まで居た部屋と同じような広間が広がっており、そこに見慣れた顔ぶれを見つける。" },
  { chara: [ { slot: "right", id: "shellmi", expr: "love" }, { slot: "center", id: "zeno", expr: "smile" } ] },
  { name: "シェル公爵", who: "shellmi", expr: "love", text: "ダーリン!会いたかった!" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "良かった、二人は無事だったんだね" },
  { text: "俺に抱き着いてくるシェル公を軽くあしらいながら、壁に寄りかかっている瀬野と、その横に転がっている｜魔杖《まじょう》を確認する。" },
  { name: "ヤマト", who: "yamato", text: "クロセルがやられたか" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "うん、でも教皇さんと勇者さんは倒したよ" },
  { text: "瀬野が右手で指差した方向を見ると、そこには倒れ込んだ教皇と、大量の氷の剣で串刺しにされた勇者の姿があった。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……祝福はニコラスの方にあったか" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "あぁ、祝福とは厄介な物だね、中々に手を焼いたよ" },
  { name: "ヤマト", who: "yamato", text: "よく倒せたな" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "教皇を倒せたのも、祝福の勇者を倒せたのも、あのゼノという男の活躍が全てだ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "瀬野がやったのか?" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "あはは……僕にしては頑張った方だと思うよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "酷い怪我だな" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "ヤマトもね、横腹から骨見えてるよ……" },
  { text: "言っていなかったが、服はアカツキに渡してしまった為、俺は上裸だ。失血でそろそろ意識が｜朦朧《もうろう》としてきた。応急処置をしないとまずいかもしれない。そう思っていると、瀬野の横に転がっていた杖が光りだす。辺りが閃光に包まれたかと思えば、そこには半透明の美少女が立っていた。" },
  { chara: { slot: "center", id: "crocell", expr: "normal", ghost: true } },
  { name: "ヤマト", who: "yamato", text: "半透明だな" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "うるさい、復活直後なのだから仕方ないだろう" },
  { text: "こうしてクロセルが復活した。俺と瀬野の治療、それとアカツキの分の服の作成。流石は俺の｜魔杖《まじょう》、便利な奴で、それらを全てこなしてしまった。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ふぅ、こんな物か" },
  { name: "ヤマト", who: "yamato", text: "お前にしては遅かったな、普段のクロセルならこの半分の時間で終わる筈なんだが" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "復活直後で弱体化してるのが見えないのかご主人は" },
  { name: "ヤマト", who: "yamato", text: "冗談だ" },
  { text: "これでひとまず体勢は整った。問題はこの後だ。" },
  { name: "ヤマト", who: "yamato", text: "クロセル、その姿で戦えるか?" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "前線を張るのは厳しいな、魔力だけはあるから後ろから魔術で援護する事は出来る" },
  { name: "ヤマト", who: "yamato", text: "グレモリーも復活直後は厳しいだろうし、俺とシェル公でなんとかするか" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "と言っても……神様の方の主戦力ってこれで全部じゃない?あとは神様をみんなで倒して終わりだと思うんだけど" },
  { name: "ヤマト", who: "yamato", text: "福音使徒は雑魚だし殆どの勇者は過去の俺が殺したみたいだしな" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "万全を期すならクロセルさんとグレモリーさんの回復を待つべきなんでしょうが" },
  { bgm: "tension" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、攻めるぞ。先手必勝だ、向こうも戦力を失ったからには体勢を立て直そうとしてるはずだ、今叩くのが一番だと判断する" },
  { text: "俺は立ち上がる。そして、その場にいる皆と顔を見合わせる。覚悟は出来てる。決意も十分。俺の選択が間違いじゃなかった事を証明する為にも、俺は神を殺す。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "アカツキ、聖域に直接繋げるか" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "分かりました。｜魔術回路構築《クリエイト》……詠唱……\nル・トゥーム・アルガス・ティル\n空間魔術……｜接続《コネクション》" },
  { text: "アカツキが近くの壁に向かって詠唱すると、お馴染みの空間の穴が生まれる。穴は長く、数十メートルはあるだろうか。途中で穴が閉じたらどうなるのだろう、というどうでもいい不安が浮かぶ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "行こう" },
  { text: "俺は仲間と自分に向けて、その一言を残す。そして、聖域に繋がる穴へと足を踏み出した。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 9: baal_summon (EP122 白と紅) =====
  { label: "baal_summon" },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { comment: "視点: ｜神《エル》" },
  { pov: "el_goddess" },
  { chara: { slot: "center", id: "el_goddess", expr: "blank" } },
  { name: "神", who: "el_goddess", expr: "blank", text: "この座標の未来は確定した" },
  { text: "私は手元の紙に浮かび上がった文字列を読み上げる。ラプラスからのメッセージだ。恐らくは最後の。あとは予定調和。私は用意されたシナリオをなぞるだけだ。それは決してハッピーエンドでは無いけれど。" },
  { chara: { slot: "left", id: "klaus", expr: "normal" } },
  { name: "クラウス", who: "klaus", expr: "normal", text: "神様、報告です" },
  { name: "神", who: "el_goddess", expr: "blank", text: "大凡予想は付きますが、聞きましょう、クラウス" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "用意していた二箇所の迎撃地点ですが、双方突破されました" },
  { name: "神", who: "el_goddess", expr: "blank", text: "敵の損害は" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "魔剣グレモリー、｜魔杖《まじょう》クロセルを無力化しました" },
  { name: "神", who: "el_goddess", expr: "normal", text: "よりにもよってその二人ですか……人間の方を一人も殺せないとは……" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "恐らく間もなく聖域に到達します、福音使徒を集めていますが……恐らく……" },
  { name: "神", who: "el_goddess", expr: "normal", text: "時間稼ぎにすらならないでしょうね" },
  { text: "私は溜息を吐く。" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "お言葉ですが……｜魔杖《まじょう》クロセルが戦闘不能になったので結界は消滅しました、ここは上層から脱出するべきでは?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "ラプラスの予言が正しければ、ヤマトが生き延びた場合、確実に結末は私の死という座標に至る" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "私にはよく分かりませんが……" },
  { name: "神", who: "el_goddess", expr: "normal", text: "説明するのも面倒ですね、要するに『ヤマトが生き延びた場合』に『今の時間座標で私が生存している』という可能性が消えるんですよ" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "おかしな話ですね、それではまるで、これからヤマトさんが生き延びた場合、何らかの手段で過去に行き、神様を殺す……と言ってるような" },
  { name: "神", who: "el_goddess", expr: "blank", text: "惜しいですね、実際はその逆です" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "……?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "まぁ、貴方に話しても意味がないことです、ただ事実は一つ、ここでヤマトを殺さなければ、私は死ぬ" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "分かりました、何としてでも神様をお守りします" },
  { name: "神", who: "el_goddess", expr: "blank", text: "えぇ、善処しなさい" },
  { text: "元から期待はしていない。それはお互い様だろう。私はヤマトのように頭が回る訳では無い。私は神だが、所詮は神の権能を宿しただけの人間なのだ。" },
  { text: "私の前の前、要するにエルの前の身体は優秀だった。卓越した剣術の才能。勇者じゃないのが惜しいほどに。エルの身体も悪くはなかった。飛び抜けた才能はないが、才能の数は良好、汎用性は高かった。" },
  { text: "それに対して、今の身体は力不足だ。戦闘系の才能は杖術3のみ。創造、天罰｜覿面《てきめん》、能力封印は全て防御系の権能である。これだけでは人は殺せない。" },
  { text: "今回は生き残るだけではダメなのだ。必ず、ヤマトを殺す必要がある。それなのに、私の手元には殺す為の手段が足りない。それでも、ラプラスの予言を信じるしかなかった。" },
  { fade: "out" },
  { hide: "all" },
  { pov: null },
  { fade: "in" },
  { text: "俺達が空間の穴を抜けると、そこには一面が透明なガラスのような建材で出来た広い空間が広がっていた。ここが聖域。神の、いや……エルの住む場所だ。俺たちはその端に立っていた。" },
  { chara: { slot: "left", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これが最終防衛ラインか" },
  { name: "アカツキ", text: "みたいですね" },
  { text: "そして、そんな俺達を取り囲むように十数人の福音使徒。その中には、俺の見知った人物の姿もあった。" },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "right", id: "klaus", expr: "normal" } ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前は……クラウスだったか" },
  { name: "クラウス", who: "klaus", expr: "normal", text: "覚えてもらえてるとは光栄だね、世界の反逆者" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "世界の反逆者……か、確かにそうだな、俺によく似合う、良い響きだ" },
  { text: "福音使徒の先頭に立つ青髪の青年。エルによく似ている。クラウス・シュルツヴェール。エル・シュルツヴェールの……いや、クリスタ・シュルツヴェールの兄であり、教皇に次ぐ地位を持った福音使徒だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前はエルに妹を奪われた、それでもお前は神に忠誠を誓うのか?" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "神様の｜依代《よりしろ》に選ばれるのはこの世で最も光栄な事だ、これはクリスタにとっても幸福な事だったんだ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "どうだか。神に身体を奪われるのは死ぬのと同じだ。神の権能を宿した人間は寿命が縮む。例え神が次の身体に移っても、その頃にはお前の妹の寿命は尽きる" },
  { name: "クラウス", who: "klaus", expr: "cold", text: "クリスタは……神に感謝しながら逝ったと聞いている……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "……狂ってるな、お前も妹も" },
  { name: "クラウス", who: "klaus", expr: "angry", text: "黙れ!狂っているのはお前達の方だ!崇高なる神様を殺すだと?そんな事が許されて良いはずがない!" },
  { text: "クラウスは大きな声で叫び、剣を構える。分かっている筈だ。彼らでは俺達に勝てない。それよりも衝撃な事実が、俺の心を揺れ動かす。クリスタが死んだ。俺と旅をしていたあの子はもう居ない。つまり、今のエルは新しい肉体を得たということだ。また……神の犠牲者が一人増えたことになる。" },
  { name: "シェル公爵", who: "shellmi", text: "ダーリンに剣を向けるとは良い度胸じゃないか、福音使徒" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "この数でクラウスはそこそこ腕が立つ、いけるか?" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "無論問題ない、｜魔杖《まじょう》クロセルの身体強化魔術があるからな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか、分かった……やれ" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "仰せのままに" },
  { fx: "shake" },
  { text: "俺の言葉と同時に、シェル公がクラウスの懐に飛び込んでいく。そこから先の戦いは一方的であった。氷の剣で数回の打ち合い、それだけでクラウスは姿勢を崩される。" },
  { name: "瀬野", who: "zeno", text: "ごめんね" },
  { se: "gunshot" },
  { fx: "flash" },
  { text: "瀬野の呟きと同時に、乾いた音が響き渡る。クラウスは大きく仰け反ったかと思うと、そのまま静かに倒れる。瀬野の拳銃でヘッドショット、即死だ。" },
  { hide: "right" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "命中精度おかしくないか?" },
  { name: "瀬野", who: "zeno", expr: "normal", text: "あはは……時間を止めて丁寧に狙ってるから、当てられない方がおかしいよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それとお前……殺しに躊躇いが無くなったな" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "そうだね……僕はもう変わったんだ" },
  { text: "そんな短いやり取りをしている間に、シェル公は一人で無数の福音使徒を相手取り、｜薙《な》ぎ倒していく。" },
  { name: "福音使徒", text: "あの男を狙え!神様はあの男さえ殺せれば良いと仰っていた!" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……俺?なんでだ?" },
  { name: "アカツキ", text: "分かりませんが死なないでくださいね" },
  { text: "福音使徒が四方八方から俺目掛けて一斉に襲いかかってくる。獲物は剣が殆ど。だが福音使徒は神官、戦闘においては素人だ。才能も持たない。360度全方位から飛んでくる｜剣戟《けんげき》を、俺は鉄の棒で受け流し、踊るように回避していく。" },
  { text: "当然だが、こちらから攻撃をしても無駄だ。回避すること、生き延びることだけを考えていれば、負けることはない。相手を殺そうと生き急いだ瞬間こそが、戦闘において最大の隙。それを常に晒し続けているこの福音使徒達は、生き残れない。" },
  { name: "福音使徒", text: "がはっ……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……最後か" },
  { text: "気が付けば、シェル公は相手していた全ての福音使徒を無力化していた。当然、俺を取り囲んでいた福音使徒も同じだ。" },
  { name: "シェル公爵", who: "shellmi", expr: "smug", text: "見事な｜屍《しかばね》の山だ" },
  { name: "アカツキ", text: "あまり見ていて気持ちのいい物ではないですね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "さて、遂にご対面だな" },
  { text: "倒れた福音使徒達を｜跨《また》いで俺達は先に進む。透明な建材で出来たとても広い空間。その中央に位置する玉座のような場所に、彼女は居た。" },
  { chara: { slot: "right", id: "el_goddess", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "久しいな、エル" },
  { name: "神", who: "el_goddess", expr: "normal", text: "久しぶりですね、ヤマト" },
  { text: "椅子から立ち上がる、緑髪の少女。真っ白な服を着ている。それに対して、俺達は真っ赤だ。身に付けているものは全て血に染まっている。これは俺達の罪の証。" },
  { name: "神", who: "el_goddess", expr: "normal", text: "この際ですから一々咎めるような面倒な事はしません、貴方達の目的は分かっています" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それは話が早いな。シンシアの為、世界の為に死んでくれるか?" },
  { name: "神", who: "el_goddess", expr: "normal", text: "世界の為?笑止千万。貴方達の行為は紛れもない世界への反逆です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺達が間違ってるんじゃない、この世界が間違ってるんだ、だから俺達はそれを正す必要がある" },
  { name: "神", who: "el_goddess", expr: "normal", text: "……そうですね、認めましょう。私は確かに、この世界の本当の神とは言えない、偽りの神、その表現が正しいかはともかく、間違いだと一概に否定できないものである事は事実です" },
  { text: "シェル公が一歩踏み出す。それを俺は手を横に突き出して制止する。対話の余地があるならば、それに越したことはない。平和的解決が一番だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "一つ提案がある、シンシアに大人しく権能を返すつもりはないか?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "良いですよ、ただし条件があります、ヤマトが今ここで死んでくれるならば。どうです?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なぜお前は俺の死に｜固執《こしつ》する?そんなに俺が憎いのか?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "前も言ったはずです、『私とヤマト様は殺し合う関係』であると" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "どちらかが死なない限り……この問題は解決できないと?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "そうですね、そうなります" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……どうしても、戦わなければならないのか" },
  { name: "神", who: "el_goddess", expr: "blank", text: "貴方は\"今\"私を殺す必要がなくても、どうしても私は\"今\"貴方を殺す必要がある、分かって頂けますか?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、分かったよ。俺は……お前を殺す、いいな、エル" },
  { name: "神", who: "el_goddess", expr: "normal", text: "無論、大人しく殺されるつもりは更々ありません、私はここで貴方達を殺します" },
  { text: "神の少女は椅子の横に置かれた杖を手に取る。教皇の持っていた身体を支える為の杖というよりは、魔術師が持つ杖というイメージのデザインだ。そして、神の少女は杖を構えると、もう片方の手で杖に手をかざす。" },
  { name: "神", who: "el_goddess", expr: "blank", text: "目覚めなさい、バアル" },
  { bgm: "boss" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "っ!誰でも良い!あの杖を破壊しろ!" },
  { text: "俺のその一声が、戦闘開始の合図だった。真っ先に先頭に躍り出たのはシェル公。氷の剣を構えて神に肉薄し、その杖を叩き切ろうとするが……" },
  { se: "magic" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "氷の剣が砕け散る音が響いた。シェル公の剣を受け止めた\"なにか\"。それは煙のように曖昧な物から、一瞬にして実体を得る。" },
  { chara: { slot: "center", id: "baal", expr: "normal" } },
  { name: "バアル", who: "baal", expr: "normal", text: "ようやく出番か、今は何年だ?" },
  { text: "現れたのは小麦色の肌の背の高い男。白髪の頭に赤い鉢巻のような物を巻き付け、両手に五枚刃の｜鉤爪《かぎづめ》のような武器を付けている。" },
  { text: "その赤い瞳から放たれる視線は鋭く、睨まれただけで動けなくなってしまいそうだ。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "魔剣……ラプラスだけじゃなかったか……" },
  { name: "神", who: "el_goddess", expr: "blank", text: "教えてあげましょう、貴方達の知らなかった最後の権能、第五権能は『魂器作成』……魂の器を作る力、『創造』と合わせて聖剣作成とも言われますね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なるほどな……『創造』で生み出した剣などの武器を『魂器作成』で魂の入れ物にしたのが聖剣ってわけか" },
  { name: "バアル", who: "baal", expr: "normal", text: "……俺を使うって事は、よほどの緊急事態みたいだな" },
  { name: "神", who: "el_goddess", expr: "blank", text: "えぇ、緊急事態です。｜原初《げんしょ》の魔王バアル、貴方の活躍を期待しています" },
  { name: "バアル", who: "baal", expr: "normal", text: "全員殺せば良いんだな?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "えぇ、特にあの男を優先して殺して頂けると" },
  { name: "バアル", who: "baal", expr: "normal", text: "良いだろう、任せろ" },
  { fx: "shake" },
  { text: "魔剣バアルはふっと小さく笑うと、目の前のシェル公に蹴りを放つ。危機を感知したシェル公はそれとほぼ同時に飛び退く。紙一重で躱した。" },
  { name: "シェル公爵", who: "shellmi", text: "やはり劣化コピーでは武器として心許ないな、｜複製《ディプケーション》" },
  { text: "シェル公の手に氷の剣が生まれる。ん?あいつ魔術なんて使えたか?" },
  { name: "クロセル", text: "あれもシェル公の才能だ。構造を完璧に記憶している物であればなんでも複製出来る、彼女は記憶操作で自身の記憶を永続的に保持できる故に、その制限も無いに等しい" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なんでも複製出来るのか……便利だな" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あと心を読むな" },
  { name: "クロセル", text: "緊急事態につべこべ言うでない、それより来るぞ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "分かっ……っ!" },
  { text: "恐ろしく速い。十メートルはあったであろう間合いを一瞬にして詰められた。鉤爪が二方向から飛んでくる。鉄棒で一撃を防ぎ、鉤爪の刃に棒を引っ掛けると、突きの動作で放たれた鉤爪に向けて振り下ろし、受け止める。" },
  { name: "バアル", who: "baal", expr: "normal", text: "ほう、ガキの癖になかなかやるな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "後ろががら空きだ!" },
  { text: "鉄棒で両手の鉤爪を振り払うと、そのまま飛び退く。追撃に前傾姿勢になった魔剣バアル。その背後には剣を振りかぶったシェル公の姿。死角からの一撃。バアルの肩口に見事に入る。が……" },
  { se: "slash" },
  { fx: "flash" },
  { text: "パリン!と氷の剣の方が砕け散った。" },
  { name: "シェル公爵", who: "shellmi", expr: "surprised", text: "なっ……" },
  { text: "バアルは攻撃を受け止めた訳ではない。間違いなく受けたのだ。だが、シェル公の振り下ろした剣は、バアルの肉体に触れた瞬間、砕け散った。それが意味するのは、あの肉体が恐ろしい硬度を持っているという事だろうか。" },
  { name: "バアル", who: "baal", expr: "serious", text: "効かねぇんだよ、そんな攻撃" },
  { text: "考えられるのは才能。覚えている。あれと同じような芸当をやってのける人物を。アシュバル・ゴッドフリー。クロセル救出任務で仲間になり、勇者ニコラスに討たれて別れる事になったあの男だ。彼の持っていた「強靭」の才能。あれと同質の才能を持っていると考えるのが無難だろう。だとすれば、中々に厄介な相手だ。" },
  { chara: { slot: "left", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "クロセル!こいつは強靭の才能を持ってる!そうだな!" },
  { name: "クロセル", text: "あぁ、確かに『強靭7』の才能を持っている" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "チッ……やっぱりそうか" },
  { text: "どうする?俺はもとよりディザビリティだ。こいつが強靭の才能を持っていようと関係ないが、仲間は違う。特にシェル公の剣や瀬野の銃が効かないのは致命的だ。" },
  { name: "バアル", who: "baal", expr: "angry", text: "くっくっく……残念だったなぁ、お前達の攻撃は俺に効かない、諦めて、死ね" },
  { text: "魔剣バアルの、死刑宣告が響き渡った。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 10: el_confession (EP123 前半) ◆B10 =====
  { label: "el_confession" },
  { pov: null },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { chara: [ { slot: "left", id: "yamato", expr: "serious" }, { slot: "center", id: "baal", expr: "normal" } ] },
  { se: "gunshot" },
  { text: "時間停止から繰り出された瀬野の必中の弾丸が、魔剣バアルの胸に命中する。" },
  { text: "瀬野の必中の弾丸も、バアルの足元に潰れて転がるだけ。バアルは攻撃を仕掛けてくる。狙いは当然、俺。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "チッ……どうする?" },
  { fx: "shake" },
  { text: "バアルは飛び上がり、鉤爪を振り下ろす。バアルの体格を考慮すると、あれは恐らく受け止めきれない。瞬時にそう判断すると、横転する。紙一重で躱し、転がった直後に跳び上がるようにして体勢を立て直す。" },
  { text: "が、着地したバアルは直ぐに俺に向き直り、鉤爪の刃が横に薙ぎ払われる。刃の長さは1m近くある。完全に間合いから逃れる事は出来ない。" },
  { fx: "red" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くっ……身体強化しててもこれか……" },
  { text: "背中に熱い感覚が走る。それから数秒後に激痛。背中から血が吹き出し、痛みから苦悶の声を漏らす。クロセルの身体強化魔術の恩恵を受けている筈の俺が遅れを取っている。バアルは強靭の才能だけではなく、戦闘系の才能も9+であると推測できる。" },
  { text: "｜原初《げんしょ》の魔王。最初の魔王の魔魂結晶を、聖教会はそんなに前から保管していたのか。" },
  { text: "要するに、そんなに前から、聖教会という組織は神と癒着していた腐りきった組織だったということだ。魔王システムがもたらす世界への悪影響を理解しながら、知らないふりをしていたのだから。心底｜反吐《へど》が出る。だが、それも今日で終わりだ。" },
  { name: "クロセル", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》\n――属性魔術……｜水弾《ウォーターボール》・｜雨《マシンガン》!" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "そんな低威力の攻撃じゃ意味ねぇぞクロセル!" },
  { name: "クロセル", text: "分かっているが今はこれしか撃てん!肉体が完全に再構築されていないのだ、魔力自体は無尽蔵だが、一度に大量の魔力を使う魔術は使えない!" },
  { fx: "clear-red" },
  { text: "俺は小さくアカツキを一瞥する。両手をバアルに向けているが、何かを撃つ気配はない。それはつまり、機を見計らっているという事。アカツキの攻撃であればバアルに届く可能性があるという事。ここは、あいつに賭けてみるしかないか。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "俺の死ぬ瞬間が見たくねぇ奴と｜断末魔《だんまつま》が聞きたくねぇ奴は目と耳塞いどけ!" },
  { name: "クロセル", text: "ご主人……分かった" },
  { name: "瀬野", who: "zeno", text: "えっ?ヤマトが死ぬのなんて嫌だよ……僕がもごもごっ" },
  { name: "シェル公爵", who: "shellmi", text: "ダーリンが死ぬわけ無いだろう、貴様は黙って見ているといい" },
  { text: "クロセルが目を閉じる。瀬野には伝わらなかったようだが、シェル公が抑えつけてくれた。あいつ意外と察しが良いんだな。当然か。そして、アカツキも目を閉じる。それを確認すると、俺は叫ぶ。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なぁバアル、俺を殺したいんだろ!?良いぜ……殺してみろ!" },
  { name: "バアル", who: "baal", expr: "normal", text: "けっ……諦めたのか?ならせめて良い声で鳴いてくれよ!" },
  { text: "俺の安っぽい挑発に、見事に乗ってくれた。俺はディザビリティを持っている。故に傷害が出来ない。それは当然相手も知っている。俺を殺すことは出来るが、俺に殺される事は万に一つもありえない。だから、確実に乗ってくる。この甘い罠に。" },
  { text: "バアルが地面を蹴ってこちらに突貫してくる、俺は左手で腰に付けた\"それ\"を取り出し、投げつけた。" },
  { name: "バアル", who: "baal", expr: "angry", text: "あ?効かねぇって言ってんだろ!そもそも当たらねぇ!" },
  { se: "explosion" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "バアルは鉤爪で俺の投げたそれを切り裂こうとする。瞬間、それは起爆した。辺りが閃光と轟音に包まれ、視力と聴力を奪われる。これは強靭の才能では防げない。そう、俺が投げたのはスタングレネード。瀬野の作った武器の一つだ。" },
  { text: "本来は勇者と戦う時に使うつもりだったが、結果的には残しておいて正解だった。" },
  { name: "アカツキ", text: "空間魔術……｜亜空切断《ディメンションカッター》!" },
  { fx: "flash" },
  { text: "この一瞬の隙。一瞬だけでも相手を怯ませ、動きを止めれば十分だ。アカツキの魔術が発動する。空間に切れ目を入れ、物を切断する魔術。これにはどんな強靭な物質だろうと抗えない。それが存在する空間そのものが切断されているのだから。" },
  { chara: { slot: "center", id: "baal", expr: "angry" } },
  { text: "俺は閉じていた目を開く。そして、勝利を確信する。バアルは棒立ちで目を見開いていた。そして、ずるり……と滑るような音と共に、その上半身が下半身と別れ、地面に転がる。" },
  { bgm: "mystery" },
  { name: "バアル", who: "baal", expr: "angry", text: "この俺の身体が切断される!?ありえねぇ……てめぇ……何をした!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "俺じゃねぇよ、俺の仲間のアカツキって奴の功績だ、すげぇだろ" },
  { name: "バアル", who: "baal", expr: "normal", text: "くそっ……くそっ……俺は悪くねぇぞ、マスターならもう少し情報をだな……" },
  { name: "神", who: "el_goddess", text: "どんなに相手の情報を与えても、残念ながら貴方では勝てません、そう未来は決定してしまっていた" },
  { text: "神の少女は、真っ二つになり地面に転がったバアルにそう告げる。その言葉は淡々としていて、一切の動揺は見て取れなかった。" },
  { name: "バアル", who: "baal", expr: "angry", text: "は!?なら何で俺を呼び出したんだよ" },
  { name: "神", who: "el_goddess", expr: "normal", text: "負けるのは分かっている、それでも足掻いてみたかったんです、運命って奴に" },
  { name: "バアル", who: "baal", expr: "serious", text: "それで……運命は変えられなかった、それで終わりかよ" },
  { name: "神", who: "el_goddess", expr: "blank", text: "終わりみたいですね……" },
  { name: "バアル", who: "baal", expr: "normal", text: "チッ……そうかよ……やられ損じゃねぇか……" },
  { text: "バアルは悔しげにそう呟くと、その身体は光の粒子になって散り散りになった。そして、聖域には俺達と神の少女だけが残った。" },
  { hide: "center" },
  { chara: { slot: "center", id: "el_goddess", expr: "blank" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前、負けるのは分かっているって言ったな" },
  { name: "神", who: "el_goddess", expr: "blank", text: "えぇ、ラプラスの力で私は未来を知った、\"この座標の私\"はどう足掻いても、生き残れない" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いつからだ" },
  { name: "神", who: "el_goddess", expr: "normal", text: "確定したのは貴方がティアではなくアカツキを選んだ瞬間。あれが分岐点だったと言えるでしょう" },
  { text: "その言葉を聞いて、俺は唇を噛む。あの選択が、正解だったと?そんなの認められる訳がない。もっと良い方法があった筈だ。俺なら二人を救えたはずなんだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……そうかよ、それで……お前はどうするんだ、大人しく殺されるのか?" },
  { name: "神", who: "el_goddess", expr: "blank", text: "抵抗しても無駄……分かっています" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "別にお前を殺す必要はない。権能をシンシアに返すならば、命は助ける" },
  { name: "神", who: "el_goddess", expr: "blank", text: "意味ないんですよ……貴方が生き延びる限り、私は死ぬんです" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "何故だ、説明しろ。俺は約束を守るぞ" },
  { name: "神", who: "el_goddess", expr: "normal", text: "優しいんですね、殺そうと思えばいつでも殺せるのに、わざわざ話を聞くだなんて" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "どんなに憎い相手だとしても、お前はエルだ、大切な仲間だった過去は消えない、だから……俺も出来れば殺したくはないんだ" },
  { name: "神", who: "el_goddess", expr: "normal", text: "……分かりました。説明しましょう、どうせ死ぬんですから" },
  { text: "神の少女は溜息を吐くと、ゆっくりと言葉を紡ぎ始める。その瞳にはただ諦めの色だけが浮かんでいた。" },
  { fx: "shake" },
  { name: "神", who: "el_goddess", expr: "blank", text: "私は未来、今から半年後にこの世界に転生してきました" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……は?ツッコミどころが多すぎるぞ?未来と言っているのに\"してきた\"は過去形だ" },
  { name: "神", who: "el_goddess", expr: "normal", text: "文字通り\"私\"としては過去の話なんですよ、私は地球からこの世界に転生してきた、貴方と同じです。神を殺せという一つの言葉と才能を与えられて" },
  { name: "瀬野", who: "zeno", text: "え?神様は貴方なんじゃ……?" },
  { name: "瀬野", who: "zeno", text: "取り敢えず最後まで聞こう" },
  { text: "瀬野が尤もな発言をする。俺も同じ事を思ったが、今は話を聞くことの方が重要だ。" },
  { name: "神", who: "el_goddess", expr: "normal", text: "最初の私が持っていた才能は\"時空間操作10\"、要するに瀬野さんの才能の上位互換です。異世界転生してチート能力を手に入れた私の旅路に関しては、特筆するまでもないでしょう、そして結論から言えば、私はヤマト様、貴方と同じ思想に至る" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……神を殺して神に成る、か" },
  { name: "神", who: "el_goddess", expr: "normal", text: "その通り、\"神を殺せ\"という啓示から私はこの世界に偽りの神ではない、本当の神が居ることを知った。この時の偽りの神は未来の私なのですが、まぁそんな事は知るはずもなく、私は真の神から力を奪うことを画策した" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だが、それは未来、つまりシンシアに権能はない" },
  { name: "神", who: "el_goddess", expr: "normal", text: "えぇ、シンシアに着いてから、私はそれを知りました、だから私は才能を使った。時空間操作で過去へ行き、シンシアから権能を奪い、神に成った" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なるほど、そして神として生き長らえた結末が、ここか" },
  { name: "神", who: "el_goddess", expr: "normal", text: "そういうことです、理解できましたか?" },
  { text: "敵は、もう一人の俺だった。同じ世界から来て、同じ啓示を受け、同じ結論に辿り着いた――俺の鏡像。" },
  { text: "ぞっとした。憎い。目の前のこいつが、心の底から憎い。だが、それと同じだけ――もし俺がほんの少し違う道を選んでいたら、そこに立っていたのは俺だったのかもしれない。その事実が、何より恐ろしかった。" },
  { wait: 600 },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "理解はした。だがそれで何故、お前が確実に死ぬんだ?シンシアに権能を返してくれれば、俺は未来にやってくるお前を殺したりしないぞ" },
  { name: "神", who: "el_goddess", expr: "blank", text: "これは推測に過ぎませんが、もし神に権能を返した場合、未来の私は果たして転生してきますか?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……そうか、神に権能が戻れば\"偽りの神を殺す為に地球で死んだ人間を転生させる\"という現象は起こらなくなる……つまり、地球で死んだお前が生き返ることはなくなる、その場合、今お前が生きている可能性が消滅する" },
  { name: "神", who: "el_goddess", expr: "blank", text: "そういうことです" },
  { text: "待てよ?おかしいぞ。エルは自分の死が確定していると言った。もし仮に、シンシアに権能を返さず、ここでエルを見逃したら、エルの死という確定した未来を回避できるのでは?……本末転倒だ。今までの苦労、ティアや教皇の死、奪い奪われた多くの命が報われない。もう戻れないのだ。確かに、エルの死はほぼ確定していると言っていいだろう。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "エル……" },
  { name: "神", who: "el_goddess", expr: "blank", text: "選択肢は2つです、私を殺すか、私が権能を返して\"私の存在しない現在\"を反映させるか" },
  { text: "後者による過去の改変はリスクが大きすぎる。偽りの神が居ない世界線では、転生者である俺、アカツキ、瀬野、ハゲの死亡が確定する。\n待て。これは全て\"エルが偽りの神になった場合\"の話だ。" },
  { text: "もし――偽りの神が、エルじゃなかったら?もし、その役割を背負うのが\"俺\"だったら?エルはこの世界に来た転生者の一人として、ヤマトの立ち位置で生き延びる。役割を、入れ替えるんだ。" },
  { wait: 600 },
  { text: "見つけた。たったひとつの冴えたやりかたを。" },
  { text: "あぁ、ダメだ。本当に俺は甘っちょろい人間になったもんだ。エルの生存する可能性を見つけてしまった。それどころか、上手く行けばティアも救える。\n――それとも、此処でこいつに引導を渡し、ティアの仇を取るか。" },
  { comment: "◆B10 分岐: 神の処遇" },
  { choice: [
    { label: "過去へ跳ぶ――全てを救う", jump: "b10_canon" },
    { label: "この場でエルを殺す", jump: "b10_revenge", kind: "if" },
  ]},

  // ----- B10 分岐側: エルを殺す → IF END -----
  { label: "b10_revenge" },
  { text: "……ダメだ。賭けには出来ない。過去の改変がどう転ぶかなんて、誰にも分からない。確実なのは、目の前の\"神\"を終わらせる事だけだ。", tid: "ch07__b10_revenge__01" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "エル。お前を殺す。それで終わりにする", tid: "ch07__b10_revenge__02" },
  { name: "神", who: "el_goddess", expr: "normal", text: "……そうですか。それも、一つの正しい結末です", tid: "ch07__b10_revenge__03" },
  { text: "神の少女は、抵抗しなかった。杖を手放し、両手を広げ、静かに目を閉じる。", tid: "ch07__b10_revenge__04" },
  { bgm: null },
  { name: "神", who: "el_goddess", expr: "blank", text: "ティアの事は……謝りません。謝って許される事ではありませんから。ただ……貴方達との旅は、楽しかった。それだけは、本当です", tid: "ch07__b10_revenge__05" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "……あぁ。知ってるよ", tid: "ch07__b10_revenge__06" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "俺の手が、エルの胸を貫いた。", tid: "ch07__b10_revenge__07" },
  { fx: "red" },
  { text: "温かい血が手を伝う。緑髪の少女は、最後に少しだけ微笑んで、俺の腕の中で崩れ落ちた。", tid: "ch07__b10_revenge__08" },
  { name: "神", who: "el_goddess", expr: "normal", text: "権能は……返して、おきました……これで……この世界は、在るべき姿に……", tid: "ch07__b10_revenge__09" },
  { se: "magic" },
  { text: "少女の身体から七つの白い光が立ち昇り、聖域の天井を突き抜けて、月へと還っていく。", tid: "ch07__b10_revenge__10" },
  { fx: "clear-red" },
  { fade: "white" },
  { hide: "all" },
  { fade: "in" },
  { bgm: "sad" },
  { text: "復讐は、果たされた。", tid: "ch07__b10_revenge__11" },
  { chara: [ { slot: "left", id: "yamato", expr: "sad" }, { slot: "right", id: "crocell", expr: "sad" } ] },
  { name: "クロセル", who: "crocell", text: "ご主人……終わった、のだな", tid: "ch07__b10_revenge__12" },
  { name: "ヤマト", who: "yamato", text: "……あぁ、終わった", tid: "ch07__b10_revenge__13" },
  { text: "｜簒奪《さんだつ》された権能は静かに星へ還り、御告げは止み、世界は緩やかに在るべき姿へ戻っていく。教国は混乱するだろうが、それは人間が人間の手で立て直していくべき事だ。", tid: "ch07__b10_revenge__14" },
  { chara: { slot: "center", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", text: "ヤマトさん。……これで、良かったんですよ。少なくとも、間違いではありません", tid: "ch07__b10_revenge__15" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "間違いじゃない、か。……便利な言葉だな、それ", tid: "ch07__b10_revenge__16" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "えぇ。私も、自分にそう言い聞かせて生きてきましたから", tid: "ch07__b10_revenge__17" },
  { chara: { slot: "center", id: "zeno", expr: "sad" } },
  { name: "瀬野", who: "zeno", text: "ヤマト……僕、教皇さんを殺した時、何も感じなかったんだ。それが一番、怖いんだよ", tid: "ch07__b10_revenge__18" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……瀬野。お前のそれは、俺が背負わせた物だ。忘れろとは言わない。ただ、一人で抱えるな", tid: "ch07__b10_revenge__19" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "……うん。ありがとう", tid: "ch07__b10_revenge__20" },
  { hide: "all" },
  { text: "ニコラスは目を覚ますと、神の死を知って長い間黙り込んだ。そして一言、「僕の正義は、何を守れたんだろうね」とだけ呟いた。誰も、答えられなかった。", tid: "ch07__b10_revenge__21" },
  { fade: "out" },
  { fade: "in" },
  { text: "数日後。俺達はティアの墓を、王都の見える丘に建てた。王女としてではなく、俺達の仲間としての小さな｜墓標《ぼひょう》だ。", tid: "ch07__b10_revenge__22" },
  { chara: { slot: "left", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", text: "ティア。……仇は取った。だがな、分かってるんだ。お前はきっと、こんな事を望んじゃいなかった", tid: "ch07__b10_revenge__23" },
  { text: "ハッピーエンドが好きだと笑っていた少女。その墓前で復讐の完遂を報告する事ほど、皮肉な話もないだろう。", tid: "ch07__b10_revenge__24" },
  { text: "だが――ティアは戻らない。瀬野の手は、人を殺した夜のままだ。", tid: "ch07__b10_revenge__25" },
  { bg: "arcadia_lower_night" },
  { text: "その夜、聖都の屋根の上で、俺は一人月を見上げていた。", tid: "ch07__b10_revenge__26" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", text: "ご主人、これで良かったのか?", tid: "ch07__b10_revenge__27" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……", tid: "ch07__b10_revenge__28" },
  { text: "答えられなかった。あの時、確かに見えた気がしたんだ。エルも、ティアも、全員を救う\"たったひとつの冴えたやりかた\"が。だが俺はそれを選ばなかった。選べなかった。", tid: "ch07__b10_revenge__29" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人は間違ってなどいない。誰も、間違ってなどいなかったのだ。ただ……", tid: "ch07__b10_revenge__30" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ。誰も間違ってないのに、誰も救われきらなかった。それだけの話だ", tid: "ch07__b10_revenge__31" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "……我は、ご主人の側に居るぞ。この先何があっても、ずっとだ", tid: "ch07__b10_revenge__32" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "知ってるよ。お前はそういう奴だ", tid: "ch07__b10_revenge__33" },
  { text: "クロセルが俺の隣に腰を下ろす。肩に触れる小さな温もりだけが、今の俺にとって確かな物だった。", tid: "ch07__b10_revenge__34" },
  { bgm: "heartwarm" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "それに、だ。アカツキも瀬野もシェル公爵も居る。賑やかな日々はこれからも続く、暇している暇など無いのだぞ、ご主人", tid: "ch07__b10_revenge__35" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "暇している暇って何だよ……ったく、お前には敵わねぇな", tid: "ch07__b10_revenge__36" },
  { text: "月だけが白く輝く夜。俺は屋根から降りて、仲間達の待つ家へと歩き出す。", tid: "ch07__b10_revenge__37" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "それでも……生きていくさ。あいつらの分まで、な", tid: "ch07__b10_revenge__38" },
  { text: "\"たったひとつの冴えたやりかた\"を見つけられなかった男は、それでも仲間と生きていくことを選んだ。", tid: "ch07__b10_revenge__39" },
  { fade: "out" },
  { hide: "all" },
  { jump: "ending:if_revenge" },

  // ----- B10 正史側: 過去へ跳ぶ -----
  { label: "b10_canon" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "過去を改変すれば未来は変わる、それは確かなんだな", tid: "ch07__b10_canon__01" },
  { name: "神", who: "el_goddess", expr: "normal", text: "えぇ、私がやった限りでは、過去と現在の整合性が取れなくなった場合、現在に至るまでの過去は都合の良いように改変される", tid: "ch07__b10_canon__02" },
  { name: "ヤマト", who: "yamato", text: "修正力の優先順位は過去、未来、現在って事か", tid: "ch07__b10_canon__03" },
  { name: "神", who: "el_goddess", text: "そうですが、そんな事を聞いて何になるんですか", tid: "ch07__b10_canon__04" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "――俺がお前の死という未来を変えてやる", tid: "ch07__b10_canon__05" },
  { name: "神", who: "el_goddess", expr: "blank", text: "……どうやって", tid: "ch07__b10_canon__06" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "秘密だ。最後の一回を使う、良いな?ハゲ", tid: "ch07__b10_canon__07" },
  { text: "俺は自分の中に居る魔王様に尋ねる。返答は直ぐに返ってきた。", tid: "ch07__b10_canon__08" },
  { text: "「過去に行くんだね、何をするつもりだい」\n「安心しろ、お前がこの世界に来なかった事になる未来じゃない」\n「過去の改変はリスクが大きい、どんな未来になるか分かったもんじゃない」\n「お前は神が憎いんだろ、安心しろ、神は殺す、必ずな、約束する」\n「……分かった、ただし僕はここに残る、過去に向かうのは君一人だ」\n「オーケー、交渉成立だな」", tid: "ch07__b10_canon__09" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "｜解除《アンロック》!", tid: "ch07__b10_canon__10" },
  { se: "chime" },
  { fx: "flash" },
  { text: "\"才能『時空間操作10』を強制解放しました\nエラー……才能データが破損しました\"", tid: "ch07__b10_canon__11" },
  { jump: "crocell_kiss" },

  // ===== Scene 11: crocell_kiss (EP123 後半 告白と時間遡行) =====
  { label: "crocell_kiss" },
  { bgm: "romance" },
  { chara: [ { slot: "left", id: "yamato", expr: "normal" }, { slot: "center", id: "crocell", expr: "angry" } ] },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人!何をするつもりだ!" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "悪い、クロセル。ちょっと行ってくる" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……ご主人、ダメだ……そんなの我は認めないぞ!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "心を読むなよ……折角格好つけたんだから" },
  { name: "アカツキ", text: "クロセルさん!?ヤマトさんは何をするつもりなんです!?" },
  { name: "シェル公爵", text: "ダーリン、必ず戻ってくるのだな?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……あぁ、また会えるさ、必ずな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人……嫌だ、嫌だよ……私はご主人の事を……" },
  { text: "どんなに隠していても、クロセルにはお見通しらしい。いつもみたいに元気な姿が見たかったが、泣かせてしまったか。あぁ、未練たらたらだ。俺も分かる。この力は片道切符。多分、戻っては来れないだろう。それに、戻って来ては俺の目的は果たせない。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "クロセル、今までありがとな、お前が居なければ俺はここまで来れなかった" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人の計画は穴だらけだ!世界の修正力が都合の良いように働く保証はないのだぞ!" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "かもしれないな、それでも俺は、みんなが笑って過ごせるハッピーエンドが見たいんだ" },
  { chara: { slot: "right", id: "el_goddess", expr: "normal" } },
  { name: "神", who: "el_goddess", expr: "normal", text: "ヤマト様……貴方のやろうとしている事はハッピーエンドなの?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、とびきりハッピーだよ、俺の大切な人達を全員救えるんだからな" },
  { name: "神", who: "el_goddess", expr: "smile", text: "そう……なら止めない、やってみて、未来の確定したこの座標を、書き換えてみなさい" },
  { text: "神の少女、エルは小さく笑った。そうだ、姿形は変わっても、エルはエルだ。確かに彼女のした事は許されない。だがそれは俺も同じなんだ。裁かれるべきは彼女じゃない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "時間がない、そろそろ行くよ" },
  { text: "そう言って、俺は仲間達の方を振り返る。その瞬間、身体に優しい衝撃と、唇に柔らかい感覚を覚えた。" },
  { cg: "cg_crocell_kiss" },
  { fx: "flash" },
  { bgm: "romance" },
  { wait: 1200 },
  { chara: { slot: "center", id: "crocell", expr: "blush" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "っ……クロセル?" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "大好きだ、ご主人!どんなにこの世界が改変されても、時が流れても、私だけは貴方を覚えてる!" },
  { text: "俺に抱き着いてきて、キスをしたクロセルを優しく抱き止めると。俺は小さく笑った。これじゃあハゲの奴に嫉妬されちまうな。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺もお前を愛してたよ、クロセル。こんな時まで素直になれなくてごめんな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人は悪くない……素直になれなかったのは私も同じだから" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、そうだな" },
  { text: "クロセルは泣きながら俺の身体を抱き締めてくる。離れたくないという強い意思を感じて、思わず決心が揺らぐ。それでも、行かないと。" },
  { cg: null },
  { name: "シェル公爵", text: "なっなっ……あいつ!ダーリンに何をしてくれて……" },
  { name: "アカツキ", text: "はいはい、良いところなんですから空気読んでください" },
  { text: "飛び出していきそうなシェル公をアカツキが捕まえている。最後まで愉快な仲間達だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "時空間操作" },
  { text: "才能を発動すると、カチカチカチと、時計の針のような音が聞こえてくる。その音が、徐々に加速していく。目指すは遥か過去、真の神であるシンシアの元へ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "それじゃあ行ってくる、また会おう" },
  { name: "アカツキ", text: "行ってらっしゃい、ヤマトさん" },
  { text: "アカツキも、微笑みながら送り出してくれた。それだけで俺には十分だ。周囲の風景が移り変わり始める。世界が巻き戻されている。" },
  { se: "magic" },
  { fade: "white" },
  { hide: "all" },
  // ===== Scene 12: moon_cynthia (EP124 Cynthia) =====
  { label: "moon_cynthia" },
  { bg: "moon_surface" },
  { bgm: "mystery" },
  { fade: "in" },
  { text: "それから、悠久とも思える時間が経った。いや、経っていない。今も時間は巻き戻っている。俺という存在の体感時間だけが、ひたすらに引き伸ばされている。" },
  { text: "辺りは真っ暗だ。俺はどこへ向かっているのだろう。才能指数10の力だ。失敗などありえないが、それでも不安だ。" },
  { text: "クロセルの泣き顔が、瞼の裏にこびり付いて離れない。アカツキの微笑み。瀬野の震える声。シェル公のおどけた態度。ティアの……ティアの笑顔は、もう思い出せなくなりつつある。だからこそ、俺は行くんだ。全員を救う、たったひとつのやり方を掴む為に。" },
  { text: "更に体感時間が経った。何時間、いや何日だ?本当に時間が巻き戻っているのかさえ分からない。才能の破壊が発生していない。という事は時間は経過していないのだろう。どこかの時間座標に取り残されて、ひたすら時を浪費しているというわけではなさそうだ。" },
  { text: "人間は一定期間孤独でいると気が狂うというのを聞いたことがある。まだ大丈夫だ。目的を果たすまで俺は狂うわけには行かない。" },
  { text: "体感時間は何年だ。今の一瞬まで、思考が停止していた。眠るなどという甘えは許されない空間だ。身体の時間が停止しているという事は脳の活動も停止しているはず。なのに何故思考が出来ている?" },
  { text: "自我というのは脳の生み出した錯覚に過ぎないんじゃないのか?本当に魂とかいう概念が存在すると?いや、異世界だから存在して当然か。こうも長い間思考だけをしていると、哲学的な事ばかり考えてしまう。" },
  { text: "そして俺は考えるのを……やめないぞ!?体感時間は既に計測不能、考える時間だけは無駄にあったが宇宙の真理とかそういう事は全然分かってない。頭が悪い人間がどんなに考えても無理な物は無理ってことだ。勉強になったな。" },
  { fx: "flash" },
  { chara: { slot: "center", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "かはっ……!?" },
  { text: "突然襲った苦しさから、思わず咳き込む。どうやら呼吸をするのを忘れていたらしい。待てよ?呼吸が必要ということは、身体の時間が動き出したということ。つまり……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "到着したか……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "はっ……そうか、シンシアってそういう意味かよ" },
  { text: "俺は笑う。目の前に広がっているのは白い大地。そこに人型は、動物は、生物は、存在しない。\n――ここは月面だ。いや、少し違うか。月によく似ているだけだ。ここは地球のある世界ではないのだから、正確には月ではない。" },
  { text: "シンシア(地上の方、ややこしいな)の衛星であり、生命を創り、才能システムを作り出した神。それがこの星だ。神は人ではなかった。当然の事だが、どうもしっくりこなくて笑えてくる。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "Cynthiaは月の別名だ、女神の名として使われる事もある、月であり神である存在、だからCynthiaか……なるほど良く出来た名前だ" },
  { text: "恐らく、これも\"後付け\"なのだろう。Cynthiaは地球の言葉だ。つまり、名付けた人間は地球の人間。文明が生まれた頃から存在していて、地球の人間と言えばエルしか居ない。まぁ、今回はエルは来ない。エルには\"別の役割\"があるのだから。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "シンシア、いや……今はまだ\"ただの神\"か、まぁいい、お前は今日からシンシアだ" },
  { text: "声が聞こえているのかは分からないが、一応伝えておかねばなるまい。今から俺は転生する前の俺に戻る。力を使って奪い、悪の道を突き進む邪道。その｜権化《ごんげ》に。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "今からお前の権能を奪う、拒否権はない、せいぜいそのでかい身体で取り返してみやがれ" },
  { text: "俺は悪い笑みを浮かべてそう告げると、月面に手を付ける。エルに出来たんだ。俺に出来ない道理はない。手を付いている部分の奥、この星の奥底から、力を感じる。膨大な力だ。才能指数10の力を何個並べても足りない。これが神の力、圧倒的だ。" },
  { text: "だが、俺は、それを奪う。その意思を抱く、それだけで良かった。" },
  { fx: "flash" },
  { se: "rumble" },
  { fx: "shake" },
  { text: "ドクンと大きな力の塊が掌から身体へと流れ込んでくる。\n1回、2回、3回、4回、5回、6回、7回。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "かはっ……まずっ……" },
  { text: "権能は七つだけじゃなかったのか。力はまだ流れ込んでこようとする。慌てて手を離すが、七つの権能を宿しただけでも、俺の身体を破壊するには十分すぎた。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "確か権能一つに付き寿命が1割削れるんだったな……" },
  { text: "ぜぇはぁと息を切らしながら、胸を抑える。ここから先は悪逆無道の道だ。俺はこれから、無数の命を喰らって生きていくことになる。多くの命を犠牲に、大切な人達を守る。" },
  { text: "酷く利己的な生き物だ。だが人間とは、そういう生き物なんだ。俺は自分が間違っているとは思っていない。悪を貫くには、そういう考え方でもないとやっていられない。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そういう意味では、エルも甘かったな、多分……俺の方が向いてるぜ、この役割はな" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あはっ……あはははははははは!やりやがりましたねぇ!ヤマト様!" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "っ……てめぇは!?" },
  { text: "俺の後ろから高笑いが聞こえる。慌てて振り返ると、そこには……見覚えのある奴が居た。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "どういう事だ、何故お前がここに居る!" },
  { text: "魔剣の悪魔。ラプラス。それが、ここに居る。ここはあの時間座標から数千年以上前であるはずだ。そして、この笑い。こいつは確実に\"知って\"いる。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "いや～そんな警戒しないでくださいよ、今のボクはまだ貴方に何もしていないはずでしょ?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "説明必要です?しょうがないですねぇ……ボクの正体は、魔剣でも悪魔でもありません、時の調律師ラプラス、それがボクだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "時の調律師?大層な名前だな、お前には悪魔ラプラスの方が似合ってるよ" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "ボクもそう思います!まぁ、残念ながらこっちが本名なんですよねぇ、ぶっちゃけダサいんですけど" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王の名前は全てソロモン72柱の名前を冠している、だがそこにラプラスという名の魔神は居ない、お前が普通の魔剣じゃない事は分かってたが……" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "あれ?気付いてたんですか?まぁその通りですよ、ボクは魂器作成で作り出された器に憑依していた人外、ジャンルとしては神の類ですかね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それで、今度は何をして俺の｜邪魔《じゃま》をするつもりだ?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あはっ?そんな警戒しなくて良いんですよ、今回ばっかりはボクは貴方の味方だ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "味方だと?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "貴方の計画は自分がエルの代わりに\"偽りの神\"になり、エルがヤマト様の立ち位置となる、簡単に言えば役割の入れ替えだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……そうだが" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "もちろん、それを実行するにあたって不整合が起こる、例えば『ヤマト様が偽りの神になった場合、ヤマト様が過去に行くという未来が発生しない』という不整合、これを｜辻褄《つじつま》合わせするのがボクの役目なんですね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どう｜辻褄《つじつま》を合わせるつもりだ" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "簡単ですよ、エルさんと同じ『ヤマト様がこの世界に来た後、偽りの神を無視して真の神であるシンシアから権能を奪う為に過去に向かった』その結果が今、ということになります" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "待て、その場合……今の俺の記憶は" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "安心してください、それを決めるのもボクの役目だ、ボクは愉快な物語が好きなんですよ、この世界を愉快な物語とする為ならば、ちょっとした例外や不整合も見逃すのがボクのやり方です、そして今回ボクは貴方の味方だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "つまり、俺の記憶はこのまま、未来の俺の行動だけが書き換えられるということか" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "それが出来るのがボクなんでね" },
  { text: "自信満々に告げると、ラプラスはウインクする。それを見て俺は溜息を吐くと、小さく頭を抱える。最低最悪な敵だったラプラスに力を借りる。不本意だが、こいつの手助けが無ければ俺は目的を果たせないだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺は地上に戻る、お前はどうするんだ" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "もちろん着いていきますよ、貴方が望んだ結末を迎えられるようにサポートするのが、ボクの役目ですから" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうかよ" },
  { text: "にっこにこのラプラスを無視して俺は才能を発動する。時空間操作は無論、空間操作も可能だ。こうして俺は一瞬にして地上に着く。" },
  { se: "magic" },
  { fx: "flash" },
  { text: "\"致命的なエラーが発生した為……破損箇所のある才能を破壊します『時空間操作0』\"" },
  { text: "いつもの警告文が頭に流れる。しかし、いつもの痛みがない。何故だ?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "神の権能『使徒命令』の副作用ですね、勇者と感覚を共有するんですけど、痛覚まで共有したらショックで死んじゃうので神には完全に痛覚が存在しません" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おい" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あと転移先に人里を選んだのは偉いですね、今のヤマトさんは才能の解放も出来ませんから野垂れ死んでたかもしれません" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんで当然のようにお前が居るんだよ……" },
  { text: "俺は自分一人だけを転移させた筈だ。つまりこいつは自力で俺に着いてきたという事になる。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんでもありかよ……" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "えーヤマト様がそれ言います?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "やっぱ俺おめーのこと嫌いだわ" },
  { text: "ニヤニヤと笑っているラプラスを無視して、俺は歩き出す。ここは神が生命を創り、文明が出来た直後だ。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "まぁボクのサポートもありますから、志半ばでヤマト様が倒れる事は無いように善処します" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前も心が読めるのか?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "いえ?でも未来は見えます" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "俺の未来は明るいのか?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "まぁ、万事うまくいけば目的は果たせますよ、ボクの力があればね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "それ、お前の力を借りなければ俺が失敗すると言ってるようなもんだよな" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "えぇそうですがなにか?え?えっ?自分一人の力でこの先数千年の未来を決定できるとでもお思いで?ぷっ、あはははははははは!" },
  { text: "こうして俺(と不本意ながらラプラス)の偽りの神としての人生が始まった。まずは人里で神の権能を示し、信仰を得る。そして次の身体を見つける。俺の肉体に残された時間は長くない。失敗は許されない、心を鬼にして取り組まねば。" },
  { fade: "out" },
  { hide: "all" },

  // ===== 追補: ep125_millennia (偽りの神の数千年) =====
  { label: "ep125_millennia" },
  { bg: "arcadia_upper", instant: true },
  { bgm: "holy" },
  { fade: "in" },
  { text: "それからの日々を、俺は今もよく思い出せない。文明の｜黎明《れいめい》、最初に俺を神と崇めた人里。権能を示し、信仰を集め、寿命が尽きる前に次の｜依り代《よりしろ》へと魂を移す。その繰り返しだ。" },
  { chara: { slot: "center", id: "yamato_young", expr: "normal" } },
  { name: "ラプラス", text: "ヤマト様、この身体ももう保ちませんよ。次を探しましょう" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "あぁ……分かってる" },
  { text: "幾つもの戦争を眺めた。幾つもの王朝が生まれ、滅びるのを見送った。魔王が現れる度に勇者の物語を陰から支え、教会という器を少しずつ整えていく。全ては、遥か未来に訪れる\"あの日\"の為に。" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "なぁラプラス、俺はあと何回、人の身体を喰い潰せばいい?" },
  { name: "ラプラス", text: "さぁ?数えるのが馬鹿らしくなる回数ですかね。でもボクは知ってますよ、ヤマト様が一度も\"やめる\"とは言わなかった事を" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "……当然だ。やめたら、何の為にここまで来たのか分からなくなる" },
  { text: "顔も、名前も、声も。大切だった人達の輪郭は、年月の波に削られて少しずつ薄れていく。それでも、胸の奥に灯った一つの願いだけは、決して消えなかった。みんなが笑って過ごせる、ハッピーエンドを。" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "……白い髪の、赤い瞳の子が居た。気の強い、可愛い奴だった。名前は……くそっ、思い出せない" },
  { name: "ラプラス", text: "無理に思い出さなくても良いんですよ。忘れても、貴方が彼女の為に動いてる事実は変わらないんですから" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "……お前、たまに良い事言うな" },
  { name: "ラプラス", text: "たまに、は余計です" },
  { text: "そうして、気の遠くなるような時間が流れた。教国は栄え、聖教会は神を戴く絶対の組織となり、福音使徒が神の周囲を固めるようになった。全ての歯車が、噛み合っていく。\"あの日\"へ向けて。" },
  { bg: "moon_surface", instant: true },
  { text: "時折、俺はシンシアを見上げた。あの白い星に、いつか七つの権能を返す。それが約束だ。神を殺すと誓った男が、神に成り代わり、神を演じ、最後には神を辞める。とんだ茶番だが、これが俺の選んだ道だ。" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "……エルは、こんな寂しさをずっと一人で抱えてたのか" },
  { name: "ラプラス", text: "今更ですか?あの人も大概甘い人でしたからねぇ。だからこそ、貴方達の旅を楽しんでた。それだけは本物でしたよ" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "……そうかよ" },
  { text: "敵の気持ちが分かるというのは、皮肉な物だ。役割を入れ替えた今、俺はかつてのエルの孤独を、嫌というほど噛み締めている。それでも、後悔はしていない。この孤独の先に、あいつらの笑顔があるのなら。" },
  { bg: "arcadia_upper", instant: true },
  { text: "そして、長い長い夜が明ける。ラプラスの瞳が、未来の輪郭を捉え始めた。役者が揃いつつある。黒髪の少女、その仲間達。俺を殺しに来る、新たな旅人達が。" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "……やっと、か。長かったな" },
  { text: "数千年越しの、約束の日。俺は静かに、その時を待った。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 13: god_yamato (EP125 偽神墜堕) =====
  { label: "god_yamato" },
  { bg: "arcadia_upper" },
  { bgm: "holy" },
  { fade: "in" },
  { text: "――数千年後。" },
  { chara: [ { slot: "center", id: "yamato_young", expr: "normal" }, { slot: "left", id: "eve_end", expr: "normal" } ] },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "お言葉ですが、本当に良かったのですか?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "何がだ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "神様が選んだその身体ですよ、その身体は才能を持たないどころか……" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "｜無才《ディザビリティ》の持ち主だろ、分かってる" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "他にも優秀な｜依り代《よりしろ》はたくさんありました、何故その身体を……?" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "まぁな、俺にはこれが一番しっくりくるんだよ" },
  { text: "俺は聖域で教皇と言葉を交わしていた。あれから何千年経ったのか。数え切れないほど転生を繰り返した。記憶は曖昧で、もはや自分が誰だったのかも思い出せない。" },
  { text: "それでも確かな事が一つある。俺はハッピーエンドを望んだんだ。顔も名前も思い出せない、大切だったはずの人達を幸せにする為に。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "それと、もう一つ。神様を討とうと迫る彼女達を、本当に迎撃しないのですか?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "あぁ、福音使徒には誰一人あいつらに手を出すなと命令しておけ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "神様無くして、これから教国はどうすれば良いんですか……" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "お前達には悪いと思ってる、ここまで俺が生きてこれたのは聖教会のお陰だ、その恩を仇で返す事になるのは、悪いな" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "滅相も無い!我々が神様にして頂いた事の方がとても尊く重い物です、寧ろ神様に貰った恩を返しきれないのが我々の心残りで……" },
  { text: "教皇イヴ・エンド。神である俺の忠実な部下だ。長く生きる内に、俺は表情や仕草から嘘と本当を見抜ける能力を手に入れた。そして、こいつは本気で言葉の通りの事を思っている。本当に良く出来た人間だ。" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "なぁ教皇、お前は知ってるんだろ?" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "……何をでしょうか?" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "CCだよ、持ってるだろ、俺が本当の神じゃない事は分かってたはずだ、それでも何故お前は……" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "そんなの簡単な話ですよ、ただ居るだけで何もしない真実の神よりも、民の為、教国の為に今まで尽力してきた偽物の神の方が、我々が信仰するに足る物だった、それだけの話です" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "なるほどな、数千年前から抱いてた疑問がやっと分かってすっきりしたよ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "……?数千年前に私は居ない筈ですが……" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "気にするな、それよりここは危険だ、もう行け" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "……分かりました。ご武運を、神様" },
  { text: "教皇は俺に深いお辞儀をする。一分程経過した。教皇はゆっくりと顔を上げ、そのまま聖域を後にした。" },
  { hide: "left" },
  { chara: { slot: "right", id: "laplace", expr: "normal" } },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "ラプラス……俺の選択は、正しかったのか?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "はへ?どれの事です?" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "俺が過去に戻り神になった事だ。俺は思うんだ、あのまま神を殺していた方が幸せだったんじゃないかって" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "さぁ……知りませんけど?あっでもでも?ボクとしてはヤマト様の方法が好みですかね" },
  { text: "いつからか、その少女は俺の脇に立っていた。どうやら彼女の事は、俺以外に見えないらしい。時の調律師ラプラス。" },
  { text: "見た目こそ可憐な少女の姿をしているが、その中身は悪魔と呼ぶに相応しい邪悪な心を持っている。彼女の力なくして、俺はこの結末に辿り着くことは出来なかった。だから、感謝はしている。どうやっても、好きにはなれないが。" },
  { name: "ラプラス", who: "laplace", expr: "blank", text: "さて、時間ですね" },
  { name: "ヤマト", who: "yamato_young", text: "あぁ、そうだな" },
  { text: "ラプラスの瞳が青く光る。黒髪に｜碧眼《へきがん》の少女、誰かとはまるで正反対だ。誰だっただろう、思い出せない。とても大切な事だったはずなのに。" },
  { hide: "right" },
  { fx: "shake" },
  { text: "そして、運命の時は訪れる。正面の通路から聖域に足を踏み入れた人間が4人。" },
  { chara: [ { slot: "farleft", id: "zeno", expr: "serious" }, { slot: "left", id: "akatsuki", expr: "serious" }, { slot: "lcenter", id: "kanade", expr: "serious" }, { slot: "center", id: "yamato_young", expr: "normal" }, { slot: "right", id: "crocell", expr: "serious" } ] },
  { name: "？？？", who: "kanade", expr: "serious", text: "……貴方が、神なの?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "あぁ、そうだ" },
  { text: "中央に立ち、俺に問い掛けてくるのは黒髪の少女。断片的だが、記憶が蘇ってくる。……この子は、確か。" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "その姿で会った事は無かったな" },
  { name: "カナデ", who: "kanade", expr: "normal", text: "……?私は貴方と初対面の筈だけど" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "そうだったな。良く思えば、俺はお前の本当の名前すら知らなかったんだ……聞いても良いか?" },
  { name: "カナデ", who: "kanade", expr: "normal", text: "これから殺す相手に名乗る必要があるかは疑問だけど、まぁいいよ、私はカナデ、｜鳴無《オトナシ》 ｜奏《カナデ》だよ" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "そうか、良い名前を持ってるじゃねぇか……俺はヤマトだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "神に名前は無いのでは無いのですか?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "アカツキか……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "何故私の名前を?それと質問に答えて下さい" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "神に名前が無いのは神を唯一の存在にする為だ、だがお前達は神が一人じゃない事をもう知っている、つまり隠す必要はない" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "なるほど、確かにそうですね" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "……ヤマト、僕を覚えてる?" },
  { text: "黒髪の少年。瀬野 充。確かこいつは、この座標で俺が過去に行った事を知っている。それは｜辻褄《つじつま》合わせの為に修正された過去、なのだろうが。そして、最後に。" },
  { name: "？？？", who: "crocell", expr: "serious", text: "貴様、何を考えている?ここまで福音使徒や勇者の妨害が無いどころか、聖域で一人、丸腰で座っているとは" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "お前は……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "｜魔杖《まじょう》クロセルだ、マスター、我は予定通りこいつを殺して良いんだな?" },
  { name: "カナデ", who: "kanade", expr: "normal", text: "そうだね、やっていいよ、クロセル" },
  { text: "クロセルと呼ばれた少女。美しい白髪に吸い込まれるような赤い瞳。白と黒のゴスロリドレスに透明な氷の剣を携えた、可憐な少女。" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "グレモリーとシェル公は居ないんだな……" },
  { name: "ラプラス", text: "役者が違いますからね、完全に同じ筋書きとは行きませんよ、まぁボクなりに頑張った結果なんで?褒めて下さいね?" },
  { text: "ラプラスが嬉しそうに顔を綻ばせて首を傾げる。なんだか一発ぶん殴ってやりたい気分なのだが、ラプラスは俺以外の誰にも見えていない。殴っても虚しいだけだろう。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……今からお前を殺す、覚悟は良いな?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "あぁ" },
  { text: "クロセルが俺に剣の切っ先を向ける。その視線には明確な殺意が込められていた。だが、自然と不安は無かった。既に心は決まっていた。俺は最初から、こうする為に神になったんだ。" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "……何故だ" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "どうした?" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "何故……抵抗しない!我を舐めているのか!?抵抗しないからと言って情けをかけるとでも!?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "いや、そんなことはない" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "なら何故!" },
  { text: "震えていた。俺ではない。目の前の彼女の肩が、震えていた。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "何故……なんだ……" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "クロセル?" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "私は……貴方の事なんて……何一つ知らない……" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "あぁ" },
  { text: "俺は目を閉じて静かに答える。あの頃とは、身も心も変わってしまった。今の俺は、もはや前の座標の俺とは別人なんだろう。そもそも、今目の前にいる彼女は、俺の知るクロセルではない。" },
  { text: "俺と出会わなかった可能性を辿ったクロセルだ。だから、分かるはずがない。あの時に交わした約束も、何も意味なんて無かった。価値なんて無かったんだ。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "なのに……なんで……どうして貴方は、そんなに優しい目で私を見るんだ!" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "数千年の間、願い続けた望みが叶うんだ。お前の為だ、俺はお前の為にここまで来た、だからお願いだ、クロセル" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "やめろ……嫌だ、聞きたくない!" },
  { text: "クロセルが頭を抱える。そんな彼女を、俺は優しく見下ろしながら、望みを告げた。" },
  { wait: 600 },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "――俺を殺してくれ" },
  { text: "俺は両手を広げて、小さく笑った。そんな俺を真っ直ぐ見据えたクロセルは、震えた手で剣を振り上げる。" },
  { name: "カナデ", who: "kanade", expr: "serious", text: "待って、クロセル" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……なんだ、マスター" },
  { name: "カナデ", who: "kanade", expr: "serious", text: "死にたがってる奴を殺すのは、なんか……癪に障る、私達の目的はシンシアに権能を返す事、そうでしょ?" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "この男を……神を殺さないのか?" },
  { name: "カナデ", who: "kanade", expr: "normal", text: "私個人としては特に恨みとかないし、確かにこいつが今までやってきた事は許されない事だけど、この偽物の神は私達に一切手を出さなかった、殺す理由、無くない?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "確かに、私もこの人は悪い人ではない……気がします、もちろん、最終決定はカナデさんに任せますが" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "僕も……ヤマトには死んでほしくない" },
  { text: "カナデが淡々とそう告げたかと思えば、それぞれが自分の意思を表明する。クロセルは、はっとした顔で剣を降ろすと、小さく安堵するように溜息を吐いた。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ふっ……ふん!命拾いしたな、我のマスターが寛大な事に感謝するが良い" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "……要するに、シンシアに権能を返せば、俺は生かして貰えるのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そういう事になるのではないか?" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "そうか……この流れになるのは予想外だったな……" },
  { text: "よく考えれば分かる事だ。俺に思い付いてカナデが思い付かない筈がない。俺の思い描いたハッピーエンドの中に、俺も居て良いのだろうか。もはや償いきれない罪を背負った俺が、生きていて良いのだろうか。" },
  { text: "両手を下ろし、自分の掌を見つめる。そしてゆっくりと立ち上がると、片手を空に掲げた。" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "ほら、持ってけよ、シンシア" },
  { fx: "flash" },
  { text: "身体の奥底にあるロックを外す。俺の中に封じ込められていた七つの膨大な力が、天に還元されていく。\n1、2、3、4、5、6。これでいい。" },
  { text: "掌から放たれた白い光の塊は、聖域の天井を突き抜け、真っ直ぐと月、シンシアの元へと還って行った。これで、俺は神ではなくなった。" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "満足か" },
  { name: "カナデ", who: "kanade", expr: "smile", text: "私は満足、シンシアの御告げもこれで果たせたしね" },
  { text: "カナデは俺に向かって一つ頷いたかと思えば、目を閉じて小さくよろける。だがそれも一瞬。姿勢を直すと、カナデは目を閉じたまま俺に向けて片手を突き出した。" },
  { bgm: null },
  { name: "カナデ", who: "kanade", expr: "normal", text: "じゃあ……" },
  { text: "そのままカナデが一歩ずつ俺に近付いてくる。やがて、その手が俺の胸に触れた。その瞬間、カナデは目を大きく見開いて笑った。" },
  { wait: 800 },
  { se: "heartbeat" },
  { name: "カナデ", who: "kanade", expr: "serious", text: "――死 ん で く れ る か い?" },
  { se: "explosion" },
  { fx: "flash" },
  { fx: "shake" },
  { fx: "red" },
  { text: "｜刹那《せつな》、俺の視界は真っ白に染まる。遠い爆発音、それが自分から発生している物だと気付くのに、数秒の時間を要した。何が起きたのか理解が追い付かないまま、俺は地面に膝をつく。" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "ごほっ……" },
  { text: "カナデが触れていた胸元を抑えながら、俺は喉元にせり上がってきた血を吐き出す。痛覚が無い為、何かをされたのは分かっていても何をされたかが分からない。" },
  { text: "損傷を確認。胸部の空間が大きく｜抉《えぐ》り取られた。辛うじて心肺は無事だが、致命傷な事に変わりはない。状況が理解できない、目の前にいるこいつは誰だ?カナデじゃないのか?" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "マスター!?何を!?" },
  { name: "カナデ", who: "kanade", expr: "normal", text: "微妙に急所を外した?いや、外部からの干渉か、となるとあいつもここに居るようだね" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "カナデさん……?じゃないですね、誰ですか?貴方は" },
  { name: "？？？", who: "kanade", expr: "serious", text: "流石は直感の才能だ、一瞬で彼女ではなく僕だと気付くとは" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "何者だ、マスターの身体を乗っ取るなど!" },
  { name: "？？？", who: "kanade", expr: "normal", text: "名乗るほどの者では無いよ、ルツ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……どうしてその名前を" },
  { name: "？？？", who: "kanade", expr: "normal", text: "おっと間違えた、君はクロセルだったね" },
  { text: "\"何者か\"がカナデの身体を乗っ取り、動かしている。そして、あの男がルツという言葉を出した瞬間、クロセルの表情が凍り付いた。クロセルの……本名なのか?俺でも知らない事を知っている存在、そんなの……" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "魔王……様?" },
  { bgm: "dark" },
  { name: "ハーゲンティ", who: "kanade", expr: "sad", text: "……最後まで君にはバレたくなかったんだけどね。そうだよ、僕だ。魔王ハーゲンティ……の意志の才能だ" },
  { name: "ヤマト", who: "yamato_young", expr: "surprised", text: "思い出したぞ……ハゲ、てめぇ……" },
  { name: "ハーゲンティ", who: "kanade", expr: "serious", text: "ヤマト君、君はどうやら勘違いしているようだね。僕の目的は\"神を殺す事\"だ、シンシアに権能を返す事じゃない" },
  { text: "カナデの身体を乗っ取ったハゲの奴は、俺達に向けてそう笑顔で言い放つ。この男は味方だと思っていた。良い奴だと思っていた。だが違ったらしい。この男は、神を殺すという目的、自分の意志の為ならば手段を問わない。俺と同じ外道だ。" },
  { text: "血が止まらない。命が尽きるまでのカウントダウンが始まっている。結局、俺はここで終わりなのか?だがそれでも良いだろう。当初の予定では、俺は死ぬはずだったんだ。俺が居なくても、ハッピーエンドは成立するんだ。" },
  { text: "意識が遠のいていく。痛みはない。苦しくもない。ただ、寂しさだけが残った。俺はこの座標で、孤独なんだ。" },
  { wait: 800 },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……だ" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "クロ……セル?" },
  { fx: "flash" },
  { bgm: "resolve" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "嫌だ、私は!もう二度と!ご主人を失いたくない!" },
  { text: "クロセルが剣を取り、ハゲの元へ走る。ご主人?マスターではなく?それは確か……" },
  { name: "ヤマト", who: "yamato_young", expr: "surprised", text: "どういうことだラプラス……前の座標の記憶は……" },
  { name: "ラプラス", text: "あはっ?言ったでしょうヤマト様、ボクは愉快な物語が好きなんだ、その為ならば不整合や例外をあえて残すこともある" },
  { name: "ヤマト", who: "yamato_young", expr: "surprised", text: "あのクロセルは……俺の事を?" },
  { name: "ラプラス", text: "まぁ、思い出せるかどうかは賭けでしたよ?ボクがやったのはあくまでも彼女の記憶を世界記憶から削除しなかっただけ。彼女のやってることは前世の記憶を呼び覚ますようなもんですから、一種の奇跡です。愛の力って凄いですね!" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "……今回ばっかりはお前に感謝するよ" },
  { text: "ラプラスが俺に向けてウインクする。溜息の代わりに血｜反吐《へど》を吐きながら、俺は事の一部始終を朧げな意識で見届けていた。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 14: final_duel (EP126 大切だったはずのもの) =====
  { label: "final_duel" },
  { bg: "arcadia_upper" },
  { bgm: "boss" },
  { fade: "in" },
  { comment: "視点: クロセル" },
  { pov: "crocell" },
  { chara: [ { slot: "left", id: "crocell", expr: "serious" }, { slot: "right", id: "kanade", expr: "normal" } ] },
  { name: "ハーゲンティ", who: "kanade", expr: "serious", text: "ルツ、いやクロセル、君は僕に剣を向けるのか?" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "私にとっては貴方は主であり、その身体はマスターだ、でも私のご主人はただ一人だけ、ヤマトだけなんだ……" },
  { name: "ハーゲンティ", who: "kanade", expr: "serious", text: "どういう事だ?君は神と何の関係も無い筈だ" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "私もよく分からない、でもこの気持ちは間違いじゃないって分かる、この思いだけは絶対に失っちゃダメなんだ" },
  { name: "ハーゲンティ", who: "kanade", expr: "serious", text: "そうか……" },
  { text: "分からない。分からないんだ。私はあの男の事を知らない。何も知らないのに。頭じゃなくて、心臓が叫んでるんだ。彼が私の一番大切な人だって。" },
  { name: "ハーゲンティ", who: "kanade", expr: "serious", text: "トドメだ、ヤマト君" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "させない……!" },
  { fx: "shake" },
  { text: "ハーゲンティが地面に膝をついたヤマトに片手を向ける。あの力は時空間操作による空間断裂。発動までの時間は3秒。発動範囲は手を向けた方向に50m。" },
  { text: "マスターの力なのだから熟知していて当然だ。つまり、手を切り落とせば力は使えない。私の魔術で後から治せるのだ、｜躊躇う《ためらう》必要はない。" },
  { text: "高速の踏み込みからハーゲンティの腕目掛けて氷の剣を斬り上げる。" },
  { name: "ハーゲンティ", who: "kanade", expr: "smile", text: "おっと……" },
  { text: "｜刹那《せつな》、ハーゲンティの姿が掻き消える。恐らくは空間転移。位置は……分かる。マスターとの契約による魔力の糸が場所を示してくれる。私は素早く身を翻すと、転移先に立っていたハーゲンティに向かっていく。" },
  { name: "ハーゲンティ", who: "kanade", expr: "normal", text: "｜埒が明かない《らちがあかない》ね、だがクロセル、君は一つ大事な事を忘れている" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "何のことだ!" },
  { name: "ハーゲンティ", who: "kanade", expr: "smile", text: "君の魔力は、僕が供給している物だという事だ" },
  { fx: "flash" },
  { text: "ハーゲンティはそう呟き、ニヤリと笑う。その瞬間、ぷつっ……と何かが切れるような感覚が全身に走った。すると、突然身体に鉛が付いたかのように動作が重くなる。これは……まさか……" },
  { name: "ハーゲンティ", who: "kanade", expr: "smile", text: "魔力の供給を断った。君は燃費の悪い魔剣だからね、僕が与えていた無尽の魔力無しではその力を発揮できないだろう" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "くっ……" },
  { text: "私は咄嗟に強化魔術のランクを落とす。体内の残存魔力は30%ほど、この調子で戦闘すれば3分と持たないだろうか。" },
  { chara: { slot: "center", id: "yamato_young", expr: "normal" } },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "好き勝手してくれてるな……ハゲ" },
  { name: "ハーゲンティ", who: "kanade", expr: "serious", text: "おや、まだ喋れる体力があるのかい?" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "ゼノの力で傷口の空間を塞いだ、荒療治だけどな" },
  { text: "神だった少年、ヤマトがふらふらとしながら立ち上がる。その胸元に空いた穴は聖域の建材であろう透明な物質で塞がれている。辺りは深い血溜まり、失血量からして意識を保っているだけでも奇跡だ。そして、ヤマトは何故か笑った。そして、手を宙に掲げる。" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "お返しだ。てめぇにプレゼントをやるよ" },
  { name: "ハーゲンティ", who: "kanade", expr: "normal", text: "君に何が出来る、その身体では才能を使ったとしても戦闘など出来るわけがない" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "――第七権能発動『能力封印』" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "ジジッとノイズが走るような音が辺りに響き渡った。" },
  { name: "ハーゲンティ", who: "kanade", expr: "serious", text: "権能!?全てシンシアに返したんじゃ……" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "悪いな、保険で一個だけ残しといたんだ、後で返すから許してくれ" },
  { name: "ハーゲンティ", who: "kanade", expr: "normal", text: "この身体の才能を封印したか、でも無駄だよ、僕は才能の封印を解除する事が……でき……っ!?" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "俺が封印したのはカナデの才能だけじゃねぇよ、てめぇという意志の才能もだ!" },
  { text: "その言葉を聞いて、ハーゲンティの顔色が変わる。まさかヤマトが権能を隠し持っていたとは。私にとっても想定外だった。" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "そうか……やってくれたね……ヤマト君" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "クロセル、分析しろ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ハーゲンティの才能としての不死性は消滅した、今のハーゲンティは才能の残り香のような物だ" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "つまり、ここであいつの意識を奪ってカナデの人格を取り戻せば、あいつを倒せるんだな?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "あぁ、そうだ……" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "ならやる事は一つだ、カナデを取り戻すぞ、クロセル" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "だが、我はもう魔力が……" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "それなら安心しろ、良い方法がある" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人、その身体で戦えるのか?" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "生憎様だが俺はディザビリティだ、傷害のな" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ディザビリティだと!?本気で私達と戦う気が無かったのだな……" },
  { text: "ヤマトはふらふらとこちらへ歩いてくる。そして、倒れ込むように私の胸の中に飛び込んでくる。その身体を抱き留めながら、私はヤマトと目を合わせる。" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "血だ、俺の血を使え" },
  { name: "クロセル", who: "crocell", expr: "surprised" , text: "そうか、我は……｜魔杖《まじょう》クロセルは本来、血液を対価に力を発揮する魔剣" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "そうだよ、あいつを気絶させるぐらいの魔力にはなるだろ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "だが、ご主人……それ以上の失血は命に関わるぞ?" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "気にするな、俺はしぶといからな、そう簡単には死なねぇよ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……分かった" },
  { fx: "flash" },
  { chara: { slot: "left", id: "crocell", expr: "blush" } },
  { text: "私はヤマトを抱き締めたまま、その首筋に歯を立てる。ぷつっ、と小さな音と共に、私の口の中にヤマトの血が流れ込んでくる。\n甘い。とても美味しい。" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "はっ……あむっ……んぁ……ぁあ……" },
  { text: "理性が溶けていく。血液摂取の副作用だ。人間で言うと、アルコールを摂取するのに近いだろうか。一滴残らず飲み干してしまいたくなる気持ちを辛うじて抑え、私はヤマトの首筋から口を離す。" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "はぁ……あぁっ……" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "一々色っぽい声出すんじゃねぇ……緊急事態なんだぞ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うん……分かってる、大好きだよ、ご主人様" },
  { name: "ヤマト", who: "yamato_young", expr: "jito", text: "だから緊急事態だって言ってるだろ……ハゲの奴に逃げられたら……" },
  { text: "ヤマトの身体を目いっぱい抱き締める。あぁ、安心する。姿は変わってしまったけど、この人は私の大好きなご主人様だ。ずっと触れていたい。でも今は……やることがあるんだ。" },
  { name: "ヤマト", who: "yamato_young", expr: "serious", text: "クロセル、命令だ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うん、私、何でもする!" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "ハゲの奴をぶちのめしてやれ、意識を奪えば俺達の勝ちだ" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "分かったぁ!任せてっ!" },
  { fx: "shake" },
  { text: "全身に魔力が満ち渡る。これなら、いける。私は氷の剣を持ち直すと、一気にハーゲンティの元へと走る。ハーゲンティは、私達に背を向けて逃げ出している。今は武器も才能も無いのだ、賢明な判断だろう。" },
  { text: "だが、逃がさない。絶対に逃がさない。ヤマトの、私の大好きなご主人様の命令は絶対だ。身体強化、フルスロットル。文字通り飛ぶように地面を駆け、距離を詰める。" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "はぁっ!" },
  { se: "slash" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "うっ……" },
  { text: "背後から剣を叩き付ける。刃の部分は当てていない。刀で言う｜峰打ち《みねうち》に近い物だ。" },
  { chara: [ { slot: "left", id: "crocell", expr: "sad" }, { slot: "right", id: "kanade", expr: "sad" } ] },
  { text: "ハーゲンティはバランスを崩し、地面に倒れ込む。諦めたように溜息を一つ吐くとそのまま力を抜く。そして、地面を横に転がり｜仰向け《あおむけ》になると、そのまま両手を大の字に広げて呟いた。" },
  { bgm: "sad" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……魔王様" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "ルツ……君は……僕を殺すのか?" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "君は……僕の唯一の理解者だと思っていた" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "私も、貴方は唯一の主だと思っていました" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "「でも違った」――私と魔王様の声が、重なった" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "あはは……やっぱり僕は、君のナイトにはなれなかったみたいだ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "どうして、魔王様はどうして神を殺すことに｜固執《こしつ》していたんですか" },
  { name: "カナデ", who: "kanade", expr: "serious", text: "……復讐だよ、魔王システムを作った神への復讐だ。僕は望まずして魔王になった数々の人間と、魔王に殺された無数の命の代弁者だ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "殺さないと……ダメなんですか" },
  { name: "カナデ", who: "kanade", expr: "serious", text: "あぁ、殺さないとダメなんだ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そう……ですか……" },
  { text: "本音を言えば、私も魔王様を殺したくはない。でも、魔王様かご主人様、どちらかを選ぶとしたら、私は後者を選ぶだろう。それほどまでに私にとって彼の存在は大きくなってしまったんだ。" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "今度こそお別れだ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そうですね……" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "君がヤマト君を想っているのと同じくらい、僕も君を想っていたんだけどね……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "知っています、でも……ごめんなさい" },
  { name: "カナデ", who: "kanade", expr: "sad", text: "良いんだ、君に消されるのなら、僕は構わない" },
  { text: "ハーゲンティはそう言って、目を閉じる。そして、私は剣を振り上げ、一思いに振り下ろした。" },
  { se: "slash" },
  { fx: "flash" },
  { fx: "shake" },
  { wait: 800 },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ごめんなさい、魔王様" },
  { text: "これで魔王ハーゲンティは完全に消滅した。私が、彼を殺したのだ。湧き上がる罪悪感と後悔で、胸が苦しい。それでも私は、ヤマトを選んだんだ。" },
  { fx: "clear-red" },
  { hide: "all" },
  { fade: "in" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そうだ……ご主人!" },
  { text: "私は、はっとして来た道を全速力で駆け戻る。ヤマトの傷は致命傷だ。直ぐに手当てをしなくては。ゼノとアカツキが立っていた場所の足元に、壁に背を預けて目を閉じたヤマトの姿が目に入る。" },
  { chara: [ { slot: "left", id: "crocell", expr: "sad" }, { slot: "center", id: "zeno", expr: "serious" }, { slot: "right", id: "akatsuki", expr: "serious" } ] },
  { name: "瀬野", who: "zeno", expr: "serious", text: "あ、クロセルさん" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人は無事か!?" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "あぁ、ヤマトなら……" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "応急処置と言えるのかすら分からないけど、傷は塞いでるよ、ただ失血が酷い、このままだと心停止する……かも" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "くっ……我が血を吸ったからっ……どうすればいい!?" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "輸血出来れば良いんだけど……僕とヤマトは血液型が違うから……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさん、何型ですか?" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "Bだよ、僕はA" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "なら問題無いです、私はO型なので" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ユケツ……?血を分け与えるのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね、瀬野さん、空間操作で輸血出来そうですか?" },
  { name: "瀬野", who: "zeno", expr: "serious", text: "やってみる。手から手への物質転送は飽きるほど練習したからね、出来る……はず" },
  { text: "アカツキが地面に膝をつき、手を差し出す。ゼノはその手首を片手で握ると、意識を失っているヤマトの片腕を握る。ゼノはそう呟くと、静かに目を閉じ、集中する。それから何秒経っただろうか。私には悠久の時に感じられた。" },
  { text: "そして、暫くするとゼノは目を開き、二人の腕を離す。" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "はぁ……多分、成功した。アカツキさん、大丈夫?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "結構持っていきましたね……まぁ、私は平気です" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "良かった。じゃあクロセルさん、傷の治療をお願い、傷を塞いだら体内の異物は除去するから" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、任せておけ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "私はカナデさんを見てきます、気絶したまま放置という訳にはいきませんし" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "僕も行くよ、ヤマトのことはよろしくね、クロセルさん" },
  { text: "そう言って、アカツキとゼノは歩いていく。残されたのは、眠ったままのヤマトと私。" },
  { bgm: "romance" },
  { hide: "all" },
  { chara: { slot: "center", id: "crocell", expr: "normal" } },
  { text: "私は心の中でほっと一息つく。ヤマトが死なずに済んだ。それだけで私にとっては十分だった。回復魔術で胸の傷を塞ぐと、私は力を失うように地面に尻餅をつく。あぁ、眠い。" },
  { text: "ぐちゃぐちゃになった頭と、消耗しきった身体。私に本来睡眠は必要無いのだが、今だけは何も考えずにただ眠りたかった。" },
  { text: "ヤマトの横に座り、背を預けると、首を傾げてヤマトの肩に乗せる。そして、その手を握って、私はゆっくりと目を閉じた。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "どうか、この一日が｜泡沫《うたかた》の夢ではありませんように。もう二度と、何よりも大切な彼の事を忘れませんように" },
  { text: "そんな願いを抱いて、私は静かに意識を手放した。" },
  { fade: "out" },
  { hide: "all" },

  // ===== 追補: ep126_dawn (新しい座標の夜明け) =====
  { label: "ep126_dawn" },
  { bg: "arcadia_upper", instant: true },
  { bgm: "heartwarm" },
  { fade: "in" },
  { comment: "視点: アカツキ" },
  { pov: "akatsuki" },
  { text: "気絶したカナデ――いや、もうハーゲンティの意志は消えている。ただのカナデを、私と瀬野さんで運び出した。聖域の白い床に、朝の光が差し込み始めていた。" },
  { chara: [ { slot: "left", id: "akatsuki", expr: "normal" }, { slot: "right", id: "zeno", expr: "smile" } ] },
  { name: "瀬野", who: "zeno", expr: "smile", text: "……終わった、のかな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "えぇ。神は権能を返し、魔王の意志も消えた。長い旅でしたね" },
  { name: "瀬野", who: "zeno", expr: "sad", text: "なんだか、実感が湧かないよ。ずっと走り続けてたから" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……分かります。でも、これでいいんです。クロセルさんがあの人を覚えていた。それだけで、この座標は救われたんだと思います" },
  { text: "あの神だった少年――ヤマト、と名乗った彼。私達の知らない過去を背負った、もう一人の旅人。クロセルさんが彼を選び、命を救った。その光景を見て、私は不思議と腑に落ちた。あぁ、これが正しい結末なんだと。" },
  { name: "瀬野", who: "zeno", expr: "smile", text: "クロセルさん、すごい顔で眠ってたね。ヤマトの肩に頭乗せて" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ふふ。よほど安心したんでしょう。……さ、私達も少し休みましょう。きっと、明日からまた賑やかになりますから" },
  { text: "白い聖域に、朝が満ちていく。長い夜は終わり、新しい一日が始まる。誰も知らない、誰も覚えていない物語の続きが――静かに、幕を開けようとしていた。" },
  { fade: "out" },
  { hide: "all" },

  // ===== Scene 15: new_coordinates (EP127 最弱無才のディザビリティ) =====
  { label: "new_coordinates" },
  { pov: null },
  { bg: "bathhouse_base" },
  { bgm: "daily" },
  { fade: "in" },
  { chara: [ { slot: "left", id: "yamato_young", expr: "normal" }, { slot: "right", id: "crocell", expr: "normal" } ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "ん……ぁ?もう朝か?" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "いや、もう昼だぞ、ご主人" },
  { text: "俺は暖かいベッドの上で目を覚ます。大好きな人の声で目を覚ます、最高の目覚めだ。" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "んっ……あっ……ぁむ……" },
  { text: "俺は身体を起こすと、流れるような動作でクロセルの唇を奪う。そして、そのまま息が苦しくなるまでキスを続けた。" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "ぷぁはぁ……もう、真昼間に何をするのだ" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "俺は数千年分の欲求が溜まってんだよ、我慢しろ" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "その幼い身体で性欲とかあるのか?" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "……ねぇよ、まだな" },
  { text: "言われて俺は自分の身体を見る。転生した身体は10歳の少年の身体だ。愛とか恋とか知るには早すぎる。" },
  { chara: { slot: "center", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "こんな時間に何してるんですか……" },
  { name: "ヤマト", who: "yamato_young", expr: "surprised", text: "え、アカツキ、いつから" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "最初からです、ご飯出来てますよ、皆さん待ってるんですから" },
  { name: "ヤマト", who: "yamato_young", expr: "surprised", text: "わざわざ俺が起きるのを待ってたのか" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "皆さん優しいですからね" },
  { text: "懐かしい間取りだ、聖都にある公衆浴場に｜併設《へいせつ》された屋敷。どうやらこの座標でも、この屋敷は手に入れる事になったらしい。俺はベッドから降りると、服を着替え、食堂に向かう。" },
  { hide: "all" },
  { chara: [ { slot: "left", id: "yamato_young", expr: "normal" }, { slot: "center", id: "kanade", expr: "smile" } ] },
  { name: "カナデ", who: "kanade", expr: "smile", text: "やっと起きてきたんだ、おはよう" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "おはよう、カナデ" },
  { name: "カナデ", who: "kanade", expr: "smile", text: "昨晩はお楽しみでしたか?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "いや別に……" },
  { name: "カナデ", who: "kanade", expr: "normal", text: "なんだ、折角私がクロセルをあげたんだからもっとイチャつけば良いのに" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "それに関しては感謝してる、お前意外と優しいんだな" },
  { name: "カナデ", who: "kanade", expr: "smile", text: "まぁ、定期的に血を吸われるの、痛いし嫌だったからなんだけど" },
  { text: "そう、魔王ハーゲンティの意志が消えた事で、クロセルには定期的にリソースの供給が必要になった。必要とするリソースは魔剣によって違う、生命力、魔力、寿命、そして血液。つまるところ、今のクロセルは、定期的に主人から血液を摂取しなければ活動できないのだ。" },
  { text: "カナデ曰く、それが嫌で俺にクロセルとの契約を渡したらしい。また、クロセルもそうする事を強く望んだからというのもある。" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "美味いな、流石はカナデだ" },
  { name: "カナデ", who: "kanade", expr: "normal", text: "なんでクロセルは貴方みたいな男を主人に選んだんだろ……私には理解できない" },
  { name: "ヤマト", who: "yamato_young", expr: "angry", text: "おい、喧嘩売ってるのか" },
  { name: "カナデ", who: "kanade", expr: "smile", text: "冗談、私も貴方の事は嫌いじゃないよ" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "お世辞どうも" },
  { text: "カナデが作った遅めの朝食を摂る。意外な事に、あいつは元々家事が得意らしい。今のカナデは、神としてのエルよりも俺の知っているエルに近い。つまりはそういうことだったのだろう。" },
  { chara: { slot: "right", id: "nicholas", expr: "normal" } },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "僕とティアが居ない間に何があったんだい?神がこの屋敷に居るなんて……" },
  { name: "ヤマト", who: "yamato_young", expr: "angry", text: "うるせぇ黙ってろ勇者、祝福剥ぐぞ" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "いや……君が権能を返したから祝福の才能も消えたんだけど……" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "あと俺を神と呼ぶな、もうただの人間だ" },
  { text: "大英雄ニコラス。その活躍は、この座標でも歴史に残る物となった。最終決戦、要するに俺を殺す為の戦いでは、ややこしくなるので待機命令を出しておいた。それはもう一人の勇者も同じ。" },
  { hide: "right" },
  { chara: { slot: "right", id: "tia", expr: "laugh" } },
  { name: "ティア", who: "tia", expr: "laugh", text: "ねぇヤマト、ご飯食べ終わったら町に行かない?" },
  { name: "ヤマト", who: "yamato_young", expr: "surprised", text: "いや、聖教会の人間に見つかるとまずいし……あとなんで殆ど他人の俺に懐いてるんだお前は" },
  { name: "ティア", who: "tia", expr: "laugh", text: "年が近い友達が欲しかったの!" },
  { name: "ヤマト", who: "yamato_young", expr: "angry", text: "俺は子供じゃねぇ!" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "外出出来ないのは不便だね……" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "ちょっと遠出すれば大丈夫だ、俺の最後に転生したこの身体を知ってるのは教皇と聖域に入れる一部の｜福音使徒《ふくいんしと》だけだからな" },
  { text: "ティアも無事だ。前の座標では救えなかった命。俺の間違った選択で失った命。彼女が笑ってる今がある。それだけで、この物語はハッピーエンドだ。" },
  { text: "俺のした事は間違いじゃなかった。そう思える。例え皆から忘れ去られようとも。こうしてまた一からやり直せば良いんだ。" },
  { hide: "right" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あはっ?" },
  { text: "気が付くと、背後にあいつが立っていた。｜神出鬼没《しんしゅつきぼつ》にも程がある。普段は姿を隠していて、俺の事を観察しているんだろう。悪趣味な奴だ。" },
  { name: "ヤマト", who: "yamato_young", expr: "jito", text: "お前やっぱ心読めるだろ" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "いえいえ～気のせいですよ" },
  { text: "ニヤニヤと笑う悪魔に向けて、拳を振り下ろす……ほど身長は無いので顔面グーパンだ。ディザビリティで弾かれた。この感覚も懐かしい。" },
  { name: "アカツキ", text: "ヤマトさん、時々｜虚空《こくう》に向かって話し掛けてますけど……幽霊でも見えるんですか?" },
  { name: "ヤマト", who: "yamato_young", expr: "surprised", text: "お前なんで見えないの?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "ボクの一番はヤマト様なんで?" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "意味分かんねぇよ、てかエルクじゃねぇのか" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "あーあいつね……あいつボクのタイプじゃないんで" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "そうかよ……" },
  { text: "皇帝はこの座標でもクロセルを盗み、魔王になり、封印された。相変わらず可哀想な奴だ。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "ボクは是非とも殴って欲しいんですけど、ヤマト様ディザビリティですからね、なんでそんなゴミみたいな身体選んだんですか?馬鹿なんですか?『俺にはこっちの方がしっくりくる』とか格好付けてるだけじゃないですかだっさｗｗ" },
  { name: "ヤマト", who: "yamato_young", expr: "angry", text: "お前俺の事嫌いだろ" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "大好きですよ?" },
  { name: "ヤマト", who: "yamato_young", expr: "sad", text: "はぁ……" },
  { text: "このマゾ悪魔の相手をしていると疲れる。が……何千年も一緒に居たらぶっちゃけ慣れてしまったというのも本音だ。それでも俺はクロセル一筋だが。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "それにしても、神が消えて教国は大騒ぎですけど、私達バレたら捕まるんですかね" },
  { name: "ヤマト", who: "yamato_young", expr: "normal", text: "もしそうなりそうなら俺を差し出せ、俺がお前達を脅迫してたって事にすれば罪には問われないだろ" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "そうですね、その時は遠慮なく" },
  { hide: "right" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "カナデ", who: "kanade", expr: "normal", text: "そう言えばヤマトが今とは別の可能性の未来から来たって話、本当なの?" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "本当だぞ、我はしっかりと記憶しているからな" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "俺が死にかけるまで忘れてた癖に" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "うぐっ……" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "俺は覚えてるぞ、どんなに世界が変わっても時が流れても私だけは永遠にあなたを……" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "うわー!やめろー!恥ずかしい台詞を復唱するな!" },
  { text: "クロセルが身を乗り出してあわあわと慌てふためく。可愛い。" },
  { name: "アカツキ", text: "まぁ、クロセルさんがここまで言うんですから、本当なんでしょう" },
  { name: "カナデ", who: "kanade", expr: "smile", text: "前の可能性の世界の話、私達に聞かせてくれる?" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "あぁ、それぐらいなら良いぞ、お返しにお前達の旅の話も聞きたい、どこが同じで、どこが違うのか気になるからな" },
  { text: "瀬野は俺の事を知っている数少ない人間だ。と言っても、瀬野の知っている俺は、俺のようで俺ではない。ラプラスが生み出した都合の良い過去だ。" },
  { text: "この世界は並行世界ではない、一つの世界、一つの線が、時の｜調律師《ちょうりつし》ラプラスによって上手くいくように管理されている。だから、俺のやった事も、所詮はあいつの掌の上だったという事だ。" },
  { bgm: "ending" },
  { text: "思えば短くも長い旅路だった。多くの困難と挫折を繰り返し、ここまで来たんだ。そして、この物語の主人公はもう俺ではない。ここまでが、俺の物語だ。この先は別の物語、カナデの｜紡《つむ》ぐ物語。故に、この話はここで一度終わりを迎える事になる。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "ヤマト様" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "なんだ" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "前にボクに言いましたよね、貴方の選んだ選択は間違いだったのかって" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "あぁ、言ったな" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "今なら答えは出てるんじゃないですか?" },
  { name: "ヤマト", who: "yamato_young", expr: "smile", text: "もちろんだ" },
  { text: "俺、クロセル、アカツキ、ニコラス、ティア、カナデ、瀬野。俺達七人は、一からやり直して新しい関係を築いていく。これが、俺の望んだハッピーエンドだ。" },
  { fade: "white" },
  { hide: "all" },
  { cg: "cg_title_call" },
  { fade: "in" },
  { text: "最弱で無才だった俺は、多くの仲間に助けられ、最弱で無才のまま生きていく。もう才能の解放なんていうチート能力は無い。だから、今の俺は本当の意味で……" },
  { wait: 800 },
  { text: "――最弱無才のディザビリティだ。" },
  { cg: null },
  { fade: "out" },
  { comment: "→ 外伝=エピローグ章へ" },
  { jump: "ch08:moonlit_warehouse" },
]);
